declare changes jsonb:='[{"id":"d1090000-0000-4000-8000-000000000001","label":"M01","beforeHash":"b12c5cc2626024cdc3f21d7be9c249ec8bdef1384c8cbd44c539593dd3c1744d","afterHash":"d1081f9f64104f9b80622fc022c9c5b39ee3e941896c90d06bd050a0c7aae529","patch":{"difficulty":"medium","version":4}},{"id":"d1090000-0000-4000-8000-000000000002","label":"M02","beforeHash":"bb12ddc7e0447144ee07d01291142f16eed497a5cf1dd245d25837fca9913bb7","afterHash":"3fa91c7ba82bdc2ecc9ac089ef2668923937fac96d83b5198a8feb6d61bba428","patch":{"difficulty":"easy","version":3}},{"id":"d1370000-0000-4000-8000-000000000001","label":"M03","beforeHash":"f26d7efa27ae566eff7511506e189afdd852beec640f0f105ba575a9c4a1a80b","afterHash":"f34241cbde3a261dd788e048c6034a0d9d136d6c470934583ac39b45fffca744","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000002","label":"M04","beforeHash":"988e13a2fcf1d9d44236290e15f0d67d17371ac6e0f95cb03634bc67e03e36e6","afterHash":"1a099439cb8b1765accbff33339bab02f8dd412337a389df5d0f179f369d8d96","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000003","label":"M05","beforeHash":"a11d309a426c3610ebe22786b8429e2a4de913e6915c075547ef8bb8a5cda4a1","afterHash":"1ffba79faafa4e43cc1b72cedb9b4353b1251973b5a24e4047afc2ed9bcf33fb","patch":{"difficulty":"easy","version":4}},{"id":"d1370000-0000-4000-8000-000000000004","label":"M06","beforeHash":"8447d754480348bbd0071c5cba8bdba44c3cca273de3b0f36fb52d40e3b81372","afterHash":"9e0e7532f0bc499098fa5b56de7e6845e28d4585dd76a02ea3f450fa0381dc25","patch":{"difficulty":"medium","options":["3 ingressos","8 ingressos","6 ingressos","16 ingressos","10 ingressos"],"version":4}},{"id":"d1370000-0000-4000-8000-000000000005","label":"M07","beforeHash":"d6e61ae4d18b2d9ee7085c758226a8e30715bef145aab9bb1419e28a5a7df1af","afterHash":"ba7c9fc482726693387e47878af28a72a5505db05b3cdab658de6fa6e5ab570f","patch":{"difficulty":"medium","options":["7,9 pontos","8,5 pontos","8,2 pontos","7,15 pontos","7,3 pontos"],"version":5}},{"id":"d1370000-0000-4000-8000-000000000006","label":"M08","beforeHash":"6ecfabcced8046bbbf25794a8ae4417429140a8b8100d5b3dddf36dd003c75f5","afterHash":"95b83a2833656aac8da2ba357b6d7c8936130f6cfcfb9ac9235f51e9bde797fa","patch":{"difficulty":"medium","version":5}},{"id":"d1370000-0000-4000-8000-000000000007","label":"M09","beforeHash":"6014b9fe7b26d9ec9e753a493e2028e5dc3c5eeea3f94acce35125a1b7fed764","afterHash":"312cf57ba3a85d8fbf8e8bc306995c9b4e8f9104e43887e926743ff1a63e7545","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000008","label":"M10","beforeHash":"a0cf8fe63390b454d1138b62c78829059b651d4dbba6b46ee0d9cbb0b4863fa5","afterHash":"3c707c91959cebae8ebfb30b072b812c549b269ef687ee6216f7f76e208b7a11","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000009","label":"M11","beforeHash":"fa0b2e1198721ef11c674305717b81fe664a734c288c932c4b2253bc2d5b1196","afterHash":"84f85ae02e1ac948dea26f2619dec03837f5f70e49b63f971e197ff7cad20f41","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000010","label":"M12","beforeHash":"2333044134ec5454c3d7019edd0c5e282b96731d27704758320e88cccee784dc","afterHash":"d9157036551e1fd6635b8f09edc8adfc4e73c0540a41556e97a203b6bf89eaed","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000011","label":"M13","beforeHash":"f210106e51d42177a79fb6b833af9b4de91271fa027a2b1928836aff65c8be26","afterHash":"2534ed9fbe1705e1bf963475dbbe1a0d33dd2996a323fa243158d6d4d9ffdfce","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000012","label":"M14","beforeHash":"6efa3c5d2e57aee0c692670d9f81c3a8218b64911f3b4a024626897c3b51f6d6","afterHash":"2211d5ad0209357193875625365789768c940d40f3bb8c3ea24fcc67ae60b553","patch":{"difficulty":"medium","version":4}},{"id":"d1370000-0000-4000-8000-000000000013","label":"M15","beforeHash":"a8be7381a6327d169735f15816b0e99c6d968b6cc81d34fd6208b02969110d4a","afterHash":"9c53a39af66f4ec4d9da33e39db4fda764231e303fc6fd44861a96aecbb53cee","patch":{"difficulty":"medium","options":["120 L","80 L","140 L","40 L","160 L"],"version":4}},{"id":"d1370000-0000-4000-8000-000000000015","label":"M17","beforeHash":"9c72a4999cba7b11fc2f3015d81d343544dcc74eba2d847fffee6d6bc1c5494a","afterHash":"c4fcb84efb8bb86d7d5cf839f29a96d7d9fcba7f468acd039884fdf1a408466f","patch":{"difficulty":"medium","version":5}},{"id":"d1370000-0000-4000-8000-000000000016","label":"M18","beforeHash":"07dbab3f0dc6db38f6829326caf8d0e9224d4e6bfba249c9d106857c874b634f","afterHash":"6979bb682b1f8b236f7db6cfd80ad5d202e5537bbecffc0ebe2935fdf0f56fc0","patch":{"difficulty":"medium","version":5}},{"id":"d1370000-0000-4000-8000-000000000017","label":"M19","beforeHash":"58bec18576e4f89935a28bb3b0371380461597cb852d879214f8e4d96cba63ab","afterHash":"32e9bbb129dd816799f2749391041ce189cab8d3266857249b397b729f72dc91","patch":{"statement":"Uma campanha recolhe 8 kg de material no primeiro dia e aumenta o recolhimento em 3 kg a cada dia seguinte. Esse padrão continua por 10 dias. Quantos quilogramas são recolhidos nesse período?","version":4}},{"id":"d1370000-0000-4000-8000-000000000018","label":"M20","beforeHash":"ab04e7ee5dce880230b9397040ae42e82a0f66ad520665f32030faa2be5488ea","afterHash":"a3660ec93e7f144f670de25b3dae5ce250dd7e6fd4ac8fdf6e8ecf70e89db062","patch":{"difficulty":"medium","version":4}},{"id":"d1430000-0000-4000-8000-000000000021","label":"M21","beforeHash":"461d40a4ff306c42ac4d50c296c540edfb5dcc932590cf791002d36a278b4c1d","afterHash":"09b59ac186feb17f6cd5815ef54bcb4e53e5265453f33e7e7e642f55332de538","patch":{"difficulty":"medium","statement":"Uma associação arrecadou R$ 3.390. Separou uma reserva e gastou 2/3 do restante em materiais. Ao final, sobraram R$ 1.080. Qual valor havia sido separado como reserva?","options":["150 reais","2.310 reais","1.130 reais","510 reais","270 reais"],"explanation":"A sobra é 1/3 do valor após a reserva. Logo, esse valor era 3 × 1.080 = 3.240 reais. A reserva foi 3.390 − 3.240 = 150 reais.","version":3}},{"id":"d1430000-0000-4000-8000-000000000022","label":"M22","beforeHash":"7bcf29cb433d00feb840ebc18987f9c4b38858d0280f9bb27c49ac2592cd6845","afterHash":"3918b86a2ce85831784d2cb6a4b030f6dcf16981cbd66cf964c4b286f49f8a85","patch":{"difficulty":"medium","statement":"Após um aumento de 20% e um desconto de 20% sobre o valor reajustado, um equipamento passou a custar R$ 288. Qual era seu preço antes das duas alterações?","options":["240 reais","300 reais","288 reais","360 reais","320 reais"],"explanation":"As duas alterações multiplicam o preço inicial por 1,20 × 0,80 = 0,96. Assim, 288/0,96 = 300 reais. Aplicar porcentagens inversas por simples subtração não recupera a base original.","version":2}},{"id":"d1430000-0000-4000-8000-000000000023","label":"M23","beforeHash":"0ac95444026ac9cf14e630a23aadcbc34cab7ea8278fdb73429cb6f570bdb4c7","afterHash":"fee0bdf1e00ae9a457c107064ba6591b8e1cd97c94049e23e0e7d672b2fa64a1","patch":{"difficulty":"medium","statement":"Uma loja vende um produto por R$ 165 após um desconto. O mesmo produto, com preço de tabela de R$ 220, é vendido em outra loja com abatimento fixo de R$ 25. Qual percentual de desconto foi aplicado pela primeira loja?","options":["20%","33,3333%","25%","75%","11,3636%"],"explanation":"O desconto foi de 220 − 165 = 55 reais. Sua base é o preço de tabela: 55/220 × 100 = 25%. Os 25 reais da segunda oferta não determinam o desconto percentual da primeira.","version":2}},{"id":"d1430000-0000-4000-8000-000000000024","label":"M24","beforeHash":"1e1db81d9b1077fbeb23dc261352eab02f7c1a5f893d179305f9cde2a4a64d16","afterHash":"88f62a6d4994e2e3b9f378614b6f5b86ca9f877eb2ae3d5c278e9d296bfaa18e","patch":{"difficulty":"medium","statement":"Uma equipe de oito trabalhadores conclui uma tarefa em doze dias de seis horas. Outra equipe, de mesma produtividade individual, deve concluir tarefa idêntica em nove dias de quatro horas. Quantos trabalhadores são necessários na segunda equipe?","options":["18 trabalhadores","24 trabalhadores","16 trabalhadores","8 trabalhadores","12 trabalhadores"],"explanation":"A tarefa exige 8 × 12 × 6 = 576 trabalhador-horas. Cada trabalhador da nova equipe oferece 9 × 4 = 36 horas. Portanto, são necessários 576/36 = 16 trabalhadores.","version":2}},{"id":"d1430000-0000-4000-8000-000000000025","label":"M25","beforeHash":"c2b956f10757423293e4b851a97c96f4d72b5af4cd431f2f650debfec0fcdea4","afterHash":"030eb6b5bbdb9eadb198e3a980dbc878b07d16e67e0727491263a928065ebf92","patch":{"difficulty":"medium","statement":"O serviço A cobra R$ 28 fixos mais R$ 3 por quilômetro; o B, R$ 10 fixos mais R$ 5 por quilômetro. Uma pessoa dispõe de R$ 55 e escolhe A. Qual é a maior distância inteira que pode percorrer sem ultrapassar o orçamento?","options":["9 km","18 km","15 km","10 km","8 km"],"explanation":"A cobrança exige 28 + 3x ≤ 55. Assim, x ≤ 9 km. A verificação dá 28 + 27 = 55; a distância de igualdade entre A e B não é o critério pedido.","version":2}},{"id":"d1430000-0000-4000-8000-000000000026","label":"M26","beforeHash":"4dd640f89c25e91d18f6294aad12a6863ca3a096f255b75cd2c4e106c7341d8b","afterHash":"3c1d93f7bed7e00aa503b47af6935859b80daea119ffed99134d5a26bd7e3b87","patch":{"difficulty":"easy","statement":"Um evento vendeu 28 ingressos: 9 inteiros de R$ 18 e os demais reduzidos de R$ 10. Sem cortesias ou taxas adicionais, qual foi a arrecadação?","options":["280 reais","352 reais","344 reais","504 reais","360 reais"],"explanation":"Há 28 − 9 = 19 ingressos reduzidos. A arrecadação é 9 × 18 + 19 × 10 = 162 + 190 = 352 reais. Não se cobra o valor inteiro sobre todos os ingressos.","version":2}},{"id":"d1430000-0000-4000-8000-000000000027","label":"M27","beforeHash":"06983d9152b3e804d65a216a93a47f3aa444933e652d68d7801838656c7f744a","afterHash":"3aa44cf233ab31889f8e8c822df032c1bba4c30e43c4a9eb12110b1a1ef847bb","patch":{"difficulty":"medium","statement":"Quatorze avaliações de mesmo peso tiveram média 7,0. Outras três avaliações receberam nota 8,7 cada uma, numa escala de zero a dez. Qual é a média das dezessete avaliações?","options":["7,3 pontos","7,6 pontos","7 pontos","7,85 pontos","8,7 pontos"],"explanation":"A soma das notas é 14 × 7 + 3 × 8,7 = 124,1. Dividindo pelas 17 avaliações: 124,1/17 = 7,3. A média simples entre 7 e 8,7 ignora a quantidade de avaliações.","version":3}},{"id":"d1430000-0000-4000-8000-000000000028","label":"M28","beforeHash":"07bd85d972e18e72e9f724438ee9bf048d47571284803f9d7658052287bbc5c7","afterHash":"187a8030285bf39171312a35740647651b990e27e9b0a6befa935f424a0d1107","patch":{"difficulty":"easy","statement":"Uma turma de 25 estudantes teve 60% de presença em uma oficina. Outra turma de 35 teve 80%. Quantos estudantes estiveram presentes no conjunto das duas turmas?","options":["45 estudantes","43 estudantes","48 estudantes","60 estudantes","42 estudantes"],"explanation":"Na primeira turma, 25 × 0,60 = 15 estiveram presentes; na segunda, 35 × 0,80 = 28. O total é 15 + 28 = 43. Percentuais não devem ser somados diretamente como contagens.","version":3}},{"id":"d1430000-0000-4000-8000-000000000029","label":"M29","beforeHash":"fdabc012e8207fe6f93e3c34fc509d17e4d6e0c6b8b6ea4d9b8cbd7ea2f55237","afterHash":"31f6df5e81c51e73f70c15d4400e958fcbbdb3e1b974a025de98b3a050c2ada8","patch":{"difficulty":"medium","statement":"Uma caixa contém quatro fichas vermelhas e cinco azuis. Retiram-se duas fichas ao acaso, sem reposição. Sabendo que a primeira é vermelha, qual é a probabilidade de a segunda também ser vermelha?","options":["16,6667%","37,5%","62,5%","50%","44,4444%"],"explanation":"Após retirar uma ficha vermelha, restam três vermelhas em oito fichas. A probabilidade condicionada é 3/8 × 100 = 37,5%. Não se multiplica novamente pela chance da primeira, pois ela já é conhecida.","version":2}},{"id":"d1430000-0000-4000-8000-000000000030","label":"M30","beforeHash":"c6155396db4ed97ef88495f5b800e4037267fadf6c95c8ffc838e2f1e070f75e","afterHash":"a90f84e385cde339c808841dc2b6c752877b7a513e77a4fee46584c6475b5ec8","patch":{"difficulty":"medium","statement":"Entre 50 estudantes, 31 participam de robótica, 26 de teatro e 11 de nenhuma atividade. Quantos participam das duas atividades?","options":["11 estudantes","7 estudantes","39 estudantes","26 estudantes","18 estudantes"],"explanation":"A união dos grupos tem 50 − 11 = 39 estudantes. Como 31 + 26 = 57 conta duas vezes os participantes de ambos, a interseção é 57 − 39 = 18.","version":2}},{"id":"d1430000-0000-4000-8000-000000000031","label":"M31","beforeHash":"3c0dbbc240f897e061687e02194e5390e30527553aefaf097bda96505e965371","afterHash":"756f6609ea15400ca67cf0a36bc5b6da5857cc214efed91670ccd9f29d95aff0","patch":{"difficulty":"medium","statement":"Em um mapa de escala 1:30.000, dois pontos distam 6 cm em linha reta. Um percurso entre eles mede 2,25 km. Em quantos por cento o percurso supera a distância real em linha reta?","options":["125%","45%","80%","25%","20%"],"explanation":"A linha reta corresponde a 6 × 30.000 cm = 1,8 km. O acréscimo é 2,25 − 1,8 = 0,45 km. Dividindo pela base de 1,8 km: 0,45/1,8 × 100 = 25%.","version":2}},{"id":"d1430000-0000-4000-8000-000000000032","label":"M32","beforeHash":"d0b20dea60243f3b0312c1407029a03f4d9d5f5b9d3b3c5b67bd2ecc69045b71","afterHash":"c61e3535676904d93a25e61cbeab3a7b25a19c1ec5ee94a3dfdfe598c6b48665","patch":{"statement":"Um jardim mede 20 m por 13 m. Uma faixa interna de 1 m contorna seus quatro lados. O revestimento da faixa custa R$ 25 por metro quadrado. Qual é o custo, sem desperdício?","options":["1.550 reais","825 reais","6.500 reais","1.320 reais","1.650 reais"],"explanation":"O centro mede 18 × 11 = 198 m². A faixa ocupa 20 × 13 − 198 = 62 m². Seu custo é 62 × 25 = 1.550 reais. O cálculo deve descontar a faixa das duas extremidades de cada dimensão.","version":2}},{"id":"d1430000-0000-4000-8000-000000000033","label":"M33","beforeHash":"f27fd644281a45d9ec9052a942c88bfbd02d06d0160097b51f3582b4810bc3c4","afterHash":"b3b22706f72572644086a1654cc313225a119f9354949659abe64d9e5ee15939","patch":{"statement":"Uma rampa reta sobe 6 m e possui projeção horizontal de 8 m. Duas barras acompanham suas laterais inclinadas. Cada barra será montada com peças de 2 m, sem perdas. Quantas peças são necessárias para as duas laterais?","options":["8 peças","10 peças","5 peças","14 peças","20 peças"],"explanation":"Cada lado inclinado mede √(6² + 8²) = 10 m. As duas barras totalizam 20 m. Dividindo por peças de 2 m, obtêm-se 10 peças; altura e projeção não são somadas para achar o comprimento inclinado.","version":2}},{"id":"d1430000-0000-4000-8000-000000000034","label":"M34","beforeHash":"faf892bdb4abc13db9d6df1fdef4fba983568bb4c406fcbc24ec965e45aec07c","afterHash":"365a8e86125a1c8c98d7aea8982531ef061677bbef338fe05657d6ffbec97c94","patch":{"difficulty":"medium","statement":"No mesmo instante, uma haste vertical de 1,75 m projeta sombra de 2 m. Uma torre vertical tem 10,5 m de altura. Em terreno plano e sob raios solares paralelos, qual é o comprimento da sombra da torre?","options":["3,5 m","18,375 m","10,5 m","12 m","6 m"],"explanation":"A razão altura/sombra é a mesma: 1,75/2 = 10,5/x. A torre é seis vezes mais alta que a haste, então sua sombra mede 6 × 2 = 12 m.","version":2}},{"id":"d1430000-0000-4000-8000-000000000035","label":"M35","beforeHash":"c67f0d4bb32edd731b211b946f45cf0c2b48c494c0226017ed113460753cb5da","afterHash":"4662d6e6e10a189abe4f63b3102c18894b09ea4ba1e4c9bb6395627228ea58b1","patch":{"difficulty":"medium","statement":"Um reservatório retangular tem medidas internas de 100 cm × 50 cm × 40 cm. Há 50 litros de água nele. Quantos litros devem ser acrescentados para atingir 3/4 da capacidade? Use 1 L = 1.000 cm³.","options":["200 L","112,5 L","150 L","50 L","100 L"],"explanation":"A capacidade é 100 × 50 × 40/1.000 = 200 L. Três quartos correspondem a 150 L. Como já existem 50 L, devem ser acrescentados 150 − 50 = 100 L.","version":2}},{"id":"d1430000-0000-4000-8000-000000000036","label":"M36","beforeHash":"d6efe4df55ecadee764caf7bbdc375f6e9763ff98c1ff37451f670dca8b5ddef","afterHash":"a1ebb7064cb2337be3b1b2110f18e0873731c1975ac348acf8dceed12035d665","patch":{"difficulty":"medium","statement":"Uma ciclista percorre 30 km a 12 km/h e volta pelo mesmo trajeto a 18 km/h, sem paradas. Qual é a duração total, em minutos, aproximadamente?","options":["200 minutos","120 minutos","250 minutos","225 minutos","300 minutos"],"explanation":"A ida dura 30/12 = 2,5 h, ou 150 minutos. A volta dura 30/18 h, ou 100 minutos. O total é 250 minutos; a distância igual não implica tempos iguais.","version":3}},{"id":"d1430000-0000-4000-8000-000000000037","label":"M37","beforeHash":"91f88de3a7c74d387136b19fb4f51dd6c6a745dc1bd0b830175068c5c81f7a64","afterHash":"4b1a0696630d0a035efc53907f62c84549ea3b6bd07f8242fcf5c95c45affb44","patch":{"difficulty":"easy","statement":"Ao contornar um polígono regular, uma pessoa muda sua direção em 40° em cada vértice. Quantos lados tem esse polígono?","options":["4 lados","8 lados","6 lados","9 lados","12 lados"],"explanation":"Os giros externos de uma volta completa somam 360°. Como cada giro mede 40°, há 360/40 = 9 vértices e nove lados. O giro externo não é o ângulo interno.","version":3}},{"id":"d1430000-0000-4000-8000-000000000038","label":"M38","beforeHash":"e1377ba1287095fbaab19c27a891845cce8e934a7d5e2beb334909c97897e6ba","afterHash":"5b000895a9135845d81dc5c1886ece94b3f0a367e2cb4bdc9a4970dea32e2396","patch":{"difficulty":"medium","statement":"Oito participantes concorrem a dois cargos distintos: coordenador e secretário. Uma pessoa não pode ocupar os dois cargos. Quantas escolhas diferentes da dupla com cargos são possíveis?","options":["36 escolhas","28 escolhas","56 escolhas","16 escolhas","64 escolhas"],"explanation":"Há oito escolhas para coordenador e sete para secretário. Como os cargos são distintos, trocar as pessoas de cargo produz outra escolha. Portanto, 8 × 7 = 56, sem dividir por dois.","version":3}},{"id":"d1430000-0000-4000-8000-000000000039","label":"M39","beforeHash":"31837f571dbc0c3fc1c25d9d43e291e2656e7333081e7e43466e6c236b2992ff","afterHash":"3d16d17ecca20f20d32586c895190687bb589b6f41e21683993ca4f96e27387e","patch":{"difficulty":"medium","statement":"Uma campanha recolhe 10 kg no primeiro dia e aumenta o recolhimento em 3 kg por dia. Em qual dia o recolhimento diário chega pela primeira vez a 40 kg?","options":["14º dia","11º dia","12º dia","13º dia","10º dia"],"explanation":"No dia n, o total diário é 10 + 3(n − 1). Igualando a 40: 3(n − 1) = 30, logo n = 11. A quantidade de aumentos é um a menos que o número do dia.","version":2}},{"id":"d1430000-0000-4000-8000-000000000040","label":"M40","beforeHash":"237cd19bf7c6d50aa82edb4f1b27d316b14073190e6e5f2225f603c54de4db0e","afterHash":"13111df29ce1c9dc8663e761e5c42ccdadb431a895b987517ad31639ad22ae1f","patch":{"difficulty":"medium","statement":"Um sensor registrou nove medições com média 6. Outras quatro medições, todas iguais a 9,25, foram acrescentadas. Qual é a média das treze medições?","options":["7 unidades","6,5 unidades","8 unidades","9,25 unidades","7,625 unidades"],"explanation":"As nove primeiras somam 54; as quatro seguintes somam 37. A soma total é 91 e a média é 91/13 = 7. O peso dos dois grupos depende da quantidade de medições.","version":2}},{"id":"d1430000-0000-4000-8000-000000000041","label":"M41","beforeHash":"3d5df0e6f7f66f09560a7e544846a2d8cb00be1100b0145a162bf974c270c9aa","afterHash":"2142106477c285a51f00d8b60572d452e9b62edc2f20b2074d55f82d6adfef02","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000042","label":"M42","beforeHash":"7cb41da95ad636f09eb94d37c50e1ba7d70f6fbd301bba38e5a4d6def6640dc9","afterHash":"27c23d75163279bb67445b5c4aa16c489c97aff564db293b6ce70eeafb209ba6","patch":{"difficulty":"easy","version":2}},{"id":"d1430000-0000-4000-8000-000000000043","label":"M43","beforeHash":"dd66ecefef6da3779cf72cac464bdf2aea9af6bd558f06ade97d3439ad31e3b8","afterHash":"7b7d26be985e21da9ef358e1242ba5e9f8491f93e3bbce3f0b70936ec373bcbd","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000044","label":"M44","beforeHash":"f72e1077e681f17fa04a228f3f1d4683b1b0489f5149cf01180858c742ef19fe","afterHash":"f81c50ffaea348f43111fee2edc732e159ea8fb32559793f4ee2d2efd5a3ef79","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000045","label":"M45","beforeHash":"1b92d32022ebba47fb46747a87029f804314f861753fcc66520798f35ab9c624","afterHash":"876218379e06ca542bf50c0d595fdacdd8f5eed6f8723470e2d4c9eaf1715541","patch":{"difficulty":"easy","version":2}},{"id":"d1430000-0000-4000-8000-000000000046","label":"M46","beforeHash":"a8df1b1b6a570a0642a572b0d12e5e8839b1b4d6b8bacbeb5063c48e45793d5c","afterHash":"608777e6884539ee6aac1fe73377e9de47d824317b87f0cbf691b11d47a58e34","patch":{"difficulty":"medium","options":["10 ingressos","22 ingressos","8 ingressos","4 ingressos","12 ingressos"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000047","label":"M47","beforeHash":"4367ed4c9c3122dc7683d3b4be7acb2a88bd481e837f828e4bbd45f061c4de66","afterHash":"1b2f9755a1eceea5f0809e829ed25bcb3db2a23126324caaffe370842be5e18b","patch":{"difficulty":"medium","options":["8,9 pontos","7,15 pontos","8,6 pontos","7,3 pontos","8,3 pontos"],"version":3}},{"id":"d1430000-0000-4000-8000-000000000048","label":"M48","beforeHash":"9a3a286ca3966f1b9f0255c8dbdaf1fa68e2e33871ad37de73c05305e5030ab4","afterHash":"8f7112f7b66601f0b81baf58d13d91277e3fede8e650e4243803269f720370e7","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000049","label":"M49","beforeHash":"50dfcf20df717bb1409f6c062cd19ef981b4ad5a9f9155b86b223f975313885e","afterHash":"86bf23a0a9bf7407df8f7fcce1394d47c2bcc1941a12a6b422801da20d10a90f","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000050","label":"M50","beforeHash":"e27a3b0fd366e0bd08bf7ccbce47bc7f493cb9645af1923f1c41d5d66bd32a12","afterHash":"be9d3a00a487c417f2b44c1214c54f69a62b875a4572415c9416ddd9fdd5b209","patch":{"difficulty":"medium","options":["0 estudantes","12 estudantes","24 estudantes","50 estudantes","1 estudantes"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000051","label":"M51","beforeHash":"eedcd46a8c958fef66c80128f488c76e78746219d9b7ffc7c12d15687d149f60","afterHash":"fc4c5b2876d5c446002e849f10d3269f2dc51ee60d6cc109a101e184840d73e7","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000052","label":"M52","beforeHash":"9bb990659f9441d430e51d32531fee871a5955bb9f5f57f6204864fb49ca6c4b","afterHash":"5c09702528dcc338daae3e0174a7233088ed305cb7b92b9d38f7c67cf807daca","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000053","label":"M53","beforeHash":"5482a0e5c3b5dfff08fc9114fef061f7aaeb264fb6480504bfa4f5ace808ae90","afterHash":"1c3e57634e025421385522fc052f22394dab1a813ff8caf8bc75fb3d10bb3e55","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000054","label":"M54","beforeHash":"08f497db5939635e38e4701ca9096716e7280d2efa99e1edc6e6b92f6d99aefd","afterHash":"0c0eca255f2a222bb2d0a826f2714c03ff8ec2661b60ae43c3dc66819c6e3ae6","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000055","label":"M55","beforeHash":"f54b92af3fbc0908ebad09ba6b01832b99bcb3a2d8949415ab9f34349d1c3427","afterHash":"248cce793624c7f357f1026e3bc9168220822f99ccbcbfded37c5be0843c9843","patch":{"difficulty":"medium","options":["180 L","120 L","200 L","60 L","240 L"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000056","label":"M56","beforeHash":"2345ccbfb26bb339a4906a997480f0a90ca1c3eb53426e055a13e4ccc41977b0","afterHash":"2226e07fd30c69b39193bfe29d74bbeb7d077121e1fc53535241f92bc9b0edb0","patch":{"statement":"Uma ciclista pedala durante uma hora a 12 km/h e, em seguida, durante uma hora a 18 km/h. Sem paradas, qual é sua velocidade média nas duas horas?","options":["16 km/h","15 km/h","30 km/h","14,4 km/h","13,5 km/h"],"explanation":"A primeira etapa tem 12 km e a segunda, 18 km. São 30 km em duas horas: 30/2 = 15 km/h. Neste caso os tempos são iguais, de modo que a média aritmética das velocidades coincide com a velocidade média.","version":3}},{"id":"d1430000-0000-4000-8000-000000000057","label":"M57","beforeHash":"196e7790e7dd22c94e403cab6679b11c7359595e64ced0a3b0b6cb172367c101","afterHash":"b9e8dd0955ad7d8ed0b0ea9adcf14d842a6f6c1c7c226abe72bcb6a0a12e7f9f","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000058","label":"M58","beforeHash":"cbf9249aff784b47d18e86597255a201e94443dfd0020065c0a67b454b4fc507","afterHash":"21a4e91317666c41c8fb690b5ebdd1f233ca184bbf3b7e9c6b0f6e17373323a3","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000059","label":"M59","beforeHash":"ba440bab57c754d89a1ac568545d002cf17dcce41ed3dbd4ee8e70400505df80","afterHash":"807339a3af94d80a8f0cd9faaac1763597decd41fe31bc00f9bb1879344a3736","patch":{"difficulty":"medium","statement":"Uma campanha recolhe 5 kg no primeiro dia e dobra o recolhimento diário a cada dia seguinte. Quantos quilogramas são recolhidos ao todo nos quatro primeiros dias?","options":["80 kg","40 kg","45 kg","75 kg","20 kg"],"explanation":"As quantidades diárias são 5, 10, 20 e 40 kg. O total é 5 + 10 + 20 + 40 = 75 kg. O padrão é multiplicativo, diferente de acrescentar uma quantidade fixa por dia.","version":2}},{"id":"d1430000-0000-4000-8000-000000000060","label":"M60","beforeHash":"434504b8d9f211252e11d4a05760374f721b51562e02617c1777b2888e976162","afterHash":"56284d3302005dc5afb30cf45d9489559f85e391df3d7ecb87495648a2e91bc5","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000061","label":"M61","beforeHash":"34b5003b0ced8f4e2b0807806ce8aa5254d1ada8f1b28c4a7af9df2d931735bb","afterHash":"7cb65fca0a6fa02628727ac85387251ecc600729b669565edbc86f008a2901bb","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000062","label":"M62","beforeHash":"c68bd9fdb15b559c617827806b5c7876fb181014dc4cabeba05cf5eedc452f1a","afterHash":"cd9bdcece601a20ae967331c99f99c7fd285ce4565087b812dc4a0e1ca3264c7","patch":{"difficulty":"easy","version":2}},{"id":"d1430000-0000-4000-8000-000000000063","label":"M63","beforeHash":"d53b64480e336221e9c7f410534b51c064d253a185cb864dc899d30ef1a18a0f","afterHash":"41381909c06fa03436bb6ff86c8688eb1b12956571efa6111b3c10abde53925a","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000064","label":"M64","beforeHash":"676227869ee5ef31af34ff3330f327afac4d1e87c4f052c41951ef587a746c0b","afterHash":"502e0d73c1db100827c489909bb791dd95f7a07541fc228200804ec2bc31f157","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000065","label":"M65","beforeHash":"71c049ac286ff2cf05a5159c47690e8a346bac3e092c2a99ed0fa79c72f07651","afterHash":"4ae5fdb187ae0775c7aff6a797f8bb1306082430381a247f120592cccbe0c245","patch":{"difficulty":"easy","version":2}},{"id":"d1430000-0000-4000-8000-000000000066","label":"M66","beforeHash":"e4ace4f2279b6c39f3ec114192b5f49152813e20a6a1238e3df75f3f2b4a2561","afterHash":"999f8fc6216f9f1e557aa790616d40e38b4fba2e50b53b1b57ba543181b9ee0e","patch":{"difficulty":"medium","options":["25 ingressos","13 ingressos","11 ingressos","4 ingressos","9 ingressos"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000067","label":"M67","beforeHash":"2b36073b233ad6252437e2775450d12a96a73fada2f0d75123f4c23bef00908f","afterHash":"093f627a2f9c40f52fb9479577fbd7f7677bcd06218940eb337143e81bec73a0","patch":{"difficulty":"medium","options":["9,1 pontos","7,3 pontos","8,8 pontos","8,5 pontos","7,15 pontos"],"version":3}},{"id":"d1430000-0000-4000-8000-000000000068","label":"M68","beforeHash":"946f46296d30fa624d8c98f6985c4239fa569b490f1ffe2df7cdb3939afa77ed","afterHash":"58e570d8250e9fc44f4434c73306e5a2e64fab56116013c44ed4a8d4decb621f","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000069","label":"M69","beforeHash":"63d8702150ff5ac4d5b8d3cccac686e72e40a4f079bab22501f4b6aea563201f","afterHash":"24c4707109a98f795fceae78656d429307e4a04cc6bf9cd4bb3cbb8c9621b709","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000070","label":"M70","beforeHash":"95f7ce9d90d07faeb95fd56c0c7d2c6a6805e777d8734bd7b36d4afcff970de6","afterHash":"a774959750ec8ae5c6b3cc2d45c40e0c60e14b2eb3092877de76f2079309fa33","patch":{"difficulty":"medium","options":["27 estudantes","53 estudantes","0 estudantes","14 estudantes","13 estudantes"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000071","label":"M71","beforeHash":"2fe76110bbc0b0c63de07459896ac2b0bf98ac6ebc99ef0ca5a5788cd9d9aa7c","afterHash":"9fea184af8beeb637dda9ec92d501755ea8f6e43f326b337aee02a32ceb392fe","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000072","label":"M72","beforeHash":"968b8910dbc8b47ae19d2ea666dcea623f91464eaa23956b777f16f3c7724cb9","afterHash":"c04423a9503865eaf45e352b856560162d181ad6c39904affe277d58d994ca61","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000073","label":"M73","beforeHash":"6d92c9ff8f51a9428cc76963472fe37ad7345c6c4e59515da04b0c6b4f21f12b","afterHash":"363aca4b6e30d9994f43897a58fb196b53d2979472fedb8670a106bf5cd679bc","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000074","label":"M74","beforeHash":"04c8ad44a823984d0d59ce71dd8204e39e7bc3044b6501a1cd2c66ea143df194","afterHash":"a94faad3b28ca9bb7db4441c99824f8ab9f003771c41168ef4e95a6005ea1da0","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000075","label":"M75","beforeHash":"8340621cc9d60229fc1b8a5e5a29bcafbae3138d03ebd813013aa9a00c62c4f5","afterHash":"3b7fb2c9adc63aad4b59c8c397d8cf850202112a8c63c285bd038881f44b47e9","patch":{"difficulty":"medium","options":["280 L","70 L","140 L","210 L","230 L"],"version":2}},{"id":"d1430000-0000-4000-8000-000000000076","label":"M76","beforeHash":"9b54b23d8412a837964850011a6f366fd39c702bfb9a701cc327e5e156384ee8","afterHash":"ab13a11b089349412f36fa1d64530ec06fb6d325ab89b89b6afb8b7bc9e8281d","patch":{"statement":"Uma ciclista percorre 36 km a 12 km/h, faz uma parada de 30 minutos e percorre mais 18 km a 18 km/h. Qual é a velocidade média de toda a viagem, incluindo a parada?","options":["13,5 km/h","12 km/h","15 km/h","14,4 km/h","18 km/h"],"explanation":"O percurso total é 54 km. Os tempos são 36/12 = 3 h, 0,5 h de parada e 18/18 = 1 h, somando 4,5 h. A média é 54/4,5 = 12 km/h; ignorar a parada produziria 13,5 km/h.","version":3}},{"id":"d1430000-0000-4000-8000-000000000077","label":"M77","beforeHash":"5869f0297293ea2ddff112bbfd57e30600e63a7f4bf418d1cdb699570cbdef77","afterHash":"5c0816a0824d6bba1f5e72157b7520d9d32bf521c89a346363fb2ed8c9c29a0b","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000078","label":"M78","beforeHash":"320a4698b68079f6e8f0932f7b04a77d479b02d8be9364f292a9d983a5d62304","afterHash":"0bc0dc7320fd1f72dae0ede6adb372cd4ec54748287a90f79f34b376b4208e34","patch":{"difficulty":"medium","version":3}},{"id":"d1430000-0000-4000-8000-000000000079","label":"M79","beforeHash":"4da85379c2ebca18673ce558dcb96388a92a5264a3937404c5233db5fc5e1c5d","afterHash":"77e1110aded8843e18475c435b21a80270506aee3c57ae71f50910c0ff5774eb","patch":{"statement":"Uma campanha dura oito dias. A quantidade recolhida aumenta 3 kg por dia e o total acumulado é 164 kg. Quantos quilogramas foram recolhidos no primeiro dia?","options":["7 kg","21 kg","10 kg","20,5 kg","13 kg"],"explanation":"Se o primeiro dia tem x kg, o oitavo tem x + 21. A média dos oito termos é x + 10,5 e o total é 8x + 84. Igualando a 164, obtém-se 8x = 80 e x = 10 kg.","version":2}},{"id":"d1430000-0000-4000-8000-000000000080","label":"M80","beforeHash":"80306e05147b61c0789d190bcbbfa8858aa0c778f13888f1b27533a95d0daf1d","afterHash":"d01614cf062a11a31f0afc190d1373203b2ae9ba20243774f7cc4f054e01d5fb","patch":{"difficulty":"medium","version":2}},{"id":"d1430000-0000-4000-8000-000000000081","label":"M81","beforeHash":"443f93c2992bd7584ab5fb4b56d239b3b384853ac3c335296033f96961579517","afterHash":"30038aecd0d79b79f8fbfaa8c82720018e2679a6e6937966729b2fc5359e1fcc","patch":{"difficulty":"medium","statement":"Uma associação separa R$ 200 e usa 2/3 do restante em materiais. Um aluno afirma que a sobra equivale a 1/3 da arrecadação inicial. Por que essa afirmação pode estar incorreta?","options":["Separar a reserva muda a fração 2/3 para 1/2.","Toda reserva precisa ser maior que o gasto em materiais.","A fração foi aplicada ao valor após a reserva, e não à arrecadação inicial.","Subtrair uma quantia e aplicar uma fração produzem sempre o mesmo resultado em qualquer ordem.","A sobra inclui necessariamente os R$ 200 separados."],"explanation":"Após separar 200 reais de um total T, a base é T − 200. A sobra é (T − 200)/3, diferente de T/3. Identificar a base evita tratar a fração como aplicada ao total anterior.","version":3}},{"id":"d1430000-0000-4000-8000-000000000082","label":"M82","beforeHash":"f33e08ed1db001a5f1fac6751b29046ce3cba6edc551d7c978038945130fea29","afterHash":"74f816658fedb76cb64424982037782354df76dd117783a0e41cc8613ac8e355","patch":{"difficulty":"medium","statement":"Um produto recebe aumento de 20% e depois desconto de 20% sobre o novo preço. Para retornar ao preço inicial após o aumento, qual análise está correta?","options":["O desconto necessário seria de aproximadamente 16,7% sobre o preço aumentado.","Qualquer desconto inferior a 20% deixa o preço acima do original.","O desconto necessário seria de 20%, pois as taxas têm o mesmo número.","O desconto necessário seria de 24%, pois 20% deve ser multiplicado por 1,20.","O desconto necessário seria de 4%, pois esse é o resultado da sequência de 20% e 20%."],"explanation":"Após o aumento, o preço é 1,20P. Para recuperar P, o desconto d satisfaz 1,20P(1 − d) = P, então d = 1 − 1/1,20 ≈ 16,7%. A base do desconto é maior que a base do aumento.","version":2}},{"id":"d1430000-0000-4000-8000-000000000083","label":"M83","beforeHash":"b60fa258f7859ed7a495ee7c949ec0d21a1213e577382c943503af5e867ba8ce","afterHash":"938ffc60e545073d38e2cd1259c7f82a57ecd547b21b76006eecab3b685382f7","patch":{"difficulty":"medium","statement":"Duas lojas têm o mesmo preço de tabela P. Uma oferece desconto de 25%; a outra, abatimento de R$ 25. Em que situação a oferta percentual é mais barata?","options":["Quando P é maior que R$ 100.","Para qualquer P positivo, pois 25% sempre supera 25 reais.","Quando P é igual a R$ 25.","Quando P é menor que R$ 100.","Apenas quando P é exatamente R$ 100."],"explanation":"A oferta percentual custa 0,75P e a fixa custa P − 25. A primeira é mais barata se 0,75P < P − 25, isto é, 0,25P > 25 e P > 100. Em P = 100, as ofertas são iguais.","version":2}},{"id":"d1430000-0000-4000-8000-000000000084","label":"M84","beforeHash":"2b32d37a38afb735aae4960f2fc168a4f34a21213f7ed723d4694ced5676d62f","afterHash":"a55e843a249b252055a3c913047d2430a066787b8f3bfd8da0fa3b8deadc316e","patch":{"difficulty":"medium","statement":"Duas equipes realizam a mesma tarefa com produtividade individual constante. A segunda dobra o número de trabalhadores e reduz a jornada diária pela metade. Como muda o número de dias necessário?","options":["Aumenta em 50%, somando diretamente as mudanças percentuais.","Permanece igual, pois a quantidade de trabalhador-horas por dia é mantida.","Cai à metade, considerando apenas o número de trabalhadores.","Dobra, considerando apenas a jornada diária.","Cai a um quarto, multiplicando duas reduções de tempo."],"explanation":"Dobrar N e dividir h por dois mantém N × h por dia. Para o mesmo trabalho total, o número de dias é igual. Os dois fatores precisam ser considerados simultaneamente.","version":2}},{"id":"d1430000-0000-4000-8000-000000000085","label":"M85","beforeHash":"d7a158a080c29661aba87455520c736ef82bd796c0e2794182ba7c23e715e788","afterHash":"9fbd8a514c8bb6cbf21256296803fc918a14f263e7ba24eb68af183d3e0a96be","patch":{"difficulty":"medium","statement":"A tarifa A é 28 + 3x e a B é 10 + 5x, em reais, para x quilômetros. As cobranças são iguais em x = 9. Qual comparação vale para uma viagem de 12 km?","options":["A custa R$ 64 e B custa R$ 70; A é mais barata.","B é mais barata porque sua taxa fixa é menor, independentemente da distância.","As duas custam R$ 64, porque ficaram iguais em 9 km.","A custa R$ 70 e B custa R$ 64; B é mais barata.","A custa R$ 64 e B custa R$ 60; B é mais barata."],"explanation":"Para x = 12, A = 28 + 36 = 64 e B = 10 + 60 = 70. Acima de 9 km, a menor cobrança por quilômetro de A compensa sua taxa fixa maior.","version":2}},{"id":"d1430000-0000-4000-8000-000000000086","label":"M86","beforeHash":"ceb397347d56385f92df17bf77d034f98e4adcf7f4804b4a80e8e46a07515e96","afterHash":"d2c093368ceb98076e652ea3d744040cbbc89ea858b7f27f6330bee4f3eb173c","patch":{"difficulty":"medium","statement":"Um evento vende ingressos inteiros de R$ 18 e reduzidos de R$ 10. Há 24 ingressos vendidos. Um relatório afirma que 8 foram inteiros e a arrecadação foi R$ 320. Que avaliação verifica as duas informações?","options":["O relatório é compatível, pois há mais ingressos reduzidos que inteiros.","Não é possível verificar a arrecadação sem saber o nome dos compradores.","O relatório é incompatível porque o total arrecadado deveria ser R$ 240 em qualquer composição.","O relatório é compatível, pois 24 × 18 é maior que R$ 320.","O relatório é incompatível: 8 inteiros e 16 reduzidos totalizam R$ 304."],"explanation":"A composição indicada produz 8 × 18 + 16 × 10 = 144 + 160 = 304 reais. Estar entre o mínimo e o máximo possíveis não comprova que uma composição específica produz 320 reais.","version":2}},{"id":"d1430000-0000-4000-8000-000000000087","label":"M87","beforeHash":"24c97fc586a2a31219f730a3a5d4ff78c322c5e1a6dbd01f31f72401d92bf805","afterHash":"145f2d72b26d4856ba091ceaf28f4257940d5b91d63ba6d4ed8d4a2563f1b8e3","patch":{"difficulty":"medium","statement":"Dez avaliações têm média 7,0 numa escala de zero a dez. Pretende-se elevar a média a 8,0 acrescentando uma única avaliação. Qual é a conclusão?","options":["É possível com nota 10,0, pois toda nota máxima garante média 8,0.","Não é possível porque acrescentar qualquer avaliação sempre reduz a média.","É possível com nota 9,0, pois basta somar a diferença de uma unidade.","Não é possível nessa escala: a nova nota teria de ser 18.","É possível com nota 8,0, pois ela é a média desejada."],"explanation":"A soma atual é 70. Para onze avaliações com média 8, a soma teria de ser 88. A nota nova precisaria ser 88 − 70 = 18, fora da escala. Mesmo uma nota 10 produz média 80/11 ≈ 7,27.","version":3}},{"id":"d1430000-0000-4000-8000-000000000088","label":"M88","beforeHash":"f5b7a8aaaac3ef26e8fef7734b8a1209b34774146381bc41fb12a8318f14040c","afterHash":"05327233f9616841a3e9058f27d7fcbe30d059fc8d3c7e79beac2c968b13f105","patch":{"difficulty":"medium","statement":"Duas turmas tiveram 60% e 80% de presença. A média simples de 70% coincide com a presença conjunta em qual condição?","options":["Quando as duas turmas têm a mesma quantidade de estudantes.","Somente quando não houve nenhum estudante ausente.","Quando a turma de 60% tem o dobro de estudantes.","Sempre, porque porcentagens não dependem do tamanho dos grupos.","Quando a turma de 80% tem o dobro de estudantes."],"explanation":"A taxa conjunta pondera os percentuais pelo tamanho das turmas. Para taxas diferentes de 60% e 80%, o resultado fica exatamente no ponto médio de 70% quando os pesos são iguais.","version":3}},{"id":"d1430000-0000-4000-8000-000000000089","label":"M89","beforeHash":"5bfb0de966d47f1be8f87641307112e5694447fcc9e3b30caf9e6afa188e1328","afterHash":"04f6db6d9b8cd9d26f8b10054d8d6abff6ace2aa4b307c07d56129b12a63b2b1","patch":{"statement":"Uma caixa tem quatro fichas vermelhas e cinco azuis. Comparam-se duas retiradas sem reposição com duas retiradas recolocando a primeira ficha. Em qual caso é maior a chance de duas vermelhas?","options":["Sem reposição: retirar uma vermelha aumenta a fração de vermelhas restantes.","Sem reposição: a segunda retirada tem uma ficha a menos, independentemente da cor retirada.","Com reposição: a segunda retirada mantém quatro vermelhas entre nove fichas.","As chances são iguais porque a composição inicial é a mesma.","Com reposição: a primeira retirada passa a ter cinco vermelhas entre nove fichas."],"explanation":"Sem reposição, a chance é (4/9)(3/8) = 1/6. Com reposição, é (4/9)² = 16/81, maior que 1/6. Depois de uma vermelha, a fração de vermelhas restantes diminui se não houver reposição.","version":2}},{"id":"d1430000-0000-4000-8000-000000000090","label":"M90","beforeHash":"f15c577bd6a4a0aa24ded2450f4cb2f4be42db16f9a3bbd812282962c5f14e96","afterHash":"74dc6401722f340b73adb214cd532fda491832e6bf7ee55191c364ce356d2645","patch":{"difficulty":"medium","statement":"Uma pesquisa registra 31 participantes de robótica, 26 de teatro e 18 em ambas. Um aluno soma 31 + 26 para contar quem faz ao menos uma atividade. Qual correção é necessária?","options":["Subtrair 26, pois o grupo menor deve ser excluído da união.","Manter 57, pois cada participação equivale a uma pessoa diferente.","Somar novamente os 18, pois eles fazem duas atividades.","Dividir 31 + 26 por dois, pois existem dois grupos.","Subtrair os 18 participantes de ambas, pois foram contados duas vezes."],"explanation":"A união inclui cada pessoa uma vez. Os participantes de ambos aparecem na contagem de robótica e na de teatro, então a união é 31 + 26 − 18 = 39 pessoas.","version":2}},{"id":"d1430000-0000-4000-8000-000000000091","label":"M91","beforeHash":"bc552a700dcdde98868e5ed2a3edfd543820699bf98a21c0ed400e45ddf1d745","afterHash":"8a557ccfe58dafb17e0f7e439ad7ab85de11d13ffbcb1bdc86a6ab3aad327325","patch":{"difficulty":"medium","statement":"Um mapa é ampliado para o dobro de seus comprimentos no papel, sem alterar a região representada. Sua escala original era 1:30.000. Qual é a escala da cópia?","options":["1:15.000","1:30.000","1:120.000","1:60.000","1:7.500"],"explanation":"Com a mesma distância real, dobrar a representação no papel divide o denominador da escala por dois. O fator aplicado aos comprimentos não deve ser confundido com o fator quadrático das áreas.","version":2}},{"id":"d1430000-0000-4000-8000-000000000092","label":"M92","beforeHash":"26edc83972461db9cd3d16d0e628aa0d2ef0793fdae8b922238c6ad6beb3fc24","afterHash":"7fdca449a1fc3fe6d26bdb5717b95229469e72a44ec77116fe8d58c11d39163b","patch":{"difficulty":"medium","statement":"Um retângulo mede 20 m por 13 m e recebe uma faixa interna de 1 m nos quatro lados. Por que subtrair apenas 1 m de cada dimensão superestima a área central?","options":["Toda faixa de 1 m ocupa exatamente 1 m², qualquer que seja o retângulo.","A área central deve ser calculada pelo perímetro externo.","A redução de largura se aplica apenas aos dois lados maiores.","Cada dimensão perde 1 m em duas extremidades, totalizando redução de 2 m.","A faixa aumenta o comprimento externo do retângulo em 1 m."],"explanation":"A dimensão de 20 m fica em 18 m e a de 13 m em 11 m. Subtrair somente 1 m considera a faixa em uma extremidade de cada dimensão, deixando parte da faixa contada como área central.","version":2}},{"id":"d1430000-0000-4000-8000-000000000093","label":"M93","beforeHash":"2e1cbed44a624b8d6c1b5bf53c3df570a4338697bf60c43b49b004a2f0c7c3ce","afterHash":"313c84121a58e69f73d7f12579d0ac90e00a5aaf4bfca4b2638376a196c96100","patch":{"difficulty":"medium","statement":"Uma rampa sobe 6 m em uma projeção horizontal de 8 m. Um aluno compra 14 m de barra para uma única lateral, somando altura e projeção. Qual avaliação está correta?","options":["Ele comprou a medida exata, pois os dois catetos devem ser somados.","Ele comprou 8 m a mais: a lateral mede apenas 6 m.","Ele comprou 4 m a mais: o comprimento inclinado é 10 m.","Ele comprou 2 m a menos: a lateral mede 16 m.","Ele comprou 6 m a mais: a lateral mede apenas 8 m."],"explanation":"A lateral é a hipotenusa de um triângulo retângulo: √(6² + 8²) = 10 m. Comprar 14 m excede a necessidade em 4 m. A soma dos catetos descreve outro percurso, não a lateral inclinada.","version":2}},{"id":"d1430000-0000-4000-8000-000000000094","label":"M94","beforeHash":"e7579ae18797015eb0e9e489999186a0e992c809d05e569aec250c3f108bd12d","afterHash":"023f26cc9f5ba3b00f40de06e17029eb6f2eaf945b50c450770e4411c2b06cd3","patch":{"difficulty":"medium","statement":"Um técnico usa sombras para comparar a altura de uma haste com a de uma torre. Qual mudança pode invalidar a semelhança usada no cálculo?","options":["Manter haste e torre verticais no mesmo terreno plano.","Medir sombras de comprimentos diferentes no mesmo instante.","Medir a sombra da haste de manhã e a da torre em outro horário, quando a inclinação solar mudou.","Usar uma haste mais baixa que a torre, mantendo as demais condições.","Usar metros para expressar ambas as alturas e sombras."],"explanation":"A proporcionalidade pressupõe a mesma inclinação dos raios solares. Horários diferentes podem produzir ângulos diferentes. Tamanhos distintos e uso consistente de unidades não invalidam por si só a semelhança.","version":2}},{"id":"d1430000-0000-4000-8000-000000000095","label":"M95","beforeHash":"c31cce97e2ed9ab6a8cb89eac21d85065ca135cc1dcaddadd64174390e677137","afterHash":"c33978ae367cc0bd17e03a988fe80d10b45328c38b64da2ed2a91eb1c43629b9","patch":{"difficulty":"easy","statement":"Um reservatório retangular passa a ter o dobro do comprimento, mantendo largura e altura. Qual mudança ocorre em sua capacidade?","options":["Fica quatro vezes maior, confundindo volume com área de duas dimensões.","Permanece igual, pois a largura e a altura não mudaram.","Aumenta apenas dois litros, independentemente das medidas originais.","Dobra, pois apenas uma das três dimensões foi multiplicada por dois.","Fica oito vezes maior, como se as três dimensões tivessem dobrado."],"explanation":"O volume é comprimento × largura × altura. Dobrar apenas o comprimento multiplica o produto por dois; o fator oito só ocorreria se as três dimensões fossem dobradas.","version":2}},{"id":"d1430000-0000-4000-8000-000000000096","label":"M96","beforeHash":"d0b0e7d182a3c2c962b5399251151dc5803bf9554f3ea737be97f6814e67c0fb","afterHash":"487f595c7eda600d9b81b7e6a1eba8002583454b7db346462c692500925662b9","patch":{"difficulty":"medium","statement":"Uma ciclista faz ida e volta por trechos de mesmo comprimento, a 12 km/h e 18 km/h, sem paradas. Por que a média aritmética de 15 km/h não é a velocidade média da viagem?","options":["Trechos de comprimentos iguais têm necessariamente durações iguais.","A velocidade média deve ser sempre a menor das duas velocidades.","A velocidade média deve ser sempre a soma das duas velocidades.","O trecho de 18 km/h exige mais tempo, pois a velocidade é maior.","Ela permanece mais tempo no trecho de 12 km/h; a média depende do tempo total."],"explanation":"Velocidade média é distância total dividida pelo tempo total. Para a mesma distância, o trecho mais lento dura mais. O resultado é 14,4 km/h, inferior à média aritmética de 15 km/h.","version":3}},{"id":"d1430000-0000-4000-8000-000000000097","label":"M97","beforeHash":"87d178eb344cc3c90e7e5ff0b72319fc6c1043add183a652b8b12e2d36e67711","afterHash":"d0bff9d0b22b1610f256582c2632f70ad6724b35ba42f9756583b485ea6df496","patch":{"difficulty":"medium","statement":"Um polígono regular tem nove lados. Um aluno usa 360°/9 para calcular seu ângulo interno. Qual correção é adequada?","options":["40° é o ângulo externo; o interno mede 180° − 40° = 140°.","40° é o interno, pois os ângulos internos de qualquer polígono somam 360°.","O interno mede 180°/9 = 20°, sem considerar o número de triângulos.","O interno mede 40°/9, pois ainda é necessário dividir pelos lados.","O interno mede 360° − 40° = 320°."],"explanation":"O giro externo de uma volta completa soma 360°, produzindo 40° por vértice. Em um polígono convexo, interno e externo adjacentes são suplementares, então o interno mede 140°.","version":3}},{"id":"d1430000-0000-4000-8000-000000000098","label":"M98","beforeHash":"96906ec518b6583ad141886046fa3ba5d100589793ce80354af1cfdfba86a34c","afterHash":"14ca52afc6193d4c5022aa9ca6be09ba53ec3a1824299e2c55102dadfa8a2405","patch":{"difficulty":"medium","statement":"Oito pessoas serão escolhidas para uma comissão de duas pessoas sem cargos. Por que 8 × 7 precisa ser dividido por dois?","options":["Porque os cargos da comissão são diferentes.","Porque somente metade das pessoas pode participar da comissão.","Porque cada dupla aparece em duas ordens, que representam a mesma comissão.","Porque existem quatro pessoas em cada dupla.","Porque uma pessoa pode ser escolhida duas vezes."],"explanation":"A contagem ordenada inclui, por exemplo, Ana–Bruno e Bruno–Ana. Sem cargos, essas duas ordens são o mesmo grupo; cada comissão foi contada duas vezes. O total correto é 8 × 7/2 = 28.","version":3}},{"id":"d1430000-0000-4000-8000-000000000099","label":"M99","beforeHash":"c26dea4e0c707800fa805f636c50e9023d229613535481a2b400d5be62211a61","afterHash":"9d5b4ebad15f2e30ed88caa635d8201026fd9a69f3c09c034eb6758a40ebcf69","patch":{"difficulty":"medium","statement":"Uma campanha começa com 10 kg e aumenta 3 kg por dia. Um aluno calcula o recolhimento no 11º dia por 10 + 11 × 3. Qual correção é necessária?","options":["Multiplicar 10 × 11 × 3 para obter o recolhimento do 11º dia.","Usar doze aumentos, somando uma vez pelo primeiro dia.","Usar dez aumentos: 10 + (11 − 1) × 3 = 40 kg.","Usar 10 + 3, pois o aumento se aplica uma única vez.","Subtrair 3 do valor inicial a cada dia, pois o período avança."],"explanation":"O primeiro dia já tem 10 kg, antes de qualquer aumento. Do primeiro ao 11º dia existem dez passos de 3 kg, portanto 40 kg. Usar onze aumentos desloca a sequência em um dia.","version":2}},{"id":"d1430000-0000-4000-8000-000000000100","label":"M100","beforeHash":"a140c17af72e2cd18e434f1d74689a90cc0f3c99cc107ec3aff7335c3a27278b","afterHash":"63664051d6c0bf84ec3f11991ef8b664be72ec3567fb13104cf7a1d4fad57b61","patch":{"difficulty":"medium","statement":"Uma série tem nove medições de média 6. Uma segunda série tem quatro medições de média 9,25. Por que a média conjunta não é (6 + 9,25)/2?","options":["As séries têm quantidades diferentes de medições e precisam de pesos 9 e 4.","O peso deve ser dado apenas à série com média maior.","Médias de séries diferentes nunca podem ser combinadas.","O valor 9,25 deve ser arredondado para 6 antes de calcular.","A soma das duas médias já corresponde à média conjunta."],"explanation":"A média conjunta é a soma total dividida pelo número total: (9 × 6 + 4 × 9,25)/13 = 7. Dar pesos iguais aos dois grupos faz cada medição do grupo menor contar mais.","version":2}},{"id":"d1090000-0000-4000-8000-000000000003","label":"P01","beforeHash":"f5ab1f66a619190480de2167a199b41e4d785244b6dbb84c23d2e1ef5ad49b73","afterHash":"80de09fac758efeb0820b0785d34a5d1a868331fa19e0fd463d1868de37f354c","patch":{"difficulty":"medium","statement":"A biblioteca ampliou o horário. Em dois meses comparáveis, os empréstimos passaram de 800 para 1.100, mas o número de usuários distintos permaneceu em 200. A direção comemorou a circulação maior; o conselho solicitou os registros de novos cadastros. Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Os empréstimos subiram de 800 para 1.100, mas continuam sendo 200 usuários distintos. O aumento mede circulação de livros, não demonstra que mais pessoas passaram a usar a biblioteca.","version":4}},{"id":"d1090000-0000-4000-8000-000000000004","label":"P02","beforeHash":"0f5e690fda548bfdbbf8308d636ab5ebcc90631e66ff678d663e18838ad09676","afterHash":"e8c7a0708efcf78f66ac7786fb375a21b39e168cb3bcaaca77da2ac1cc7eaaef","patch":{"statement":"Depois que uma rua recebeu ciclovia, as vendas de duas lojas aumentaram. No mesmo mês, abriu uma estação de transporte e ocorreu uma feira comercial. Um lojista declarou: Foi a ciclovia que trouxe o crescimento. O levantamento apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Ciclovia, estação e feira aparecem no mesmo período. Sem comparação que separe essas mudanças, o aumento das vendas não pode ser atribuído exclusivamente à ciclovia nem usado para negar qualquer contribuição dela.","version":4}},{"id":"d1380000-0000-4000-8000-000000000001","label":"P03","beforeHash":"1ce3d1b998c46f44f12400eadce910fee6cc96a85758641cf88faa5fe72788e1","afterHash":"843abff805eb7bef2f903a8c947bdca410af98bb655cceae064c15901472917e","patch":{"statement":"O aplicativo prometia devolver tempo aos passageiros. Lara passou a consultar a previsão a cada minuto. Quando o ônibus atrasou, recebeu seis notificações de que o horário era estimado. Ela comentou: Que economia de tempo, agora preciso acompanhar o atraso em tempo real. Os colegas riram, mas continuaram na fila esperando o veículo.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"A promessa era poupar tempo, mas Lara consulta o aplicativo repetidamente e continua esperando. O aparente elogio ao acompanhamento do atraso produz ironia por esse contraste.","version":5}},{"id":"d1380000-0000-4000-8000-000000000002","label":"P04","beforeHash":"8f8867a22cf4c9379d0d82d79edadc0720005ca74ffeee80af645c15816cad9d","afterHash":"f6d9aa94413b59699960e9d7ba6c90a6fd2b456e4adc601d0b0adddd9a092bce","patch":{"statement":"Um estudo acompanhou hortas em três escolas e registrou relatos de maior interesse por alimentação. Os autores escreveram: A atividade pode favorecer esse interesse, embora o grupo não represente todas as escolas. A notícia foi publicada com o título Hortas garantem mudança alimentar. O texto da reportagem não acrescentava observações sobre os hábitos alimentares posteriores.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"O estudo usa pode favorecer e limita a abrangência a três escolas. O título emprega garantem e muda interesse por alimentação para mudança alimentar, ampliando certeza e alcance sem novos dados.","version":5}},{"id":"d1380000-0000-4000-8000-000000000003","label":"P05","beforeHash":"022749a325b8fe04306413101031ef94cb6d05e8d06f230955018c7d809029ba","afterHash":"542c235cf6aa4b2399da3729553ed9ef746e555bacadfa755b57ea4d13d5ddc0","patch":{"difficulty":"medium","statement":"No debate sobre a praça, o vereador afirmou: Precisamos voltar a ouvir os moradores. Uma participante perguntou quando havia ocorrido a escuta anterior; outra perguntou se ela havia sido ampla ou apenas formal. O registro da reunião não traz resposta a essas perguntas.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Voltar a ouvir apresenta a escuta como retomada. Essa pressuposição linguística não demonstra quando, como ou quantos moradores foram ouvidos; por isso as perguntas da participante continuam pertinentes.","version":5}},{"id":"d1380000-0000-4000-8000-000000000004","label":"P06","beforeHash":"7266e82d9b05d699b0c88af502ceff01ec02073820eefdd12f3efa675d336ccb","afterHash":"7e1960371830afd7fe117a8ce38fcfc3fafa539d1558ddfa983b15974f6feb75","patch":{"difficulty":"easy","statement":"A escola instalou painéis informativos e distribuiu mapas do bairro. Os primeiros ficaram próximos aos portões; os segundos foram entregues aos estudantes. Visitantes consultavam os painéis para localizar a entrada. Ainda assim, os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos indicados.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"A ordem de menção é painéis e depois mapas. Assim, primeiros retoma painéis e segundos retoma mapas. As obras alteram os caminhos, justificando atualização dos dois recursos.","version":5}},{"id":"d1380000-0000-4000-8000-000000000005","label":"P07","beforeHash":"540f0a3880977af528119475673b311c6c3afb2ef2f0798865fc6f8589a7d7e9","afterHash":"c4743384c67a3b0a6b961ac6908c1717709539688f2739a0bc0cd431b543cfe2","patch":{"statement":"Um fabricante informou que sua embalagem usava 20% menos plástico. Uma cooperativa observou que ela combinava materiais difíceis de separar nos equipamentos disponíveis. O relatório final pediu uma avaliação da produção e da destinação, sem apresentar um único indicador como resposta para todas as etapas.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Usar menos plástico é um indicador de produção; separar materiais é uma condição da reciclagem. A redução de 20% informada não elimina a dificuldade indicada pela cooperativa.","version":5}},{"id":"d1380000-0000-4000-8000-000000000006","label":"P08","beforeHash":"5d4900af29984d562339354c4eb321bb5f4bc4b53a9a6ca2ca95b07332fe4731","afterHash":"af63bdc87f033260854399efa7bf01a8376e49db79cdc98bfd0e8ad6ff90cbcb","patch":{"difficulty":"medium","statement":"O conselho apoiou a finalidade de ampliar a acessibilidade, mas contestou a sequência proposta para a reforma: a única passagem seria fechada antes de a alternativa ficar pronta. Para os conselheiros, o plano deveria manter uma rota durante toda a obra. A empresa respondeu que reorganizaria as etapas.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"O conselho declara apoio à acessibilidade, mas identifica fechamento antes de haver rota alternativa. A crítica é à sequência que deixaria pessoas sem passagem, não ao objetivo da reforma.","version":5}},{"id":"d1380000-0000-4000-8000-000000000007","label":"P09","beforeHash":"88b2fe4a8d106bdff835f0411b52593bc29702e18f8cb472331a52254f90910e","afterHash":"fae5a556fb49ca059d1e23e4a6713ec768a60b43aae5b1586e8dfc4637d39b19","patch":{"statement":"Enquanto os convidados discutiam o prêmio, o porteiro reorganizava as cadeiras. Conhecia cada nome das placas, mas não aparecia nas fotografias. Ao final, encontrou no chão uma medalha de participação e a pendurou no uniforme. O relato encerra-se com essa ação, sem registrar fala ou pensamento do porteiro.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"O porteiro encontra e usa a medalha, mas não há fala ou pensamento registrado que revele sua intenção. A busca de reconhecimento é uma leitura possível, não um fato comprovado ou uma homenagem oficial.","version":5}},{"id":"d1380000-0000-4000-8000-000000000008","label":"P10","beforeHash":"03d2069563d66e7c01f881ead305e1cc9208f488df8300c62832b147978dadec","afterHash":"7ad6d00266d91dd4d2f831c8e0209c488d7d1efaf176b0a87b6db3d49d3113b8","patch":{"statement":"Uma enquete foi divulgada apenas no perfil de um clube. Entre as 300 respostas, 240 apoiavam ampliar sua sede. O anúncio dizia: A cidade aprova o projeto. A cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores do perfil se distribuíam entre bairros nem quem decidiu responder.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Entre 300 respondentes, 240 apoiam o projeto: 80% das respostas. A enquete no perfil do clube não demonstra que esses respondentes representem os 40 mil moradores; o percentual não pode ser generalizado à cidade.","version":5}},{"id":"d1380000-0000-4000-8000-000000000009","label":"P11","beforeHash":"4415ac42745989d283557268533f8b13196fa48923d637e191d068afb32a8bdc","afterHash":"c587c43ff5bf9c8baede879da25c396216c21b512a3aba632c5105f8957ef0ec","patch":{"difficulty":"medium","statement":"A comissão pediu que a proposta financeira fosse revista. Ao comentar um passeio, uma aluna disse que queria rever a cidade. Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento e a situação de cada ocorrência.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Na proposta financeira, rever indica reexaminar; no contexto do passeio, indica ver ou visitar novamente. O complemento e a situação orientam a diferença de sentido do mesmo verbo.","version":5}},{"id":"d1380000-0000-4000-8000-000000000010","label":"P12","beforeHash":"a653f1b0013aba1aeac4463d58b00a6611a9f133168d6b8885c1573e2cb24357","afterHash":"a6305c696e18d3614fc135375db1d55c75a039bd79650828e5dd879dbf7962f6","patch":{"difficulty":"medium","statement":"Um comunicado dizia: Os moradores que solicitaram vistoria receberão resposta. Outra versão dizia: Os moradores, que solicitaram vistoria, receberão resposta. As palavras eram as mesmas, porém a equipe precisava decidir se o aviso se referia apenas aos solicitantes ou ao conjunto dos moradores mencionado no documento.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Sem vírgulas, que solicitaram vistoria restringe o grupo a solicitantes. Com vírgulas, a oração é explicativa e apresenta a solicitação como informação sobre o grupo mencionado.","version":5}},{"id":"d1380000-0000-4000-8000-000000000011","label":"P13","beforeHash":"00515eb576df3849adc159415be12a07759e4794e4221414fc16cb74b2423b04","afterHash":"1ab10779313c1b80072c9c0da606a16abee5fd510a164a5a875294f1fdcba304","patch":{"difficulty":"medium","statement":"A nota dizia: Foram eliminados os registros duplicados. O relatório posterior dizia: A equipe de cadastro eliminou os registros duplicados. Embora os documentos tratassem da mesma ação, uma solicitação de prestação de contas pedia também a identificação de quem a executou.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Foram eliminados expressa voz passiva sem nomear quem agiu. A segunda versão nomeia a equipe. Omissão do agente e intenção de ocultá-lo não são equivalentes: a finalidade não é demonstrada pelo primeiro período.","version":5}},{"id":"d1380000-0000-4000-8000-000000000012","label":"P14","beforeHash":"2149a6815a04aa55653f7d64617c88a7491b6e38866d1f5249362a83d2ced282","afterHash":"747258ff80f1defed866aabd638ad47f530547f9e64e574d69a4927ec0958c45","patch":{"difficulty":"medium","statement":"Uma editora encontrou no relatório: Fazem três meses que o projeto começou. Na página seguinte, leu: Houveram alterações no cronograma. Ela pediu a revisão das formas verbais, e não apenas a troca dos termos meses e alterações por palavras no singular.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Fazer indica tempo decorrido e haver indica existência. Nesses sentidos, são impessoais e ficam no singular: Faz três meses e Houve alterações. Meses e alterações não exigem plural desses verbos.","version":5}},{"id":"d1380000-0000-4000-8000-000000000013","label":"P15","beforeHash":"13a4913d700fd1e207aa6466506b0238fdca2f78e87f01a7b8bf1b886fff997f","afterHash":"be9907213a2c20e969b8033e7cbceb8b50bccf47b9234aece41b829fcabeb462","patch":{"difficulty":"medium","statement":"No relatório, constavam: Os estudantes assistiram o documentário e O técnico assistiu o pesquisador durante o procedimento. A primeira frase tratava da exibição de um filme; a segunda, da ajuda prestada no laboratório. A revisora avaliou a regência de assistir no sentido de cada ação descrita.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Assistir no sentido de presenciar rege a: assistiram ao documentário. No sentido de ajudar, admite objeto direto: assistiu o pesquisador. A acepção orienta a regência.","version":5}},{"id":"d1380000-0000-4000-8000-000000000014","label":"P16","beforeHash":"535addb47f6aad60e99d1045735a2ebd3b854b165c194b6bc56d9de3d5367513","afterHash":"90dca9b306bd7d7e5eec4ae59d2eebe81728eed0cf330b19829a1077b3d220d9","patch":{"difficulty":"medium","statement":"A ficha registrava: Entregou o documento à diretora. Outra registrava: Entregou o documento a uma diretora. Uma estudante propôs pôr acento grave nas duas, mas a editora pediu que ela comparasse os artigos e a preposição exigida pelo verbo.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Em à diretora, unem-se a preposição a e o artigo definido a. Em a uma diretora, há preposição e artigo indefinido uma, sem o mesmo encontro que produziria o acento grave.","version":5}},{"id":"d1380000-0000-4000-8000-000000000015","label":"P17","beforeHash":"8d5df1ec11d0789dbb5f79708a2ef8c33747e9fce5206a7321932c3c656f689e","afterHash":"31c92eb1f74cb4eb6ecc975f356d5677df88ec4e6cc025de05b3752141a19b13","patch":{"difficulty":"medium","statement":"O jornal publicou: A professora informou à aluna que sua inscrição estava incompleta. Um leitor perguntou de quem era a inscrição. O redator substituiu “sua inscrição” pela expressão “a inscrição da aluna” e manteve o restante da informação. A alteração passou a constar na edição seguinte.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Sua inscrição pode ser interpretada como inscrição da professora ou da aluna. Nomear a inscrição da aluna explicita o possuidor pretendido, mantendo o estado de incompletude informado.","version":5}},{"id":"d1380000-0000-4000-8000-000000000016","label":"P18","beforeHash":"c175cdf8bb75cf012f5f3a77df158c119452221e4715de44fac938a94d441f19","afterHash":"c9427016d396eafa0808e4bc2af1f6632a859842ab1cefa8c6fcbf4b4179821d","patch":{"difficulty":"medium","statement":"O editorial chamou a falta de planejamento de um buraco no orçamento. Na sequência, apresentou receitas e despesas para dimensionar o problema. Um leitor destacou a imagem expressiva, mas outro pediu que a avaliação se baseasse também nos valores documentados.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Buraco no orçamento é uma imagem expressiva de insuficiência ou problema. Para avaliar a dimensão, são necessários os valores de receitas e despesas; a metáfora não fornece esse número.","version":5}},{"id":"d1380000-0000-4000-8000-000000000017","label":"P19","beforeHash":"9d3a265fdb333c0b8d7fb448a055d4c444df53fb141592bb0a8976d0a7d38e6f","afterHash":"ccba094ddf65bde03bfe722d245c0b1da6f9192ae93aebe083ba7840a1cc9035","patch":{"statement":"A notícia dizia: Segundo a pesquisadora, o material pode reduzir perdas. Na edição seguinte, apareceu: O material reduz perdas. A mudança retirou palavras da frase, sem acrescentar dados ou resultados ao conteúdo publicado.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Segundo a pesquisadora atribui a informação a uma fonte, e pode reduz o grau de certeza. Ao retirar os dois elementos, a notícia apresenta a conclusão de forma mais assertiva sem acrescentar evidência.","version":5}},{"id":"d1380000-0000-4000-8000-000000000018","label":"P20","beforeHash":"61fbd144bad299c1beca847e41aa07e0aa296a1d22bffa201fce91598a816a2f","afterHash":"e2585bb5e6cf04e675c3d006a664ef94258d1c05d470b97061668489eeaf1990","patch":{"difficulty":"easy","statement":"O regulamento dizia: A inscrição só será aceita se o formulário estiver completo e o comprovante for enviado. Rui preencheu o formulário, mas não enviou o comprovante. A equipe recusou o pedido. Uma colega sugeriu que ele relesse os dois requisitos antes de reclamar.\n\nConsiderando o que é afirmado e o que permanece apenas como hipótese, qual interpretação é sustentada pelo texto?","explanation":"Os dois requisitos são necessários em conjunto. Rui cumpriu o formulário, mas faltou o comprovante, portanto não satisfaz a condição exigida. Isso não demonstra que o formulário estava incompleto.","version":5}},{"id":"d1431000-0000-4000-8000-000000000021","label":"P21","beforeHash":"37faf8a0d8e449f1bd9c28d49eb67c9b3d088c87c72758caf6167d3c117de3e6","afterHash":"f417eb1ad2793ad0b5b0e742474ff78cbb1db115af4ec87bff023c070bfbeb49","patch":{"difficulty":"easy","statement":"A biblioteca ampliou o horário. Em dois meses comparáveis, os empréstimos passaram de 800 para 1.100, mas o número de usuários distintos permaneceu em 200. A direção comemorou a circulação maior; o conselho solicitou os registros de novos cadastros. Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais.\n\nEm “Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais”, qual reescrita mantém a relação concessiva?","options":["Se destacar o crescimento, o relatório não informará quem fez os empréstimos adicionais.","Como destaca o crescimento, o relatório não informa quem fez os empréstimos adicionais.","O relatório destaca o crescimento porque não informa quem fez os empréstimos adicionais.","Apesar de destacar o crescimento, o relatório não informa quem fez os empréstimos adicionais.","Para destacar o crescimento, o relatório não informa quem fez os empréstimos adicionais."],"explanation":"Embora introduz uma informação que não impede o fato da oração principal. Apesar de mantém a concessão; causa, finalidade e condição alteram a relação.","version":3}},{"id":"d1431000-0000-4000-8000-000000000022","label":"P22","beforeHash":"db1ef2d4785d560ecc229aceceef1ded4ff4d20e36eef80ef6ada6ddd81ca251","afterHash":"defac132b1f8a2612bf62f3d14d4db212aecafbde81731417f6b5fafc0a1e08a","patch":{"statement":"Depois que uma rua recebeu ciclovia, as vendas de duas lojas aumentaram. No mesmo mês, abriu uma estação de transporte e ocorreu uma feira comercial. Um lojista declarou: Foi a ciclovia que trouxe o crescimento. O levantamento apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes.\n\nEm “apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes”, porém introduz qual relação?","options":["Uma finalidade que explica por que foram apresentadas as vendas.","Uma causa que atribui as vendas apenas à nova estação.","Uma ressalva que contrasta a apresentação de dados com a falta de comparação necessária.","Uma consequência que comprova o efeito isolado da ciclovia.","Uma condição para que as ruas se tornem semelhantes."],"explanation":"Porém marca contraste: há dados de dois momentos, mas falta um grupo comparável para atribuir o efeito. O conector não apresenta finalidade, condição ou prova de causa.","version":3}},{"id":"d1431000-0000-4000-8000-000000000023","label":"P23","beforeHash":"de65d59e508eaa8f66805400b78f21c616bf20079beb6c9e0275d3582b1c8357","afterHash":"284fb2fedb52ca073d4b956f2e2abafb12f5d6977c47a60ac75d0cf8b9e7e44d","patch":{"statement":"O aplicativo prometia devolver tempo aos passageiros. Lara passou a consultar a previsão a cada minuto. Quando o ônibus atrasou, recebeu seis notificações de que o horário era estimado. Ela comentou: Que economia de tempo, agora preciso acompanhar o atraso em tempo real. Os colegas riram, mas continuaram na fila esperando o veículo.\n\nEm “Os colegas riram, mas continuaram na fila”, qual efeito é produzido por mas?","options":["Afirma que a espera foi encerrada como consequência do riso.","Contrasta a reação ao comentário com a permanência da situação de espera.","Marca uma condição futura para que os colegas possam rir.","Apresenta permanecer na fila como finalidade do riso.","Indica que rir foi a causa necessária de permanecer na fila."],"explanation":"Mas é adversativo e destaca que a reação bem-humorada não mudou a espera. Ele não transforma riso em causa, finalidade ou condição do atraso.","version":3}},{"id":"d1431000-0000-4000-8000-000000000024","label":"P24","beforeHash":"89b923a3e1bbeb90f0f37a926163ad4ab9abe8316fe53e6e62ea777ab8dde0f7","afterHash":"9d860302291841a068ca60a8499196bcff2b561752316993b044ccdb1f84bdcc","patch":{"statement":"Um estudo acompanhou hortas em três escolas e registrou relatos de maior interesse por alimentação. Os autores escreveram: A atividade pode favorecer esse interesse, embora o grupo não represente todas as escolas. A notícia foi publicada com o título Hortas garantem mudança alimentar. O texto da reportagem não acrescentava observações sobre os hábitos alimentares posteriores.\n\nEm “pode favorecer esse interesse, embora o grupo não represente todas as escolas”, o trecho iniciado por embora exerce qual função?","options":["Converte a possibilidade em uma finalidade obrigatória da atividade.","Afirma que o grupo reduzido garante o resultado em todas as escolas.","Apresenta a representatividade como condição já atendida pelo estudo.","Nega que tenha ocorrido qualquer relato nas escolas acompanhadas.","Concede uma limitação que restringe a generalização sem negar a possibilidade mencionada."],"explanation":"A concessiva apresenta uma limitação relevante ao alcance da afirmação. Não nega o registro local, mas impede tratá-lo como comprovação geral.","version":3}},{"id":"d1431000-0000-4000-8000-000000000025","label":"P25","beforeHash":"0925bcf5c4c4799d7819544968486d434ab4c6440de4000b949b5192d2d95355","afterHash":"ab92a198edb37845b1dc410e414a7f30881a0243e31c6c314bbae1fea17989fc","patch":{"statement":"No debate sobre a praça, o vereador afirmou: Precisamos voltar a ouvir os moradores. Uma participante perguntou quando havia ocorrido a escuta anterior; outra perguntou se ela havia sido ampla ou apenas formal. O registro da reunião não traz resposta a essas perguntas.\n\nEm “outra perguntou se ela havia sido ampla ou apenas formal”, qual é o papel de se?","options":["Estabelecer a condição necessária para realizar a reunião.","Apresentar a finalidade da fala do vereador.","Expressar o motivo pelo qual todos os moradores concordaram.","Indicar que a reunião ocorreu antes da escuta.","Introduzir o conteúdo de uma pergunta indireta sobre a escuta anterior."],"explanation":"Se introduz uma interrogativa indireta dependente de perguntou. O trecho equivale ao conteúdo da pergunta “A escuta havia sido ampla ou apenas formal?”, sem expressar condição para a reunião.","version":3}},{"id":"d1431000-0000-4000-8000-000000000026","label":"P26","beforeHash":"8ae1d2d496ea8d41fc6279a5123a8265d04fae626e7535384862094bbfa46f88","afterHash":"d227f7a0dc778ddf0ee8bcd3a741c6788bf17ba5cf0a20ae02f0c15b6b89209a","patch":{"statement":"A escola instalou painéis informativos e distribuiu mapas do bairro. Os primeiros ficaram próximos aos portões; os segundos foram entregues aos estudantes. Visitantes consultavam os painéis para localizar a entrada. Ainda assim, os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos indicados.\n\nEm “os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos”, pois relaciona quais informações?","options":["Duas informações opostas que se anulam.","A atualização e uma condição que já foi comprovada falsa.","A necessidade de atualização e a razão que a explica.","A construção dos painéis e sua consequência inevitável para os caminhos.","A distribuição dos mapas e o objetivo de impedir obras."],"explanation":"A oração introduzida por pois explica por que atualizar os recursos é necessário. A mudança dos caminhos é a razão indicada; não se afirma oposição ou finalidade de impedir obras.","version":3}},{"id":"d1431000-0000-4000-8000-000000000027","label":"P27","beforeHash":"99f561a90ecb6e2af7a571c5105ef8b7a310a8fb1727e3385424a455c49e85c4","afterHash":"f760d640f3fc699647160a20e25c714077d1dc6d193b352e132b64feada5290f","patch":{"statement":"Um fabricante informou que sua embalagem usava 20% menos plástico. Uma cooperativa observou que ela combinava materiais difíceis de separar nos equipamentos disponíveis. O relatório final pediu uma avaliação da produção e da destinação, sem apresentar um único indicador como resposta para todas as etapas.\n\nEm “sem apresentar um único indicador como resposta para todas as etapas”, que interpretação de sem é adequada?","options":["Exclui um procedimento de avaliação baseado num só indicador.","Afirma que o relatório não contém dado algum.","Exige que a avaliação use apenas a massa de plástico.","Transforma o indicador em causa da dificuldade de separar materiais.","Exclui qualquer possibilidade de comparar embalagens."],"explanation":"Sem nega o procedimento de tratar um indicador como resposta completa. Isso não equivale a negar todos os dados ou toda avaliação; a restrição recai sobre a generalização indevida.","version":3}},{"id":"d1431000-0000-4000-8000-000000000028","label":"P28","beforeHash":"e7449d1cabd2ed5daa42310aec54ebe32e6716d227efdf2585393a712c1449b1","afterHash":"943f9026f18c48d233055e611c15ae63cd41274a171741dea0e052dd535ac5d4","patch":{"statement":"O conselho apoiou a finalidade de ampliar a acessibilidade, mas contestou a sequência proposta para a reforma: a única passagem seria fechada antes de a alternativa ficar pronta. Para os conselheiros, o plano deveria manter uma rota durante toda a obra. A empresa respondeu que reorganizaria as etapas.\n\nEm “Para os conselheiros, o plano deveria manter uma rota”, a expressão inicial introduz o quê?","options":["A finalidade de enviar a rota aos conselheiros.","Uma consequência da construção da nova rota.","Uma condição para que os conselheiros participem.","O destino físico de uma passagem durante a obra.","O ponto de vista ao qual a avaliação do plano é atribuída."],"explanation":"Para os conselheiros equivale a “na avaliação dos conselheiros”. A preposição atribui uma opinião; não descreve destino físico ou finalidade da rota.","version":3}},{"id":"d1431000-0000-4000-8000-000000000029","label":"P29","beforeHash":"49119085c1ddca6d65e9b089be25b6e8e912f2a54f58d6bc889c774a23f93ecb","afterHash":"35f33cfed946ec8f5895140cb8c278183ba5ca58ccb1dc5606b8a7f730928d2d","patch":{"statement":"Enquanto os convidados discutiam o prêmio, o porteiro reorganizava as cadeiras. Conhecia cada nome das placas, mas não aparecia nas fotografias. Ao final, encontrou no chão uma medalha de participação e a pendurou no uniforme. O relato encerra-se com essa ação, sem registrar fala ou pensamento do porteiro.\n\nO porteiro “conhecia cada nome das placas, mas não aparecia nas fotografias”. Que contraste essa construção destaca?","options":["Relação de causa entre conhecer nomes e receber uma medalha oficial.","Desconhecimento dos convidados e destaque nas fotografias.","Oposição entre dois acontecimentos que não podem coexistir.","Certeza de que ele recusou aparecer nas imagens.","Proximidade com os participantes e ausência na representação pública do evento."],"explanation":"Conhecer os nomes e ficar fora das fotografias podem coexistir. O contraste contribui para a tensão entre presença no trabalho do evento e reconhecimento, sem provar intenção de quem fotografou.","version":3}},{"id":"d1431000-0000-4000-8000-000000000030","label":"P30","beforeHash":"a74287f2838a30b7603abd9444766a08c24ba587d898d531e5ce95f37d1cd3bc","afterHash":"685c90305bb075a33a711ffffad12d4173b4d5bf1e97e1c5a0d4ae1a2e7e49c3","patch":{"statement":"Uma enquete foi divulgada apenas no perfil de um clube. Entre as 300 respostas, 240 apoiavam ampliar sua sede. O anúncio dizia: A cidade aprova o projeto. A cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores do perfil se distribuíam entre bairros nem quem decidiu responder.\n\nEm “a cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores se distribuíam”, qual contraste é relevante?","options":["A cidade e a exigência de que apenas não respondentes sejam pesquisados.","O apoio ao projeto e a conclusão de que a contagem das 300 respostas está errada.","O universo municipal conhecido e a falta de informação sobre quem está representado na enquete.","A quantidade de seguidores e a certeza de que cada bairro foi representado igualmente.","O tamanho da cidade e a comprovação de que todos os moradores responderam."],"explanation":"O contraste ressalta que conhecer a população municipal não demonstra representatividade dos respondentes. A limitação é de seleção e abrangência, não necessariamente da contagem das respostas.","version":3}},{"id":"d1431000-0000-4000-8000-000000000031","label":"P31","beforeHash":"77d12533c8fb8cddf79f8bc425546b3788ce7ab06befae2d082130c3400660fa","afterHash":"4616eb7829967195056967eed94c410a30a87bef306c3e631f85cbabf5da7487","patch":{"difficulty":"easy","statement":"A comissão pediu que a proposta financeira fosse revista. Ao comentar um passeio, uma aluna disse que queria rever a cidade. Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento e a situação de cada ocorrência.\n\n“Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento”. Que relação mas marca?","options":["Causa pela qual corrigir tem necessariamente todos os sentidos de rever.","Condição de que a aluna deixe de visitar a cidade.","Oposição entre a substituição uniforme sugerida e a análise contextual solicitada.","Consequência que comprova que a proposta já havia sido corrigida.","Finalidade de eliminar os complementos das duas frases."],"explanation":"O conector põe em contraste uma troca igual para as duas ocorrências e a necessidade de considerar seus sentidos. Ele não estabelece equivalência universal entre corrigir e rever.","version":3}},{"id":"d1431000-0000-4000-8000-000000000032","label":"P32","beforeHash":"5d21610ce792ea8de22a3ae4b98c2aec522b68bd02dbc784b9712f61fce19959","afterHash":"9c777b578e0502a60a8481fcfcd562a51a4ff01da2df7065ffc8598c26c8f85e","patch":{"statement":"Um comunicado dizia: Os moradores que solicitaram vistoria receberão resposta. Outra versão dizia: Os moradores, que solicitaram vistoria, receberão resposta. As palavras eram as mesmas, porém a equipe precisava decidir se o aviso se referia apenas aos solicitantes ou ao conjunto dos moradores mencionado no documento.\n\nCompare “Os moradores que solicitaram vistoria” e “Os moradores, que solicitaram vistoria,”. Que efeito das vírgulas é adequado?","options":["A primeira inclui todos os moradores e a segunda restringe aos solicitantes.","As vírgulas identificam quem será responsável pela vistoria.","As duas construções selecionam necessariamente os mesmos solicitantes entre todos os moradores.","As vírgulas transformam uma ação futura em uma ação passada.","A primeira oração seleciona solicitantes; a segunda apresenta a solicitação como informação sobre o grupo de moradores mencionado."],"explanation":"Sem vírgulas, a relativa é restritiva; com vírgulas, é explicativa. Muda o recorte do grupo, não o tempo verbal nem o responsável pela ação.","version":3}},{"id":"d1431000-0000-4000-8000-000000000033","label":"P33","beforeHash":"2b4adc339d77bea912dc33d5115ee4de3d1e355215d07f5401682ac03373033a","afterHash":"98b1848eb8e4827a1c7affe1133ecfd475e28c0cd81a6d51b00ee37e8fbb85c9","patch":{"difficulty":"easy","statement":"A nota dizia: Foram eliminados os registros duplicados. O relatório posterior dizia: A equipe de cadastro eliminou os registros duplicados. Embora os documentos tratassem da mesma ação, uma solicitação de prestação de contas pedia também a identificação de quem a executou.\n\n“Embora os documentos tratassem da mesma ação, (...) pedia também a identificação de quem a executou”. Qual informação a oração concessiva destaca?","options":["O segundo documento nega que tenha ocorrido eliminação.","A semelhança entre os documentos comprova que os dois já nomeiam o agente.","A identificação do agente transforma a eliminação em outra ação.","Tratar da mesma ação não dispensa informar seu agente para a finalidade indicada.","A identificação é a causa necessária da existência dos registros duplicados."],"explanation":"A concessiva admite a identidade da ação e contrapõe a ela uma informação ainda necessária: quem a realizou. Isso não muda o acontecimento nem demonstra que o primeiro documento já contém o agente.","version":3}},{"id":"d1431000-0000-4000-8000-000000000034","label":"P34","beforeHash":"f2997b27be45ef9f5f8f25a8aa184e048fd3ed27b6be9c432e03c85948625478","afterHash":"e92cb8698b5ae4e7f03259a7c9afd49425f5b446db996d78392a00f8d13846e6","patch":{"difficulty":"easy","statement":"Uma editora encontrou no relatório: Fazem três meses que o projeto começou. Na página seguinte, leu: Houveram alterações no cronograma. Ela pediu a revisão das formas verbais, e não apenas a troca dos termos meses e alterações por palavras no singular.\n\nEm “revisão das formas verbais, e não apenas a troca dos termos (...) por palavras no singular”, que orientação é comunicada?","options":["A revisão precisa retirar os verbos e manter apenas os substantivos.","O uso de e exige que as duas frases tenham sujeito plural.","Trocar substantivos é suficiente para manter corretamente qualquer forma verbal.","A correção deve examinar a construção verbal, sem se limitar a alterar os substantivos seguintes.","Todos os verbos devem passar ao plural para concordar com alterações."],"explanation":"E não apenas delimita o alcance da revisão: ela não deve se resumir à troca lexical. Haver existencial e fazer temporal exigem análise de impessoalidade, não uma regra mecânica pelo termo seguinte.","version":3}},{"id":"d1431000-0000-4000-8000-000000000035","label":"P35","beforeHash":"2a503e3b3a895b34a81ec09e8276d923a855bcf31adcb65781bab4f17f49a4a6","afterHash":"56ea292506f67141931733b43224bfaa4a9cd889954f6f3f16846963c8cb676d","patch":{"statement":"No relatório, constavam: Os estudantes assistiram o documentário e O técnico assistiu o pesquisador durante o procedimento. A primeira frase tratava da exibição de um filme; a segunda, da ajuda prestada no laboratório. A revisora avaliou a regência de assistir no sentido de cada ação descrita.\n\nAssistir aparece como ver um documentário e como auxiliar um pesquisador. Qual comparação corresponde à norma-padrão adotada?","options":["Assistir no documentário e assistir no pesquisador.","Assistir o documentário e assistir ao pesquisador, invertendo as regências dos dois sentidos.","Assistir ao documentário e assistir o pesquisador.","Assistir do documentário e assistir o pesquisador.","Assistir ao documentário e assistir do pesquisador."],"explanation":"No sentido de presenciar, assistir rege a preposição a; no de ajudar, pode ser transitivo direto. A análise distingue a acepção, sem escolher a regência apenas pelo tipo de complemento.","version":3}},{"id":"d1431000-0000-4000-8000-000000000036","label":"P36","beforeHash":"3bec3abfda5d20da1f1171bd74f0d7fe02077915a7f29f32dfda0016f9306212","afterHash":"99f460acde696c8082991726dff06ce35631aca397b21d71eca0d9982b6b4d1b","patch":{"difficulty":"easy","statement":"A ficha registrava: Entregou o documento à diretora. Outra registrava: Entregou o documento a uma diretora. Uma estudante propôs pôr acento grave nas duas, mas a editora pediu que ela comparasse os artigos e a preposição exigida pelo verbo.\n\nQual troca permite testar o acento grave em “entregou o documento à diretora”?","options":["Substituir documento por formulário, mantendo o destinatário igual.","Substituir diretora por diretor: entregou o documento ao diretor.","Colocar o verbo no passado, preservando o destinatário feminino.","Trocar diretora por uma palavra feminina sem considerar artigo ou regência.","Acrescentar uma antes de diretora e manter necessariamente à."],"explanation":"Ao reúne a preposição a com o artigo o, ajudando a identificar os dois elementos que formam à no correspondente feminino. Mudar o objeto ou o tempo não verifica esse encontro.","version":3}},{"id":"d1431000-0000-4000-8000-000000000037","label":"P37","beforeHash":"bfa8375736c4145cf2ef15ffb8326a3b2ef3611e5b3f60439f6a8c8d8c224084","afterHash":"6cc9fd6175cb6227fba4dc997c97204cf86a0874c4c62913d28c89472e8dece4","patch":{"difficulty":"easy","statement":"O jornal publicou: A professora informou à aluna que sua inscrição estava incompleta. Um leitor perguntou de quem era a inscrição. O redator substituiu “sua inscrição” pela expressão “a inscrição da aluna” e manteve o restante da informação. A alteração passou a constar na edição seguinte.\n\nEm “a professora informou à aluna que sua inscrição estava incompleta”, qual alternativa identifica o problema de sua?","options":["Sua indica obrigatoriamente a aluna porque ela aparece mais perto do pronome.","Sua indica obrigatoriamente que a inscrição é da professora por ela ser o sujeito.","A forma possessiva elimina qualquer necessidade de contexto.","O possessivo não explicita se a inscrição é da professora ou da aluna.","A ambiguidade decorre apenas do tempo passado de estava."],"explanation":"O possessivo pode ter mais de um referente no contexto. Proximidade e posição de sujeito não bastam para garantir uma leitura única; explicitar o nome do possuidor resolve essa ambiguidade.","version":3}},{"id":"d1431000-0000-4000-8000-000000000038","label":"P38","beforeHash":"5fee289e261b58b93d47f4642a0b07d3b2ddfb085547ad75575954356cf9512b","afterHash":"b83d4ca31cc8528ccf196a51a67c2b4e3686d5c591982c3aff4252a63ace047e","patch":{"statement":"O editorial chamou a falta de planejamento de um buraco no orçamento. Na sequência, apresentou receitas e despesas para dimensionar o problema. Um leitor destacou a imagem expressiva, mas outro pediu que a avaliação se baseasse também nos valores documentados.\n\nEm “um buraco no orçamento”, qual relação entre imagem e dados é adequada?","options":["A palavra buraco já informa o valor exato do déficit.","A metáfora transforma receitas e despesas em medidas de distância.","Receitas e despesas impedem qualquer uso expressivo de linguagem.","A expressão figurada caracteriza um problema, mas os valores são necessários para quantificá-lo.","O uso figurado comprova que os dados financeiros são inventados."],"explanation":"A imagem atribui uma característica ao problema e pode orientar a interpretação. Ela não fornece, sozinha, uma medida numérica nem invalida a apresentação de dados.","version":3}},{"id":"d1431000-0000-4000-8000-000000000039","label":"P39","beforeHash":"842ff40ba599732f1358fc781225250f5e4068028b562d9b533d30ae33905b30","afterHash":"6adb9839ce71d3a6e4c98e1f23bb958ad78274655bd7325150d15d6b9d640a48","patch":{"statement":"A notícia dizia: Segundo a pesquisadora, o material pode reduzir perdas. Na edição seguinte, apareceu: O material reduz perdas. A mudança retirou palavras da frase, sem acrescentar dados ou resultados ao conteúdo publicado.\n\nEm “Segundo a pesquisadora, o material pode reduzir perdas”, qual efeito tem Segundo a pesquisadora?","options":["Converter a hipótese em comprovação pelo veículo.","Indicar que o veículo discorda obrigatoriamente da pesquisadora.","Atribuir a afirmação a uma fonte, sem provar sozinho a eficácia do material.","Informar que o material foi testado em todas as condições de uso.","Transformar pode em uma obrigação de obter resultado."],"explanation":"A expressão identifica a origem da informação. Sua presença não é demonstração de eficácia nem sinal obrigatório de discordância; a hipótese continua marcada por pode.","version":3}},{"id":"d1431000-0000-4000-8000-000000000040","label":"P40","beforeHash":"8f6a71f183aa60ee63db12ac4200585a3f8150cdb1d907d01f57948de772e644","afterHash":"53eda5f75cf69b8934f70580b204b30dd9a0e372249089666c3e40d8547bb652","patch":{"difficulty":"easy","statement":"O regulamento dizia: A inscrição só será aceita se o formulário estiver completo e o comprovante for enviado. Rui preencheu o formulário, mas não enviou o comprovante. A equipe recusou o pedido. Uma colega sugeriu que ele relesse os dois requisitos antes de reclamar.\n\nConsidere somente os requisitos formulário completo e comprovante enviado, sem outros critérios. Qual mudança na satisfação dos requisitos resulta de trocar e por ou, com sentido de alternativa inclusiva?","options":["Passa a ser obrigatório cumprir exatamente os mesmos dois requisitos.","Passa a ser obrigatório que o formulário fique incompleto.","Passa a bastar o cumprimento de ao menos um requisito, incluindo a possibilidade de cumprir ambos.","Passa a ser proibido apresentar qualquer comprovante.","Passa a ser necessário que nenhum requisito esteja cumprido."],"explanation":"E reúne condições conjuntas. Ou inclusivo admite uma ou ambas, alterando o critério de aceitação. A indicação do sentido inclusivo evita confundir a tarefa com uma alternativa exclusiva.","version":3}},{"id":"d1431000-0000-4000-8000-000000000041","label":"P41","beforeHash":"6df6de41ed6bdc890ea79f6239d2bceb7883dc49fa805852f31190a8ee2843e9","afterHash":"7ac6393ffdce65314e3b7298e242758f1ff21e60203cba1f4ceb9e16a0f13f02","patch":{"statement":"A biblioteca ampliou o horário. Em dois meses comparáveis, os empréstimos passaram de 800 para 1.100, mas o número de usuários distintos permaneceu em 200. A direção comemorou a circulação maior; o conselho solicitou os registros de novos cadastros. Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Os empréstimos subiram de 800 para 1.100, mas continuam sendo 200 usuários distintos. O aumento mede circulação de livros, não demonstra que mais pessoas passaram a usar a biblioteca.","version":3}},{"id":"d1431000-0000-4000-8000-000000000042","label":"P42","beforeHash":"34d39f36cb9a631c9c9d2b29f885d1cc4a0232a4f435446e87e2ccce5424b667","afterHash":"a0488ecfa57a1a734918016d1e41852838b0e6fdade7878073b969caf2e15806","patch":{"statement":"Depois que uma rua recebeu ciclovia, as vendas de duas lojas aumentaram. No mesmo mês, abriu uma estação de transporte e ocorreu uma feira comercial. Um lojista declarou: Foi a ciclovia que trouxe o crescimento. O levantamento apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Ciclovia, estação e feira aparecem no mesmo período. Sem comparação que separe essas mudanças, o aumento das vendas não pode ser atribuído exclusivamente à ciclovia nem usado para negar qualquer contribuição dela.","version":3}},{"id":"d1431000-0000-4000-8000-000000000043","label":"P43","beforeHash":"069e938bb9a2988fcb7a7916be10ad0011fd0cbe8834da71b3e9ec2043bf9bd4","afterHash":"92413dae159ff0b53dbced4bf7dbbf01599e5eff9d153890b562232f0dabdf6b","patch":{"statement":"O aplicativo prometia devolver tempo aos passageiros. Lara passou a consultar a previsão a cada minuto. Quando o ônibus atrasou, recebeu seis notificações de que o horário era estimado. Ela comentou: Que economia de tempo, agora preciso acompanhar o atraso em tempo real. Os colegas riram, mas continuaram na fila esperando o veículo.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"A promessa era poupar tempo, mas Lara consulta o aplicativo repetidamente e continua esperando. O aparente elogio ao acompanhamento do atraso produz ironia por esse contraste.","version":3}},{"id":"d1431000-0000-4000-8000-000000000044","label":"P44","beforeHash":"acc17783f161d0eb2949b7f04f5689c851cbceae0fdf0632db12fc6760f3c0ca","afterHash":"a731462d03440f795cdc47fb3c65ab9e968dca2d37836372ada9f2992fde9f28","patch":{"statement":"Um estudo acompanhou hortas em três escolas e registrou relatos de maior interesse por alimentação. Os autores escreveram: A atividade pode favorecer esse interesse, embora o grupo não represente todas as escolas. A notícia foi publicada com o título Hortas garantem mudança alimentar. O texto da reportagem não acrescentava observações sobre os hábitos alimentares posteriores.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"O estudo usa pode favorecer e limita a abrangência a três escolas. O título emprega garantem e muda interesse por alimentação para mudança alimentar, ampliando certeza e alcance sem novos dados.","version":3}},{"id":"d1431000-0000-4000-8000-000000000045","label":"P45","beforeHash":"bfcb3f615acd01e0fc53f21e751e29c6e11a70aea1a23f90ceb9b1837f5383ce","afterHash":"dd23e3353a79f665d08cb951e0e6b48ba68f6928c9deb2309e94dca305005a39","patch":{"statement":"No debate sobre a praça, o vereador afirmou: Precisamos voltar a ouvir os moradores. Uma participante perguntou quando havia ocorrido a escuta anterior; outra perguntou se ela havia sido ampla ou apenas formal. O registro da reunião não traz resposta a essas perguntas.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Voltar a ouvir apresenta a escuta como retomada. Essa pressuposição linguística não demonstra quando, como ou quantos moradores foram ouvidos; por isso as perguntas da participante continuam pertinentes.","version":3}},{"id":"d1431000-0000-4000-8000-000000000046","label":"P46","beforeHash":"f63d7e87f95123f466f453e5ebdb191139eb459587d910fc944adfc3995ca1c5","afterHash":"855338e2ccf6f26a051c4656e4ca3cd491dc021fc91ed3b1ecb30759dd8a8ce3","patch":{"statement":"A escola instalou painéis informativos e distribuiu mapas do bairro. Os primeiros ficaram próximos aos portões; os segundos foram entregues aos estudantes. Visitantes consultavam os painéis para localizar a entrada. Ainda assim, os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos indicados.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"A ordem de menção é painéis e depois mapas. Assim, primeiros retoma painéis e segundos retoma mapas. As obras alteram os caminhos, justificando atualização dos dois recursos.","version":3}},{"id":"d1431000-0000-4000-8000-000000000047","label":"P47","beforeHash":"356069733a5025a4873d1c89f43adcb634345ef2f4a24205a63872631e9512a3","afterHash":"4c6bf9dfa70642e1a8f88efb21460f6db568814c0d40c1796b08bff8247ed36d","patch":{"statement":"Um fabricante informou que sua embalagem usava 20% menos plástico. Uma cooperativa observou que ela combinava materiais difíceis de separar nos equipamentos disponíveis. O relatório final pediu uma avaliação da produção e da destinação, sem apresentar um único indicador como resposta para todas as etapas.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Usar menos plástico é um indicador de produção; separar materiais é uma condição da reciclagem. A redução de 20% informada não elimina a dificuldade indicada pela cooperativa.","version":3}},{"id":"d1431000-0000-4000-8000-000000000048","label":"P48","beforeHash":"2234a6e46430d8572f7adc3807e8dcd4734dcb379a87665049cd20011aada696","afterHash":"ca0232a9c83cc28d66c6272ef5885137bbdbe658156082cdcad3c6908cf40063","patch":{"statement":"O conselho apoiou a finalidade de ampliar a acessibilidade, mas contestou a sequência proposta para a reforma: a única passagem seria fechada antes de a alternativa ficar pronta. Para os conselheiros, o plano deveria manter uma rota durante toda a obra. A empresa respondeu que reorganizaria as etapas.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"O conselho declara apoio à acessibilidade, mas identifica fechamento antes de haver rota alternativa. A crítica é à sequência que deixaria pessoas sem passagem, não ao objetivo da reforma.","version":3}},{"id":"d1431000-0000-4000-8000-000000000049","label":"P49","beforeHash":"92d8ddbae9050c60f17bce98a2d599ffb9fe55de1263d369b0a5b435a676b462","afterHash":"5303b489b75d5b848e01b5ba47ca34ca8637c6b419d485af29a879d024d98a12","patch":{"difficulty":"hard","statement":"Enquanto os convidados discutiam o prêmio, o porteiro reorganizava as cadeiras. Conhecia cada nome das placas, mas não aparecia nas fotografias. Ao final, encontrou no chão uma medalha de participação e a pendurou no uniforme. O relato encerra-se com essa ação, sem registrar fala ou pensamento do porteiro.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"O porteiro encontra e usa a medalha, mas não há fala ou pensamento registrado que revele sua intenção. A busca de reconhecimento é uma leitura possível, não um fato comprovado ou uma homenagem oficial.","version":3}},{"id":"d1431000-0000-4000-8000-000000000050","label":"P50","beforeHash":"313d9a87c85bbc98e4c2a347fde0994018a4c3ee56489b772944913b312c1cb9","afterHash":"f13ac911eee433b4b5f5f13f486914d27aeb207562abcaf1efb2eedf59ec40ae","patch":{"statement":"Uma enquete foi divulgada apenas no perfil de um clube. Entre as 300 respostas, 240 apoiavam ampliar sua sede. O anúncio dizia: A cidade aprova o projeto. A cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores do perfil se distribuíam entre bairros nem quem decidiu responder.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Entre 300 respondentes, 240 apoiam o projeto: 80% das respostas. A enquete no perfil do clube não demonstra que esses respondentes representem os 40 mil moradores; o percentual não pode ser generalizado à cidade.","version":3}},{"id":"d1431000-0000-4000-8000-000000000051","label":"P51","beforeHash":"1ae64c1c80121b685088b0c72b51d08a6f50d943250e4265d8b705395c079e4f","afterHash":"d135af512b97d034204d015f4a34a86d847e2b86e0d218932dea2cfd11b368e1","patch":{"statement":"A comissão pediu que a proposta financeira fosse revista. Ao comentar um passeio, uma aluna disse que queria rever a cidade. Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento e a situação de cada ocorrência.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Na proposta financeira, rever indica reexaminar; no contexto do passeio, indica ver ou visitar novamente. O complemento e a situação orientam a diferença de sentido do mesmo verbo.","version":3}},{"id":"d1431000-0000-4000-8000-000000000052","label":"P52","beforeHash":"a338adb5f15a47fc6d672eae03658f24f6636c7b9830541c0df114033386b4c2","afterHash":"7cdcc63b741d98c81cab12920d8d3ec306935af79d70dcfa6502a3d8b5060329","patch":{"statement":"Um comunicado dizia: Os moradores que solicitaram vistoria receberão resposta. Outra versão dizia: Os moradores, que solicitaram vistoria, receberão resposta. As palavras eram as mesmas, porém a equipe precisava decidir se o aviso se referia apenas aos solicitantes ou ao conjunto dos moradores mencionado no documento.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Sem vírgulas, que solicitaram vistoria restringe o grupo a solicitantes. Com vírgulas, a oração é explicativa e apresenta a solicitação como informação sobre o grupo mencionado.","version":3}},{"id":"d1431000-0000-4000-8000-000000000053","label":"P53","beforeHash":"7231bca0f97e6f174ca7fd8b761be502bdfcfed686024f49ad1e8a8dcd7e70ca","afterHash":"cfa84e874235fc6ba3bd5176ac4935f7f798860e7f3336be81a1f9cd895ecfb8","patch":{"statement":"A nota dizia: Foram eliminados os registros duplicados. O relatório posterior dizia: A equipe de cadastro eliminou os registros duplicados. Embora os documentos tratassem da mesma ação, uma solicitação de prestação de contas pedia também a identificação de quem a executou.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Foram eliminados expressa voz passiva sem nomear quem agiu. A segunda versão nomeia a equipe. Omissão do agente e intenção de ocultá-lo não são equivalentes: a finalidade não é demonstrada pelo primeiro período.","version":3}},{"id":"d1431000-0000-4000-8000-000000000054","label":"P54","beforeHash":"2da1b271b28156d63fe9d16656e3eac5dbac8bc1ddea23b824af3b33b30cd62b","afterHash":"16a0cc29fa77d6c1fdf160e2c7126dc50740e08e737be2e3153bd4bdd75eb374","patch":{"statement":"Uma editora encontrou no relatório: Fazem três meses que o projeto começou. Na página seguinte, leu: Houveram alterações no cronograma. Ela pediu a revisão das formas verbais, e não apenas a troca dos termos meses e alterações por palavras no singular.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Fazer indica tempo decorrido e haver indica existência. Nesses sentidos, são impessoais e ficam no singular: Faz três meses e Houve alterações. Meses e alterações não exigem plural desses verbos.","version":3}},{"id":"d1431000-0000-4000-8000-000000000055","label":"P55","beforeHash":"161093fc36224df93f1e1a6a65184dd5f7d96144e4ea5b627646437fdefa62bf","afterHash":"e5e224aa8c68d5bf8f8a2b4eb0c3b5b2864f052c02b22671efaf369f2311f057","patch":{"statement":"No relatório, constavam: Os estudantes assistiram o documentário e O técnico assistiu o pesquisador durante o procedimento. A primeira frase tratava da exibição de um filme; a segunda, da ajuda prestada no laboratório. A revisora avaliou a regência de assistir no sentido de cada ação descrita.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Assistir no sentido de presenciar rege a: assistiram ao documentário. No sentido de ajudar, admite objeto direto: assistiu o pesquisador. A acepção orienta a regência.","version":3}},{"id":"d1431000-0000-4000-8000-000000000056","label":"P56","beforeHash":"6d6e614ffd1274343f6e7bfda1998de21c3967dd935568426b550789d1c1a00e","afterHash":"7244623be54415f69123201f6ba65e26dd537ac9d6f254620fd0562f87943d07","patch":{"statement":"A ficha registrava: Entregou o documento à diretora. Outra registrava: Entregou o documento a uma diretora. Uma estudante propôs pôr acento grave nas duas, mas a editora pediu que ela comparasse os artigos e a preposição exigida pelo verbo.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Em à diretora, unem-se a preposição a e o artigo definido a. Em a uma diretora, há preposição e artigo indefinido uma, sem o mesmo encontro que produziria o acento grave.","version":3}},{"id":"d1431000-0000-4000-8000-000000000057","label":"P57","beforeHash":"46bd5a56a8c585d8c19f5e5ba0a27c4cceb1d6e503b9ca594c1b15f088e37528","afterHash":"d98f8632ed472bfc8dd3e386ef6ee6f64d62ca26af89550feea05c1f8d6f0790","patch":{"statement":"O jornal publicou: A professora informou à aluna que sua inscrição estava incompleta. Um leitor perguntou de quem era a inscrição. O redator substituiu “sua inscrição” pela expressão “a inscrição da aluna” e manteve o restante da informação. A alteração passou a constar na edição seguinte.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Sua inscrição pode ser interpretada como inscrição da professora ou da aluna. Nomear a inscrição da aluna explicita o possuidor pretendido, mantendo o estado de incompletude informado.","version":3}},{"id":"d1431000-0000-4000-8000-000000000058","label":"P58","beforeHash":"4087a5dced2f696fb9353800f27fa4b124e7606b59cf4fef604a05f230a7202b","afterHash":"80856f83c7e7513fea5ffcbf7151aa112877cb7fc93164b68d3fb88c47b3ccc5","patch":{"statement":"O editorial chamou a falta de planejamento de um buraco no orçamento. Na sequência, apresentou receitas e despesas para dimensionar o problema. Um leitor destacou a imagem expressiva, mas outro pediu que a avaliação se baseasse também nos valores documentados.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Buraco no orçamento é uma imagem expressiva de insuficiência ou problema. Para avaliar a dimensão, são necessários os valores de receitas e despesas; a metáfora não fornece esse número.","version":3}},{"id":"d1431000-0000-4000-8000-000000000059","label":"P59","beforeHash":"e6180783915857dbd012f57418897891fcc55d669ea4422a68ea7de2c3fd8a6a","afterHash":"aef4f1b5b706ec5c6eb35319da94a147c3221e2d313db306a5b8a08404ca3a89","patch":{"statement":"A notícia dizia: Segundo a pesquisadora, o material pode reduzir perdas. Na edição seguinte, apareceu: O material reduz perdas. A mudança retirou palavras da frase, sem acrescentar dados ou resultados ao conteúdo publicado.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Segundo a pesquisadora atribui a informação a uma fonte, e pode reduz o grau de certeza. Ao retirar os dois elementos, a notícia apresenta a conclusão de forma mais assertiva sem acrescentar evidência.","version":3}},{"id":"d1431000-0000-4000-8000-000000000060","label":"P60","beforeHash":"70e6b7369f277545499f0f7a82541ba42eba83ab73e70d5e25be9712423abfc7","afterHash":"5acd7f8c3ef10a4bce0b1dbf24b442166a75d077a3ca8067be891d523308d57d","patch":{"difficulty":"easy","statement":"O regulamento dizia: A inscrição só será aceita se o formulário estiver completo e o comprovante for enviado. Rui preencheu o formulário, mas não enviou o comprovante. A equipe recusou o pedido. Uma colega sugeriu que ele relesse os dois requisitos antes de reclamar.\n\nQual manchete sintetiza o ponto central sem ampliar indevidamente o alcance das informações?","explanation":"Os dois requisitos são necessários em conjunto. Rui cumpriu o formulário, mas faltou o comprovante, portanto não satisfaz a condição exigida. Isso não demonstra que o formulário estava incompleto.","version":3}},{"id":"d1431000-0000-4000-8000-000000000061","label":"P61","beforeHash":"2b1b58e7a622907c9a731f2442a0c31c9a9a5511f8dc6a76b402f41bfb9d54cc","afterHash":"9648ec01aaf18290e9df39d6a56a6cb18172410a7396b302a835d8bc82a6e50d","patch":{"statement":"A biblioteca ampliou o horário. Em dois meses comparáveis, os empréstimos passaram de 800 para 1.100, mas o número de usuários distintos permaneceu em 200. A direção comemorou a circulação maior; o conselho solicitou os registros de novos cadastros. Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais.\n\nConsidere também a formulação: “Empréstimos aumentaram, mas o número de usuários ficou estável.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000062","label":"P62","beforeHash":"64e1dc32abb405ce138f776c658422de129ba8e3c9cb544f6a1736a3139ec8e9","afterHash":"cc734cdc1f702ebfd21d72fcc3eb4a6642debe3749b0e462c0ce5a54879a0ff6","patch":{"statement":"Depois que uma rua recebeu ciclovia, as vendas de duas lojas aumentaram. No mesmo mês, abriu uma estação de transporte e ocorreu uma feira comercial. Um lojista declarou: Foi a ciclovia que trouxe o crescimento. O levantamento apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes.\n\nConsidere também a formulação: “O levantamento não compara ruas semelhantes, por isso não isola o efeito da ciclovia.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000063","label":"P63","beforeHash":"0dc66ab62684870cb2d614f261f0b4af7e600a9fbbc7f6cf475fe15364c80b2f","afterHash":"f83e7e1f02c9f1f113f313daad8c3520559fa23456d0b14e75d331569c52ae87","patch":{"statement":"O aplicativo prometia devolver tempo aos passageiros. Lara passou a consultar a previsão a cada minuto. Quando o ônibus atrasou, recebeu seis notificações de que o horário era estimado. Ela comentou: Que economia de tempo, agora preciso acompanhar o atraso em tempo real. Os colegas riram, mas continuaram na fila esperando o veículo.\n\nConsidere também a formulação: “Lara disse: Agora preciso acompanhar o atraso em tempo real.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000064","label":"P64","beforeHash":"d41418059c9c54400ed5be0828381364d9bc90ae8b257bbfc3e9deefd03b11c5","afterHash":"7d3a29853d2b3e144bd59d2c5ae08b7321efd4572bd1b6b84b11a625934a7ba0","patch":{"statement":"Um estudo acompanhou hortas em três escolas e registrou relatos de maior interesse por alimentação. Os autores escreveram: A atividade pode favorecer esse interesse, embora o grupo não represente todas as escolas. A notícia foi publicada com o título Hortas garantem mudança alimentar. O texto da reportagem não acrescentava observações sobre os hábitos alimentares posteriores.\n\nConsidere também a formulação: “A atividade pode favorecer o interesse por alimentação.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000065","label":"P65","beforeHash":"b846748cdbe610670b8fec88266337bd0bee980c3e06413e3220dddea7ebe7ee","afterHash":"979312992c7b24a07cded23f02e2b0fb55e094eec5c17565cc5cc7812ab2f660","patch":{"difficulty":"easy","statement":"No debate sobre a praça, o vereador afirmou: Precisamos voltar a ouvir os moradores. Uma participante perguntou quando havia ocorrido a escuta anterior; outra perguntou se ela havia sido ampla ou apenas formal. O registro da reunião não traz resposta a essas perguntas.\n\nConsidere também a formulação: “Precisamos voltar a ouvir os moradores.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000066","label":"P66","beforeHash":"5bf8cfbb46e6549fa76cbedb89742f2322b4e680de7f1d87ff91cc832450ea62","afterHash":"a9f3130d0c1f697595bc8bb9e197949eac6c3899647c441109c6a411b65f6a67","patch":{"statement":"A escola instalou painéis informativos e distribuiu mapas do bairro. Os primeiros ficaram próximos aos portões; os segundos foram entregues aos estudantes. Visitantes consultavam os painéis para localizar a entrada. Ainda assim, os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos indicados.\n\nConsidere também a formulação: “Painéis e mapas são necessários. Ambos precisam de atualização.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000067","label":"P67","beforeHash":"1efda4914bec14ee0c7dd7d23b91782c5f0981c9ae8161cda037b581ade092d9","afterHash":"4896a51c0edccad93acd5470a2165acacd921e70a17b016675179c2c7c3b6d43","patch":{"statement":"Um fabricante informou que sua embalagem usava 20% menos plástico. Uma cooperativa observou que ela combinava materiais difíceis de separar nos equipamentos disponíveis. O relatório final pediu uma avaliação da produção e da destinação, sem apresentar um único indicador como resposta para todas as etapas.\n\nConsidere também a formulação: “Usar menos plástico não significa, por si só, reciclar com mais facilidade.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000068","label":"P68","beforeHash":"2a4e869ec98776f86bbe3fd5e189a4f7979efd4a9845738a53a737737aa12ec0","afterHash":"d9be39ea5f689f54a6363f57f597e9e6267d587d827023806aa969d6772e474c","patch":{"statement":"O conselho apoiou a finalidade de ampliar a acessibilidade, mas contestou a sequência proposta para a reforma: a única passagem seria fechada antes de a alternativa ficar pronta. Para os conselheiros, o plano deveria manter uma rota durante toda a obra. A empresa respondeu que reorganizaria as etapas.\n\nConsidere também a formulação: “Antes de fechar a passagem, a empresa deve criar uma alternativa.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000069","label":"P69","beforeHash":"296e0a8b429a586534dc9e8da31599dd9245c92fade41118ff0441bf455be080","afterHash":"bc7d4b32a128a1b636bc5dddc346ec00099e84539605e21bbde09f167fca28f8","patch":{"statement":"Enquanto os convidados discutiam o prêmio, o porteiro reorganizava as cadeiras. Conhecia cada nome das placas, mas não aparecia nas fotografias. Ao final, encontrou no chão uma medalha de participação e a pendurou no uniforme. O relato encerra-se com essa ação, sem registrar fala ou pensamento do porteiro.\n\nConsidere também a formulação: “O gesto pode indicar uma busca de reconhecimento.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000070","label":"P70","beforeHash":"99d1adc7c4379fc8b0e9ea74d6ca4a012568e1e3b7a9ec0e9ce1774fe4ee73e8","afterHash":"e742bdf24db16046d5b03a571fc890c8cde5133758f1dfe44b93b7838951d137","patch":{"statement":"Uma enquete foi divulgada apenas no perfil de um clube. Entre as 300 respostas, 240 apoiavam ampliar sua sede. O anúncio dizia: A cidade aprova o projeto. A cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores do perfil se distribuíam entre bairros nem quem decidiu responder.\n\nConsidere também a formulação: “A maioria dos respondentes apoiou o projeto.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000071","label":"P71","beforeHash":"66033c0b38dccc95a8f10dbbfd9afa52f909cff342cdf702aa3fc54d190a5e29","afterHash":"dafcb2d7b221fcbabe7562960d2fd832d8dec51b6d8adfceea64db160a093009","patch":{"statement":"A comissão pediu que a proposta financeira fosse revista. Ao comentar um passeio, uma aluna disse que queria rever a cidade. Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento e a situação de cada ocorrência.\n\nConsidere também a formulação: “A proposta deve ser revista; a aluna quer rever a cidade.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000072","label":"P72","beforeHash":"ad718afd6a7660bc3a136ac1637cc2976b6226e2f5791438f9a39d00e7299dfe","afterHash":"4f574c3bd74ba7ac002782add0e1ffc363f0749fe6dcd46ff8791dfb1fb97fb6","patch":{"statement":"Um comunicado dizia: Os moradores que solicitaram vistoria receberão resposta. Outra versão dizia: Os moradores, que solicitaram vistoria, receberão resposta. As palavras eram as mesmas, porém a equipe precisava decidir se o aviso se referia apenas aos solicitantes ou ao conjunto dos moradores mencionado no documento.\n\nConsidere também a formulação: “Somente os moradores solicitantes receberão resposta.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000073","label":"P73","beforeHash":"4fd4d1ab37112f966df253526cc8737142b477dbeefd990440901fdd6e0984b3","afterHash":"72429b858e34cfcfa7b46d7bdb04198ae33ebf734131f4d271b11efdb2e6fbe8","patch":{"statement":"A nota dizia: Foram eliminados os registros duplicados. O relatório posterior dizia: A equipe de cadastro eliminou os registros duplicados. Embora os documentos tratassem da mesma ação, uma solicitação de prestação de contas pedia também a identificação de quem a executou.\n\nConsidere também a formulação: “A equipe de cadastro eliminou os registros duplicados.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000074","label":"P74","beforeHash":"8309e78db616bb185ae959073c5294c7500d5a509ade9a7c82e8589492773a14","afterHash":"930381199a070d3e47616e6eb177b9af6e348972a160fa2e6904c64913c69be2","patch":{"statement":"Uma editora encontrou no relatório: Fazem três meses que o projeto começou. Na página seguinte, leu: Houveram alterações no cronograma. Ela pediu a revisão das formas verbais, e não apenas a troca dos termos meses e alterações por palavras no singular.\n\nConsidere também a formulação: “Haverá alterações. Vai fazer três meses que o projeto começou.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000075","label":"P75","beforeHash":"7ba2cfab3740df988a7fa8306404489f4a594fb8395278a7a2f45040b3eb783d","afterHash":"7c0bfb22b20c0b467e65dfe92b0b5dc2f8423e7eb3676e37d01d430b2bbb5ace","patch":{"statement":"No relatório, constavam: Os estudantes assistiram o documentário e O técnico assistiu o pesquisador durante o procedimento. A primeira frase tratava da exibição de um filme; a segunda, da ajuda prestada no laboratório. A revisora avaliou a regência de assistir no sentido de cada ação descrita.\n\nConsidere também a formulação: “Os estudantes assistiram ao documentário.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000076","label":"P76","beforeHash":"0bfb3ddecefa53e2edb4f1f120129b08f96b9feb36086be87c845f437edb2d65","afterHash":"5c21364f32579c6d289224ad610d64c599fea852d44972328c9ebc20e1f777fa","patch":{"statement":"A ficha registrava: Entregou o documento à diretora. Outra registrava: Entregou o documento a uma diretora. Uma estudante propôs pôr acento grave nas duas, mas a editora pediu que ela comparasse os artigos e a preposição exigida pelo verbo.\n\nConsidere também a formulação: “Os documentos foram entregues às diretoras e a duas supervisoras.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000077","label":"P77","beforeHash":"4a1c92e0246e4c148f264a2e9b23c00435f9538f6c6c2c57df7b1cd790e54f61","afterHash":"56bedaea7f719ac49c87be6624a80e1e9dfd69c3f81c6776bf316463e7945e2a","patch":{"statement":"O jornal publicou: A professora informou à aluna que sua inscrição estava incompleta. Um leitor perguntou de quem era a inscrição. O redator substituiu “sua inscrição” pela expressão “a inscrição da aluna” e manteve o restante da informação. A alteração passou a constar na edição seguinte.\n\nConsidere também a formulação: “A professora informou à aluna que sua inscrição estava incompleta.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000078","label":"P78","beforeHash":"2f33d2321332effff10225c8e0624968969d06998b7d9231426b751c9e0fb4e1","afterHash":"b1a353a6d76a4bb1fe35600b2ce3eca791cf62c6665e9f6951d8bd7e90786547","patch":{"statement":"O editorial chamou a falta de planejamento de um buraco no orçamento. Na sequência, apresentou receitas e despesas para dimensionar o problema. Um leitor destacou a imagem expressiva, mas outro pediu que a avaliação se baseasse também nos valores documentados.\n\nConsidere também a formulação: “A metáfora torna o problema concreto, mas não mede seu tamanho.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000079","label":"P79","beforeHash":"697b6dfe5c8140257e026b6ce7cd5860491ac6f884d1cacc0819ab55d0fe98bd","afterHash":"411b2e8968134c85aacf1beac3f68b8c0b4a33edd18119a67d830e84e2f23646","patch":{"statement":"A notícia dizia: Segundo a pesquisadora, o material pode reduzir perdas. Na edição seguinte, apareceu: O material reduz perdas. A mudança retirou palavras da frase, sem acrescentar dados ou resultados ao conteúdo publicado.\n\nConsidere também a formulação: “Segundo a pesquisadora, o material pode reduzir perdas.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000080","label":"P80","beforeHash":"ea5525d4f0a9bab4a3ac07869db760b030a7338ea06b584c60f4a16a93722808","afterHash":"ed522674753c02383774ac1f891f7c467269720c38618bd0fbfb14c02c7520f1","patch":{"statement":"O regulamento dizia: A inscrição só será aceita se o formulário estiver completo e o comprovante for enviado. Rui preencheu o formulário, mas não enviou o comprovante. A equipe recusou o pedido. Uma colega sugeriu que ele relesse os dois requisitos antes de reclamar.\n\nConsidere também a formulação: “O formulário deve estar completo e o comprovante deve ser enviado.” Qual alternativa apresenta uma reescrita equivalente ou uma análise adequada à norma-padrão e ao sentido indicado?","version":3}},{"id":"d1431000-0000-4000-8000-000000000081","label":"P81","beforeHash":"5be4f684a8c36132a591ed04b125c10e391853ebccceeb4985de3170b8f5adf8","afterHash":"feee50a87b555825524c44abe1db2940e05ab6e939e2ddd623616a093e8f89c9","patch":{"difficulty":"medium","statement":"A biblioteca ampliou o horário. Em dois meses comparáveis, os empréstimos passaram de 800 para 1.100, mas o número de usuários distintos permaneceu em 200. A direção comemorou a circulação maior; o conselho solicitou os registros de novos cadastros. Embora o relatório destaque o crescimento, não informa quem fez os empréstimos adicionais.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Contar novos exemplares no acervo como se fossem novos usuários.","Verificar somente se o total de empréstimos aumentou novamente.","Comparar quantos usuários novos frequentaram a biblioteca antes e depois da mudança.","Comparar a média de livros emprestados por usuário sem distinguir novos leitores.","Usar o horário ampliado como prova suficiente de aumento do público."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000082","label":"P82","beforeHash":"8a592c9ac0679f577a103814f9230f81ba227a3d647b29d22f3512ef0c6577d7","afterHash":"4e1f7f568332acf277626c4cd79ed83d3de104f9fb8640cce470845df89f9340","patch":{"difficulty":"medium","statement":"Depois que uma rua recebeu ciclovia, as vendas de duas lojas aumentaram. No mesmo mês, abriu uma estação de transporte e ocorreu uma feira comercial. Um lojista declarou: Foi a ciclovia que trouxe o crescimento. O levantamento apresenta os totais anteriores e posteriores, porém não compara ruas com condições semelhantes.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Comparar apenas o período anterior e posterior na mesma rua, sem registrar estação e feira.","Atribuir à ciclovia todo o aumento porque ela foi inaugurada antes do levantamento.","Perguntar só aos lojistas se aprovam a ciclovia e tomar a opinião como medida do efeito.","Comparar ruas com mudanças simultâneas diferentes sem controlar essas diferenças.","Comparar ruas semelhantes com e sem ciclovia, controlando outras mudanças relevantes."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000083","label":"P83","beforeHash":"7e882f98de8a838eca93985d7107bc7f243529824edcfc4a68192c87682dbea9","afterHash":"8dea04a898cbafd0ea079f6cd2013e4c8e54edbc168b838ddab6d0a214152d9a","patch":{"difficulty":"medium","statement":"O aplicativo prometia devolver tempo aos passageiros. Lara passou a consultar a previsão a cada minuto. Quando o ônibus atrasou, recebeu seis notificações de que o horário era estimado. Ela comentou: Que economia de tempo, agora preciso acompanhar o atraso em tempo real. Os colegas riram, mas continuaram na fila esperando o veículo.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Comparar o tempo de espera e o de consulta ao aplicativo em condições equivalentes.","Contar notificações como se cada uma equivalesse ao mesmo tempo de consulta.","Usar a promessa publicitária como medida do tempo efetivamente poupado.","Comparar usuários diferentes sem registrar frequência e duração das consultas.","Medir apenas o atraso do ônibus, sem o tempo gasto acompanhando o aplicativo."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000084","label":"P84","beforeHash":"cbdd42fc32e910b2454e7e6dd47cb4c63366b923a838311725e01fc2b3e337db","afterHash":"5ef86361246ec2142f3a1437fa525b6be83f14843f866ad0c64cb62390892046","patch":{"difficulty":"medium","statement":"Um estudo acompanhou hortas em três escolas e registrou relatos de maior interesse por alimentação. Os autores escreveram: A atividade pode favorecer esse interesse, embora o grupo não represente todas as escolas. A notícia foi publicada com o título Hortas garantem mudança alimentar. O texto da reportagem não acrescentava observações sobre os hábitos alimentares posteriores.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Acompanhar práticas alimentares e ampliar a amostra antes de generalizar o resultado.","Tomar conhecer hortaliças como comprovação de mudanças permanentes na alimentação.","Adotar garantem como equivalente de pode favorecer para tornar o título mais direto.","Comparar só o tamanho das hortas, sem observar hábitos ou interesse.","Generalizar os relatos das três escolas sem investigar outras condições."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000085","label":"P85","beforeHash":"f75ee3c9a7d0af4e6b20ac535afb3dd0a2b09bf3eb815dd9325e2a743191fb49","afterHash":"3060ca29e90fd3f92ab9254f3bb3ca4ef8a31398d095659f46329d6165b799bb","patch":{"difficulty":"medium","statement":"No debate sobre a praça, o vereador afirmou: Precisamos voltar a ouvir os moradores. Uma participante perguntou quando havia ocorrido a escuta anterior; outra perguntou se ela havia sido ampla ou apenas formal. O registro da reunião não traz resposta a essas perguntas.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Consultar somente o cronograma futuro, sem examinar a escuta anterior.","Tomar voltar como prova de que todos os moradores foram ouvidos amplamente.","Consultar registros da participação anterior para verificar quem foi efetivamente ouvido.","Verificar só o número de reuniões, sem saber quem participou e como.","Usar a fala do vereador como registro suficiente da qualidade da participação passada."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000086","label":"P86","beforeHash":"0dce63f0cf585be8f692308e762aa4b1559123f06c05da3ee8ab55ba6fdc4e89","afterHash":"cccc797bf2c46b069faecd5cf28c5f813f31ee473833e237aa725fff702d71d6","patch":{"difficulty":"medium","statement":"A escola instalou painéis informativos e distribuiu mapas do bairro. Os primeiros ficaram próximos aos portões; os segundos foram entregues aos estudantes. Visitantes consultavam os painéis para localizar a entrada. Ainda assim, os dois recursos dependiam de atualização, pois obras temporárias alteravam os caminhos indicados.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Conferir a escala do mapa como substituto da verificação de obras e acessos.","Verificar periodicamente se os trajetos exibidos correspondem às condições do bairro.","Comparar só a quantidade de mapas distribuídos, sem consultar seu conteúdo.","Atualizar apenas os nomes dos portões sem verificar os trajetos alterados.","Manter o mapa antigo porque a localização geral do bairro não mudou."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000087","label":"P87","beforeHash":"d76783a811439e481eb2d54699a42e5292f9d749ce99f268da34749de4448dd0","afterHash":"899957d066771597df05bc3646a6e31f74cb7e3bd047d8e40cd3e91522f08c10","patch":{"difficulty":"medium","statement":"Um fabricante informou que sua embalagem usava 20% menos plástico. Uma cooperativa observou que ela combinava materiais difíceis de separar nos equipamentos disponíveis. O relatório final pediu uma avaliação da produção e da destinação, sem apresentar um único indicador como resposta para todas as etapas.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Considerar reciclável todo material que usa menos plástico, sem verificar separação.","Comparar o preço das embalagens como medida completa da destinação.","Consultar somente o fabricante, desconsiderando os equipamentos da cooperativa.","Usar apenas a redução de massa de plástico como conclusão sobre todo o ciclo.","Comparar produção, separação e destinação das embalagens nas condições locais."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000088","label":"P88","beforeHash":"49ceab31bb6d82a0b77555760ffaac2b8824343be969a986c2482e2ad39aa17a","afterHash":"b64863d032068696c7770586e7eef8d007b46b539bc8f8e4836aae6ade39afee","patch":{"difficulty":"medium","statement":"O conselho apoiou a finalidade de ampliar a acessibilidade, mas contestou a sequência proposta para a reforma: a única passagem seria fechada antes de a alternativa ficar pronta. Para os conselheiros, o plano deveria manter uma rota durante toda a obra. A empresa respondeu que reorganizaria as etapas.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Confirmar apenas a finalidade de acessibilidade, sem verificar a ordem das etapas.","Verificar a rota alternativa somente depois de fechar a passagem existente.","Comparar o prazo final da obra sem investigar acessos durante a execução.","Tomar a promessa de reorganização como comprovação de que a rota já funciona.","Examinar se uma rota acessível alternativa pode ser criada antes do bloqueio da atual."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000089","label":"P89","beforeHash":"e8e22b050878a9edf5b9f173d9f3574964ed99c79c6390d393640d2e5c6f7cfc","afterHash":"f1033bd1de82d41bab05e8bce12fdc3dd940f4f275bd2bdc612f727bacead6a7","patch":{"statement":"Enquanto os convidados discutiam o prêmio, o porteiro reorganizava as cadeiras. Conhecia cada nome das placas, mas não aparecia nas fotografias. Ao final, encontrou no chão uma medalha de participação e a pendurou no uniforme. O relato encerra-se com essa ação, sem registrar fala ou pensamento do porteiro.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Tomar sua ausência nas fotos como prova de que não esteve no evento.","Afirmar que a medalha encontrada foi uma homenagem oficial.","Distinguir ações narradas de intenções apenas inferidas a partir delas.","Concluir que o porteiro buscava o prêmio com certeza, apesar da ausência de fala.","Usar conhecer nomes como comprovação de reconhecimento público."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000090","label":"P90","beforeHash":"e868f6a739e26c087111b49fddfada7617c363835917b3bc2f06f91cd4b4ebb1","afterHash":"02a17a0765e778997648eb1fcf2ab7912ada439ea0cf7a7eac69a8e33e78c3d1","patch":{"difficulty":"medium","statement":"Uma enquete foi divulgada apenas no perfil de um clube. Entre as 300 respostas, 240 apoiavam ampliar sua sede. O anúncio dizia: A cidade aprova o projeto. A cidade tinha 40 mil moradores, mas o relatório não informou como os seguidores do perfil se distribuíam entre bairros nem quem decidiu responder.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Pesquisar só associados favoráveis ao projeto, sem considerar a seleção.","Aumentar a quantidade de respostas apenas no mesmo perfil do clube.","Usar o percentual de apoio entre respondentes como percentual de todos os moradores.","Obter uma amostra representativa com método de seleção e margem de incerteza explicitados.","Tomar o total de seguidores como garantia de representação de todos os bairros."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000091","label":"P91","beforeHash":"c8529cf1f740ef6727caf11e74bc75179259fbe74339020258e4579d80ba4062","afterHash":"458147da75baad27a1a467ae6fa1a023a222fc800a1c4068b2ca840738f80dd5","patch":{"difficulty":"medium","statement":"A comissão pediu que a proposta financeira fosse revista. Ao comentar um passeio, uma aluna disse que queria rever a cidade. Um colega sugeriu empregar corrigir nas duas frases, mas a editora pediu que ele considerasse o complemento e a situação de cada ocorrência.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Decidir o sentido pelo infinitivo, sem considerar os complementos.","Substituir rever por corrigir nos dois casos antes de avaliar o contexto.","Usar a existência do mesmo verbo como prova de um único sentido.","Examinar complementos e situações de uso antes de escolher um sinônimo para cada passagem.","Trocar apenas o tempo verbal e tratar as duas ocorrências como equivalentes."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000092","label":"P92","beforeHash":"55949b3e6f6acad4b355f10bba160a5dd90c6612cefa2c8863b751dae7b26ffc","afterHash":"9cd93fe96d409903318ade0357d3f7bc971934ea72c3e434669ce8b550255bf1","patch":{"difficulty":"medium","statement":"Um comunicado dizia: Os moradores que solicitaram vistoria receberão resposta. Outra versão dizia: Os moradores, que solicitaram vistoria, receberão resposta. As palavras eram as mesmas, porém a equipe precisava decidir se o aviso se referia apenas aos solicitantes ou ao conjunto dos moradores mencionado no documento.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Retirar as vírgulas sem decidir se o aviso inclui todos os moradores ou apenas solicitantes.","Manter a pontuação e afirmar que toda oração relativa é explicativa.","Mudar o tempo verbal como se isso resolvesse a abrangência do grupo.","Definir se a intenção era atender somente solicitantes ou todo o conjunto mencionado.","Trocar moradores por habitantes e considerar eliminada a diferença entre as duas versões."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000093","label":"P93","beforeHash":"4e0e1b069f1eed65091a97c37bf9b94c73a825547456643d64999371654248d6","afterHash":"f9b807975a6a0aa173e046b2091fa23243034e777d8b4420e8b4f2e7a2b3403a","patch":{"difficulty":"medium","statement":"A nota dizia: Foram eliminados os registros duplicados. O relatório posterior dizia: A equipe de cadastro eliminou os registros duplicados. Embora os documentos tratassem da mesma ação, uma solicitação de prestação de contas pedia também a identificação de quem a executou.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Concluir que o agente não existiu porque foi omitido da primeira nota.","Consultar os registros do procedimento para identificar os responsáveis efetivos.","Alterar a voz verbal sem fornecer nem verificar o agente.","Tomar o número de registros eliminados como identificação da equipe responsável.","Atribuir a ação a uma equipe mencionada em outro caso, sem registro da execução."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000094","label":"P94","beforeHash":"7c67e51f80838de9d9f772b4601389892b1fcad57b84a61a8381843464225784","afterHash":"0ba973f56686599f0065abc60842460c67d1ea0542d3e3e7de2c44683a84225a","patch":{"difficulty":"medium","statement":"Uma editora encontrou no relatório: Fazem três meses que o projeto começou. Na página seguinte, leu: Houveram alterações no cronograma. Ela pediu a revisão das formas verbais, e não apenas a troca dos termos meses e alterações por palavras no singular.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Fazer concordância automática com meses e alterações, sem analisar o verbo.","Substituir haver por existir e comparar: Existiram alterações tem sujeito, ao contrário de Houve alterações.","Usar existir e haver com a mesma concordância em qualquer construção.","Pluralizar auxiliares de haver existencial pelo número de alterações.","Alterar só os substantivos para o singular, sem revisar o sentido."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000095","label":"P95","beforeHash":"b68810f0a3fe370d318ff39060171779c9574acea184d5a99ba0ee2609eb4271","afterHash":"1abb18e988abdf4be5f2fd78c7fa201b7d44ef9faef055353c920c52b7198434","patch":{"difficulty":"medium","statement":"No relatório, constavam: Os estudantes assistiram o documentário e O técnico assistiu o pesquisador durante o procedimento. A primeira frase tratava da exibição de um filme; a segunda, da ajuda prestada no laboratório. A revisora avaliou a regência de assistir no sentido de cada ação descrita.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Aplicar uma única regência a assistir, ignorando a diferença entre ver e ajudar.","Acrescentar de ao complemento em ambos os sentidos para uniformizar o relatório.","Retirar a preposição de ao documentário porque documentário não é pessoa.","Escolher a preposição pela presença de um complemento humano.","Identificar a ação descrita em cada frase antes de decidir a preposição."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000096","label":"P96","beforeHash":"56721bfea7363d3a9fc2d9e6d3bc2bec59b26c6c252805e990cf1c1863c7d779","afterHash":"96514c2fc64fd6d8b137a5c41cb546d2075a27f227a1a443bb8db40d9100f586","patch":{"difficulty":"medium","statement":"A ficha registrava: Entregou o documento à diretora. Outra registrava: Entregou o documento a uma diretora. Uma estudante propôs pôr acento grave nas duas, mas a editora pediu que ela comparasse os artigos e a preposição exigida pelo verbo.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Retirar a preposição de entregar para evitar avaliar a crase.","Verificar apenas o gênero do destinatário, sem a preposição.","Comparar Entregou ao diretor com Entregou a um diretor para verificar a combinação de preposição e artigo.","Considerar uma artigo definido e aplicar a mesma construção de à diretora.","Usar acento grave em todo a antes de palavra feminina."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000097","label":"P97","beforeHash":"b5aa52d0fab4417ed505597be423b43f41c326aa252dba37ab11ee5375793099","afterHash":"0a7d09c582de068f6720b271d3089ead6d5ba89c23b5f6f97f5966064c3702cf","patch":{"difficulty":"medium","statement":"O jornal publicou: A professora informou à aluna que sua inscrição estava incompleta. Um leitor perguntou de quem era a inscrição. O redator substituiu “sua inscrição” pela expressão “a inscrição da aluna” e manteve o restante da informação. A alteração passou a constar na edição seguinte.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Interpretar o possessivo sempre como referência ao sujeito.","Trocar sua por dela sem identificar a professora ou a aluna.","Identificar o referente pretendido e avaliar as leituras possíveis antes da reescrita.","Trocar informou por comunicou e preservar o mesmo possessivo.","Escolher o referente apenas pela posição mais próxima, sem verificar a intenção."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000098","label":"P98","beforeHash":"282c232a21e7d688eb2f5066c5768f142ec87da5d4cf53936313ac25fd2cde3c","afterHash":"41c86651b45ea56db1ff15bf545da9e802225dbb848dff0b3fd80d95f775f559","patch":{"difficulty":"medium","statement":"O editorial chamou a falta de planejamento de um buraco no orçamento. Na sequência, apresentou receitas e despesas para dimensionar o problema. Um leitor destacou a imagem expressiva, mas outro pediu que a avaliação se baseasse também nos valores documentados.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Concluir que a imagem figurada dispensa os valores documentados.","Usar a intensidade da metáfora como valor numérico do problema.","Avaliar somente a escolha lexical, sem confrontar os dados financeiros.","Tomar a reação dos leitores como medida de receitas e despesas.","Confrontar receitas e despesas documentadas para medir a insuficiência mencionada."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000099","label":"P99","beforeHash":"b5e37546577ee9545a8cf0542b385ab8ed6ac766e3468fdd90257e7edd074caf","afterHash":"284652b95fb385692c4499dfb247447e0dc559860cbf531dedb5f91ae16d6d1f","patch":{"difficulty":"medium","statement":"A notícia dizia: Segundo a pesquisadora, o material pode reduzir perdas. Na edição seguinte, apareceu: O material reduz perdas. A mudança retirou palavras da frase, sem acrescentar dados ou resultados ao conteúdo publicado.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Tomar uma frase mais curta como demonstração de comprovação mais forte.","Substituir pode reduzir por reduz como se não alterasse o grau de certeza.","Retirar a fonte e manter o resultado como certeza sem conferir evidências.","Usar apenas a reputação da fonte como prova da eficácia em qualquer condição.","Verificar quais testes sustentam a afirmação e conservar a atribuição e as ressalvas pertinentes."],"version":3}},{"id":"d1431000-0000-4000-8000-000000000100","label":"P100","beforeHash":"12d4585bf93fb5ec99c8d9dde89a27fa78f3bee25f21bbea3a35bd9f21704941","afterHash":"ebb1279e6f2434194fbcdf10005ea77a43a9968034fca37038eeb7611a751f11","patch":{"difficulty":"medium","statement":"O regulamento dizia: A inscrição só será aceita se o formulário estiver completo e o comprovante for enviado. Rui preencheu o formulário, mas não enviou o comprovante. A equipe recusou o pedido. Uma colega sugeriu que ele relesse os dois requisitos antes de reclamar.\n\nPara avaliar a informação ou solucionar o problema de leitura discutido, qual procedimento responde diretamente à limitação apontada?","options":["Verificar separadamente os dois requisitos e aplicar a condição conjunta prevista.","Verificar somente o envio do comprovante e ignorar o preenchimento.","Trocar e por ou na interpretação, sem alterar formalmente o regulamento.","Aceitar apenas o formulário completo, tratando os requisitos como alternativas.","Deduzir que a recusa comprova formulário incompleto, apesar de faltar o comprovante."],"version":3}},{"id":"d1090000-0000-4000-8000-000000000005","label":"C01","beforeHash":"b2ccc2b20ce35956caff73d1c81446d882304955ff122c13573257338995363b","afterHash":"9713708ee9e126c7cdd4a025da64b357cf3a3687189909f4f68d06ee6eee1ce2","patch":{"difficulty":"medium","statement":"Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve.\n\nQual previsão combina corretamente a medida de densidade e o comportamento nos dois líquidos?","version":4}},{"id":"d1090000-0000-4000-8000-000000000006","label":"C02","beforeHash":"d909a5936d15515dee9d59934373d5fadc3b52642bc9d0abfce212d9cf22c476","afterHash":"c4638de4248fa420fd0895c44fb4df3d02aaaa7e733625c65ff00560db9e4a46","patch":{"difficulty":"medium","statement":"Uma amostra contém areia e sal dissolvido em água. A areia é insolúvel e o sal não evapora nas condições usadas. O objetivo é recolher separadamente os três componentes, em procedimentos ideais sem perdas.\n\nQual sequência de procedimentos atende ao objetivo?","options":["Filtrar a areia e destilar o filtrado, recolhendo a água condensada e o sal residual.","Filtrar a areia e evaporar o filtrado em recipiente aberto, recolhendo apenas o resíduo sólido.","Destilar a amostra sem filtrar, considerando o resíduo de areia e sal como dois componentes já separados.","Filtrar a amostra, considerando que o papel retém também o sal dissolvido.","Decantar a areia e recolher o restante como se fosse água pura."],"explanation":"A filtração separa a areia insolúvel. O filtrado ainda contém água e sal; a destilação permite recolher a água e deixar o sal. Evaporação aberta não recupera a água, e destilar sem filtrar deixa areia e sal juntos no resíduo.","version":4}},{"id":"d1390000-0000-4000-8000-000000000001","label":"C03","beforeHash":"d640b8dbc326ae6c535d110192fd066d4bb875831d38fbc1bd0e0f8a8cddc625","afterHash":"e785ccad57885443504a1125dd988f52eaf81394bf9a7b74cd869910786c3d81","patch":{"statement":"Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.\n\nPara realizar a mesma transferência de água em dez minutos, qual comparação das bombas está correta?","version":5}},{"id":"d1390000-0000-4000-8000-000000000002","label":"C04","beforeHash":"d776a7651b6f3a67600c3bd2957878264de729448a14dfb07fdbbaf398486caf","afterHash":"c325293a7384daf400c46ac6ff6490a0d2e6cda1e42b41d8121bae326d61ab5e","patch":{"difficulty":"medium","statement":"Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.\n\nQual comparação das correntes totais está correta?","version":4}},{"id":"d1390000-0000-4000-8000-000000000003","label":"C05","beforeHash":"83d5b2fd9b3eef83123c3f5b49132afa74e660d477cd0787b83ee62177d19ef9","afterHash":"8bf0d53ec958d9c30db50ecdc6ac186b3f7a8b17048426a4090b8e6fbc85a73c","patch":{"difficulty":"medium","statement":"Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico.\n\nQual temperatura final satisfaz o equilíbrio de energia?","version":5}},{"id":"d1390000-0000-4000-8000-000000000004","label":"C06","beforeHash":"a87e3ddaa177e7d04464f9713592306e8f82b61a7ce5aaeb07acd3d42febc7a5","afterHash":"abed75e82301eb40db1f611a879c8ac603f2e4a60c0ad04f4689cbfc2c0dc516","patch":{"difficulty":"medium","statement":"Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQue comparação permite avaliar o efeito da intensidade luminosa mantendo as outras condições descritas?","explanation":"A e B diferem na intensidade da luz, mas mantêm as condições iniciais comparáveis. A e C variam gás carbônico; Entre as alternativas, as demais comparações não isolam a intensidade: A/C varia gás carbônico; B/C e C/D variam gás carbônico e luz; D sozinho não oferece comparação.","version":5}},{"id":"d1390000-0000-4000-8000-000000000005","label":"C07","beforeHash":"aede1114784d5aa4760d2a1020a0624564717161c9c61450a03a7c90c19dca61","afterHash":"7244c1fe9927a2454123eff8f24b5c19c92688e306b2ddf8751afe5ddcb95ba7","patch":{"difficulty":"medium","statement":"Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final.\n\nQue energia fica disponível ao predador final no modelo?","version":5}},{"id":"d1390000-0000-4000-8000-000000000006","label":"C08","beforeHash":"0a6e4da93c59c5577e2c3cc0478f7cc5a563b62d16942adb0f33a9af01e73b31","afterHash":"715a89335449abb42aa493de962ff6188eee1d1cb60cdb8c8f3116cee4d7e0bc","patch":{"difficulty":"easy","statement":"Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação dos alelos, fecundações independentes e igual viabilidade dos genótipos.\n\nQual probabilidade de um descendente apresentar a característica recessiva?","version":4}},{"id":"d1390000-0000-4000-8000-000000000007","label":"C09","beforeHash":"ab646365dac4fef3ee8656f5856c8f7b329d82dad5403c51c1e45158d94d87e5","afterHash":"c35a7a5d5ef4e1bc5633325b6f0fa5b63017b3be3e209140c7183043ce07d1fa","patch":{"difficulty":"medium","statement":"Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. Todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.\n\nApós a exposição, a proporção de resistentes cresce. Qual mecanismo explica isso no modelo apresentado?","version":5}},{"id":"d1390000-0000-4000-8000-000000000008","label":"C10","beforeHash":"5c9dcfaf002a99591cf4e9d7aac9e5e358239446edfa9952b2783a2d535ce597","afterHash":"8caf53a742e469d12ce65701f0ea6d30e6aeaad11763f1d51a85600f3552b980","patch":{"difficulty":"medium","statement":"Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra, pressões hidrostáticas inicialmente iguais e ausência de transporte ativo no período.\n\nQual direção inicial do fluxo líquido de água é coerente com as três situações?","version":4}},{"id":"d1390000-0000-4000-8000-000000000009","label":"C11","beforeHash":"9a469924e81423d65dcb74e72d907fcfb9ff1526377f314cc169008d138beefc","afterHash":"578d22c14449085d6d2f2d492df21b5edfb02c4f1a619d350d34c2e082b718d9","patch":{"difficulty":"easy","statement":"Uma solução contém 12 g de soluto. Acrescenta-se água até o volume total chegar a 600 mL, sem perda ou adição de soluto.\n\nQual é a concentração final, em g/L?","options":["20 g/L","80 g/L","6 g/L","60 g/L","30 g/L"],"explanation":"A massa de soluto continua em 12 g e o volume final é 0,600 L. Logo, a concentração é 12/0,600 = 20 g/L. Deve-se usar o volume final em litros, sem alterar a massa de soluto.","version":4}},{"id":"d1390000-0000-4000-8000-000000000010","label":"C12","beforeHash":"09581524fc2f7c87784a01d3d404d2ccf5b3a4e57f99208709e18e33a79e40b5","afterHash":"208ba49bb3e41840a58a00c509e246e8cded90caf39078682a95e7a65966cfc7","patch":{"difficulty":"medium","statement":"Um frasco fechado contém 5 g de bicarbonato e 25 g de solução ácida. Ao misturá-los, forma-se gás e o recipiente permanece vedado. A balança continua marcando 30 g de conteúdo. Em outro ensaio igual, o recipiente é aberto e parte do gás escapa, deixando 28 g de conteúdo medido.\n\nQual interpretação das duas pesagens é compatível com a conservação da massa?","version":5}},{"id":"d1390000-0000-4000-8000-000000000011","label":"C13","beforeHash":"1e760281ef1f2cbcd4e698722cba78055f800429110f629766311b537002312a","afterHash":"dddea61e0f21c9c369693b165672a32e83dfa7e75c604c8f03483adf013c70c8","patch":{"difficulty":"medium","statement":"Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.\n\nComo as pressões médias se comparam?","version":4}},{"id":"d1390000-0000-4000-8000-000000000012","label":"C14","beforeHash":"b5abf9f015a1582e9ff9b2bdcd7f02a029e24bfd87161bb7c30407b2ae901a42","afterHash":"ed37f8049b8dd78e7a3be027631c6b379702e397e60b885fc2a4c8cb08b24ea0","patch":{"difficulty":"medium","statement":"Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ.\n\nQuais comprimentos de onda resultam nos dois meios?","version":4}},{"id":"d1390000-0000-4000-8000-000000000013","label":"C15","beforeHash":"0b94ed87e4179eb6c08e8ef8100093b2fb716bb68ccaa52a61cc7e5ed9721508","afterHash":"537fbc100951e6629cd34006f02aca90af332e9387c678dafe9050619e490ff5","patch":{"difficulty":"medium","statement":"Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem.\n\nQual mecanismo explica a inversão das durações de luz entre junho e dezembro nos dois hemisférios?","version":5}},{"id":"d1390000-0000-4000-8000-000000000014","label":"C16","beforeHash":"4cc2a9d75c7510cc247c1d52c1bd4016f52e2a3ed1164edc6d9004244532f89e","afterHash":"b58e87634a5800b4a9b5430803088f816ab12733bc0d36ede58e3fc1b2476d53","patch":{"difficulty":"medium","statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQue inferência é compatível com a comparação entre os frascos?","version":4}},{"id":"d1390000-0000-4000-8000-000000000015","label":"C17","beforeHash":"54486da4b22759150aa2f02961b835c7149d46fd86a07e2845639a6cdd781710","afterHash":"83c0019df9648a9f7562933b66682c19b19425215c4b51a1d3e2dd618b51fa4d","patch":{"difficulty":"medium","statement":"Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.\n\nQual sequência de processos é compatível com a queda noturna do oxigênio após a entrada de nutrientes?","version":5}},{"id":"d1390000-0000-4000-8000-000000000016","label":"C18","beforeHash":"270ca35a83c55fc09a4c89a0faf8cdd65d1f4053fcedf55a079636680e09319a","afterHash":"09fc1defb0fca56262af2d22acd57700dd8cb2fa1f151b28b2f57e75bebfaa0b","patch":{"difficulty":"medium","statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos.\n\nQue leitura distingue esse crescimento de uma duplicação indefinida?","version":4}},{"id":"d1390000-0000-4000-8000-000000000017","label":"C19","beforeHash":"f2199351bde1c2d7335cefc8fa15a9da5e0cfc65bea15d209e8a0bc531599adc","afterHash":"9e7d1005d67295022b85d7d5458942f50f6935c8ff3d55fc401daa322ded38fe","patch":{"difficulty":"medium","statement":"Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.\n\nQual comparação dos limites é coerente com as evidências?","version":4}},{"id":"d1390000-0000-4000-8000-000000000018","label":"C20","beforeHash":"b2799d53a375e4bb120471ec55d2b44f1f1e0365e178f55258e47f386ac478db","afterHash":"0177586e6fa34759bb92be5ff76f7bb1d683da6819c1735692ac1f7f6239e5bd","patch":{"difficulty":"medium","statement":"Duas caixas idênticas, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nPor que a caixa revestida de espuma conserva mais gelo nas condições do experimento?","version":5}},{"id":"d1432000-0000-4000-8000-000000000021","label":"C21","beforeHash":"18d547d49592c1ee532f4a4f46d24b0caf858e53ff2c75f6bafae2a13b47b29d","afterHash":"805a8d38345fd6db26266bf411520af195ba75c0314b30c5f507929af7d6a869","patch":{"difficulty":"medium","statement":"Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve.\n\nNa água, que volume precisa ficar submerso para que a massa de água deslocada iguale os 240 g do objeto?","version":3}},{"id":"d1432000-0000-4000-8000-000000000022","label":"C22","beforeHash":"dfd4866e8e32d8b6bba9069fa3c851d3c7011bd88da992eab1afd97d6f01f2a5","afterHash":"775ccf80b6d3ea4403a73aec1d9e9e875ecc3bc71ab93e0e06ba7655aa49155c","patch":{"difficulty":"easy","statement":"Após separar 20 g de areia por filtração sem perdas, obtém-se uma solução homogênea de 30 g de sal em 150 g de água. A solução é dividida em duas partes de mesma massa. Uma delas é evaporada em recipiente aberto até secar, sem decomposição nem perda de sal.\n\nQual massa de sal fica nesse recipiente?","options":["90 g","30 g","10 g","15 g","75 g"],"explanation":"Cada metade homogênea contém metade do sal: 30/2 = 15 g. A evaporação remove a água dessa metade, mas não o sal, que fica no recipiente.","version":2}},{"id":"d1432000-0000-4000-8000-000000000023","label":"C23","beforeHash":"691bc856dcb84f9933b1d90981f6049aab83a87e5d81004a6c32b3ce78e16e94","afterHash":"4999bc9ecc7aa2009762749adb1bb7796be8bba62c070f95f101a36978ae8002","patch":{"difficulty":"medium","statement":"Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.\n\nQue energia útil a primeira bomba fornece nos dez minutos, em joules?","version":2}},{"id":"d1432000-0000-4000-8000-000000000024","label":"C24","beforeHash":"0a11b87a9da585050989ad950fea6748cb1fd9467c5774e5d8ea2ec30e6ab62b","afterHash":"ca3c82183d73f26ed9b247da1612944ed7e30c0226b2a8db8b9c2f3fda49b3f3","patch":{"difficulty":"easy","statement":"Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.\n\nQual diferença de potencial aparece em cada resistor em série?","version":2}},{"id":"d1432000-0000-4000-8000-000000000025","label":"C25","beforeHash":"6e26edcc4d71a5cad20bef2c9755feb41374b4fac3fe93bd51eb584696a32350","afterHash":"962b7599d86a990a4b74c9930b86eb0d0166ac521a3a3dc3c29ea608fdc17bbb","patch":{"difficulty":"easy","statement":"Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico.\n\nSe as duas massas fossem iguais, mantendo as temperaturas iniciais, qual seria a temperatura final ideal?","version":3}},{"id":"d1432000-0000-4000-8000-000000000026","label":"C26","beforeHash":"1324dbebc93b0371072d144617c9fac3b94f890c3168f479fbf54a962a3e581d","afterHash":"af7e16a277d128f87cdb3b6a12016cb9090d6dc666441d59e6a17d27f0ecb89d","patch":{"difficulty":"medium","statement":"Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQue interpretação é sustentada pela comparação entre A e C?","version":3}},{"id":"d1432000-0000-4000-8000-000000000027","label":"C27","beforeHash":"874d7059c563da811bacce0fec9faafea5ecff6fe268d7beda0b30c862287e2e","afterHash":"15f934b328d8673ef879650d7f18c68dd2c858a048d684602e545d98ae3326d9","patch":{"difficulty":"medium","statement":"Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final.\n\nSe o consumo humano ocorrer diretamente no nível dos herbívoros em vez do predador final, qual comparação de energia entre esses níveis decorre do modelo?","version":3}},{"id":"d1432000-0000-4000-8000-000000000028","label":"C28","beforeHash":"05af32c1c6473575906dcd261203a0001bb4147b0332ffa22e61cbb7cdecb5b5","afterHash":"2e1b5d1502cf9f19e7dcd193d83446673150f736f7692ed6820c4e17907b674e","patch":{"statement":"Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação dos alelos, fecundações independentes e igual viabilidade dos genótipos.\n\nEntre os descendentes que não apresentam a característica recessiva, que fração esperada é heterozigota?","version":2}},{"id":"d1432000-0000-4000-8000-000000000029","label":"C29","beforeHash":"a4736da4ee4bcac31794d66c0dd96174829ac7099ecaf02c5f62aab1c1355a6b","afterHash":"679e6003a226d64948ae943e4025fba960dc1f978b94df2843d119e31ef6eb25","patch":{"difficulty":"easy","statement":"Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. Todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.\n\nQuantas bactérias sensíveis sobrevivem sob as condições descritas?","version":3}},{"id":"d1432000-0000-4000-8000-000000000030","label":"C30","beforeHash":"74d324ecb5baead5465705c7b7b9994f2da0b50569bcc89f7ea8bca5e6542474","afterHash":"f430de536ebe7f7cb3eb5cc4142e9e619f4b8958f7caba274f5f6be7a30f9d8b","patch":{"difficulty":"medium","statement":"Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra, pressões hidrostáticas inicialmente iguais e ausência de transporte ativo no período.\n\nQual comparação descreve a diferença entre célula vegetal e uma célula sem parede sob condições hipotônicas?","version":2}},{"id":"d1432000-0000-4000-8000-000000000031","label":"C31","beforeHash":"60e40808adb11ff9d18537f11015d91decda6197a09aafc5022a566dd60118c6","afterHash":"b14fb1565227e2d3968ee98bff68bc7ccb4a8c3966623a40a1531c35e5efedcb","patch":{"difficulty":"medium","statement":"Uma solução homogênea contém 12 g de soluto em 600 mL. Retiram-se 150 mL dessa solução.\n\nQual massa de soluto foi retirada?","explanation":"A porção retirada corresponde a 150/600 = 1/4 do volume. Por ser homogênea, ela contém 1/4 da massa de soluto: 12/4 = 3 g.","version":2}},{"id":"d1432000-0000-4000-8000-000000000032","label":"C32","beforeHash":"7607d1f8caddb77ac3077ead2c23681cc8ffea8e0bf7e4c0c51dec1129fc6e70","afterHash":"6a1b0625c21fe994aa5552d6d517d6b8c02542535ed105124cc12c2824196b83","patch":{"difficulty":"easy","statement":"Um frasco fechado contém 5 g de bicarbonato e 25 g de solução ácida. Ao misturá-los, forma-se gás e o recipiente permanece vedado. A balança continua marcando 30 g de conteúdo. Em outro ensaio igual, o recipiente é aberto e parte do gás escapa, deixando 28 g de conteúdo medido.\n\nQual massa do conteúdo é esperada no frasco fechado antes e depois da reação ideal?","version":2}},{"id":"d1432000-0000-4000-8000-000000000033","label":"C33","beforeHash":"e95daab63f2bc8d98820775828bba5558ce09874c85c9fc74c8be7ceb94aaf08","afterHash":"b3dbeffc354b6e5c94f9fc3ca3c58a1eabcb31c1da0989faacad3b4e360c2405","patch":{"difficulty":"medium","statement":"Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.\n\nQue área seria necessária para limitar a pressão média a 5.000 Pa?","version":2}},{"id":"d1432000-0000-4000-8000-000000000034","label":"C34","beforeHash":"b1ce67946148b6df4b95c0e095a21ace5fc02a0709a4fe9442819341c0095f3a","afterHash":"f7e4e733986e5d1ecba70892162e06da2eb6ee0303a2903668bd004ea632a1de","patch":{"difficulty":"easy","statement":"Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ.\n\nQual é o período da fonte?","version":2}},{"id":"d1432000-0000-4000-8000-000000000035","label":"C35","beforeHash":"c5ddacf8de0dbb181f08a22c29c00a49fa4d6fe8997abd52ba4b0b0d5abdc824","afterHash":"3957871735d02b4f060080d02f286e93b40394931b5f23a74d1d63943ab6fb07","patch":{"difficulty":"easy","statement":"Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem.\n\nQue diferença de tempo de luz a cidade sul apresenta entre os dois meses do exemplo?","version":3}},{"id":"d1432000-0000-4000-8000-000000000036","label":"C36","beforeHash":"267a0219f4b380268446d589543722e44c32c8b692035ab654413a972cb4e8fe","afterHash":"1877c94ac25b9af49bba249c4c95b62a34875e3d00bf79e6ce3186ea214a4c6f","patch":{"difficulty":"medium","statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQual redução relativa da concentração de oxigênio ocorre em A, tomando 21% como referência inicial?","version":2}},{"id":"d1432000-0000-4000-8000-000000000037","label":"C37","beforeHash":"2c88433c4e7e307c846e4e7a63c075bf168127048367ec684ebf79aa50be684e","afterHash":"3070e0a898200717ce32d423efada0f861351169bb6dd3f8f3a6d7c7bfc13aed","patch":{"difficulty":"easy","statement":"Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.\n\nQual é a queda percentual em relação aos 8 mg/L anteriores?","version":2}},{"id":"d1432000-0000-4000-8000-000000000038","label":"C38","beforeHash":"a74519751a2be2362c87fdae5a1378e70ebddc53b0f5b4709dcc8efab9b25ebc","afterHash":"b586886154955eee274b82c764c7917a4cb07518ceeb3ff6c50637f1ee57f0a7","patch":{"difficulty":"easy","statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos.\n\nQual crescimento relativo ocorre de 200 para 320 indivíduos?","version":2}},{"id":"d1432000-0000-4000-8000-000000000039","label":"C39","beforeHash":"eb6e01b054fa4adf0cd8c2d9a3759e1b11896eab84f59e04eea9552b2b6efe25","afterHash":"eed4ac397ffa28b08b13983487bc74427c1769346befa6610b46bb83b5bfb141","patch":{"difficulty":"medium","statement":"Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.\n\nPor que o conjunto de montanhas, vulcões e terremotos é mais informativo que um evento isolado?","version":2}},{"id":"d1432000-0000-4000-8000-000000000040","label":"C40","beforeHash":"a71136c99a743ea19e61a23b46a07b5b0c1c11a6e37192de7845cfaa63dba69e","afterHash":"145197902343daca83c91162aa42ebf1856bb6b6675a8d1d72cea0536725d197","patch":{"difficulty":"medium","statement":"Duas caixas idênticas, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nQual variável deve permanecer comparável para atribuir a diferença ao revestimento?","version":3}},{"id":"d1432000-0000-4000-8000-000000000041","label":"C41","beforeHash":"e3652c489b56deba5d4ec9fb91f785d02abe30c27d7c1bc3c01a4b17b6b463e2","afterHash":"0cfa4fbab117daf26db83df0d36d5110971cf08a271c422d051cdfd7c45da421","patch":{"difficulty":"easy","statement":"Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve.\n\nUm segundo objeto do mesmo material tem 600 cm³. Qual massa e comportamento na água são coerentes com a homogeneidade do material?","version":3}},{"id":"d1432000-0000-4000-8000-000000000042","label":"C42","beforeHash":"9190b1d621bd1a59184ce2678517e7191b9e39e18f6df98ca41802c3c8b0e9d7","afterHash":"03c1f9557c1b81fe86dc3efe82fd5bcdadedd7789e94147eb6128d64e1c10671","patch":{"difficulty":"easy","statement":"Uma solução homogênea de 30 g de sal em 150 g de água é dividida em duas partes de mesma massa. Uma metade é destilada com coleta completa do vapor condensado. O sal não é volátil nas condições do processo.\n\nQual massa de água é recolhida na destilação dessa metade?","options":["150 g","90 g","15 g","60 g","75 g"],"explanation":"A divisão da solução homogênea reparte também a água: 150/2 = 75 g em cada metade. O destilado recolhido é a água; os 15 g de sal da metade permanecem no recipiente aquecido.","version":2}},{"id":"d1432000-0000-4000-8000-000000000043","label":"C43","beforeHash":"2e61f85f975d5140ac29035fa75045f16d21e31e268b106dcb62c845fcef90d6","afterHash":"a1631be1168e694500325f86150270f9be7f25fa02b4396474c56e8bdd6256b6","patch":{"difficulty":"medium","statement":"Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.\n\nQual energia a primeira bomba dissipa no mesmo intervalo?","version":2}},{"id":"d1432000-0000-4000-8000-000000000044","label":"C44","beforeHash":"dbe0117c37d47171443baec7739b8abd42fe7b625d1f5253de3edb4072242aab","afterHash":"45b49f6d9533b8d68a323e071982c3705d6d53ad80a3f1b6c1eb0bf928fe6007","patch":{"difficulty":"medium","statement":"Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.\n\nQual potência total é dissipada no circuito em paralelo?","version":2}},{"id":"d1432000-0000-4000-8000-000000000045","label":"C45","beforeHash":"a6e80e451c6202e7e0448646f16690d105087697fddb3c4c89faee6fadf25884","afterHash":"2969935fa6651e7c2c9fa57e7ccfea9167f29a4867e75a29ce141c3af7f0f0ef","patch":{"difficulty":"medium","statement":"Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico.\n\nMantendo 200 g de água quente, que massa de água a 15 °C produziria temperatura final de 45 °C?","version":3}},{"id":"d1432000-0000-4000-8000-000000000046","label":"C46","beforeHash":"6930cd4120c878b885fe905df749fcce3e08fa581a9755d5188bff14487e0ca8","afterHash":"d56247369c8e6b6a8811390fb3a4029010fbb77feb0a0b0840e8277220f53e10","patch":{"difficulty":"medium","statement":"Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nA ausência de bolhas em D permite concluir o quê, sem extrapolar o indicador?","version":3}},{"id":"d1432000-0000-4000-8000-000000000047","label":"C47","beforeHash":"28ce448330bcd0f3296f9173d855961090e64e2228b5c3f6f99fd0afbeca6e80","afterHash":"b1c21c4513c486fa7ab01acd6083e13b2f008991c1076217006563c2603dbec8","patch":{"difficulty":"medium","statement":"Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final.\n\nO que acontece com a energia que não chega ao nível seguinte?","version":3}},{"id":"d1432000-0000-4000-8000-000000000048","label":"C48","beforeHash":"1752f3225ac9b7176678673cb9ed0a5078e24f6f701594c1425702a54b1e2aa2","afterHash":"f6a94095470412e5c5afbe9b90f848e65650ea3fe54ae6f217e3193c3b3a6e28","patch":{"difficulty":"medium","statement":"Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação dos alelos, fecundações independentes e igual viabilidade dos genótipos.\n\nQual chance de dois descendentes independentes serem ambos aa?","version":2}},{"id":"d1432000-0000-4000-8000-000000000049","label":"C49","beforeHash":"f2cf85a2c7b639686ba348aeed7af7fd06584fc798d6426335ea4f0582578b5a","afterHash":"0d59a4a77b86abc4f249ee4273b5fb3d4d8118dc46f2762fe0b93beab40ff014","patch":{"difficulty":"medium","statement":"Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. Todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.\n\nQue proporção aproximada dos sobreviventes é resistente?","version":3}},{"id":"d1432000-0000-4000-8000-000000000050","label":"C50","beforeHash":"03be843ef047df9419510e2bb52921b62abbfe99a061a54357b41d966e2b5d35","afterHash":"ec8afe08b200939c7699f331716a8990f9bda4e85ceae4d668c89bbe15d0d8b3","patch":{"difficulty":"medium","statement":"Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra, pressões hidrostáticas inicialmente iguais e ausência de transporte ativo no período.\n\nEm III, o citoplasma se retrai e a membrana se afasta parcialmente da parede. Qual explicação é compatível com o enunciado?","version":2}},{"id":"d1432000-0000-4000-8000-000000000051","label":"C51","beforeHash":"9b7141dd1c42eec113b6c1acce35f8891c7e2a3fdec42c07bbcecedae3cb86d3","afterHash":"4116f2b0c2b0304b632c5f60ce2a562037c82ada79f28bc2b9272eace606859d","patch":{"difficulty":"medium","statement":"Uma solução homogênea contém 12 g de soluto em 600 mL. Retiram-se 150 mL, sem acrescentar água ou alterar o soluto.\n\nComo fica a concentração da solução que permanece no frasco?","options":["Permanece em 20 g/L, pois restam 9 g em 450 mL.","Sobe para 60 g/L, pois a retirada reverte a diluição anterior.","Sobe para 26,7 g/L, pois sai água, mas se considera que todo o soluto permanece.","Cai para 5 g/L, pois a porção retirada é confundida com a solução restante.","Cai para 15 g/L, pois sai um quarto do soluto e o volume é considerado constante."],"explanation":"Retirar 1/4 de uma solução homogênea retira a mesma fração de soluto e de volume. Restam 9 g em 0,450 L: 9/0,450 = 20 g/L. Transferir uma porção não concentra nem dilui a parte restante.","version":2}},{"id":"d1432000-0000-4000-8000-000000000052","label":"C52","beforeHash":"0aae5d2a0a8620aefb78b0e38f7fc90150f092bcb02c0fc008f6d65b69a68494","afterHash":"de385a4447f53f56db5eb349d99deb171a1dd01674ad79d0bad47710258a9e05","patch":{"difficulty":"easy","statement":"Após reagirem 5 g de bicarbonato de sódio com 25 g de solução ácida, um frasco aberto tem 28 g de conteúdo. Em seguida, saem mais 0,5 g de gás, sem outras trocas de matéria.\n\nQual massa de conteúdo será medida após essa saída adicional?","options":["26,5 g","28,5 g","27,5 g","29,5 g","27 g"],"explanation":"A saída adicional reduz a massa de 28 para 27,5 g: 28 − 0,5 = 27,5. A perda total é de 2,5 g de gás, compatível com a quantidade de bicarbonato informada; o gás que saiu continua existindo fora do frasco.","version":2}},{"id":"d1432000-0000-4000-8000-000000000053","label":"C53","beforeHash":"9cfab16bca78dfa6381e62fcfb15e5ef328ecb5ce20bb0cea18bd3197314217f","afterHash":"0d4044cd43668b485d22e9d0368c29d24ef98d52e589255061f2aa0cce9f7cca","patch":{"difficulty":"easy","statement":"Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.\n\nSe a força aumentar para 1.200 N, mantendo o apoio II, que pressão resulta?","version":2}},{"id":"d1432000-0000-4000-8000-000000000054","label":"C54","beforeHash":"f79c09c7e5405bdaaef81bc15b9c7dc0461922ec538535b3d097b0abae3eb6e0","afterHash":"b1a6e8f0b6d258e3d7f2c64afb939e543119e50f2f5213504eb6b0d9522db0b1","patch":{"difficulty":"medium","statement":"Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ.\n\nQue mudança ocorre na quantidade de comprimentos de onda contidos em um trecho de 20 m após entrar em II?","version":2}},{"id":"d1432000-0000-4000-8000-000000000055","label":"C55","beforeHash":"7c307860de8e00682786f0c34ddab5dcb1be1dfbe8a3684bff33fbbfc320ccdd","afterHash":"828299d43c5199941d05e12e98c1465406ce834a12184aea6a08710f213b474c","patch":{"difficulty":"medium","statement":"Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem.\n\nQue observação contradiz mais diretamente a explicação baseada só na aproximação de toda a Terra ao Sol?","version":3}},{"id":"d1432000-0000-4000-8000-000000000056","label":"C56","beforeHash":"3d47688981cf4415bb67f654656a41976fc5e01e5fefb2ea93500c584fbee6b7","afterHash":"85d14da3fadf466b6ced50a0723f20f25624f8752134fd10fb3e2b51b04106ab","patch":{"difficulty":"medium","statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nPor que o frasco B é relevante para a interpretação?","version":2}},{"id":"d1432000-0000-4000-8000-000000000057","label":"C57","beforeHash":"1d7bc33163666e82199edf1757780b0e94274b563e7fe3f5462ab4b218e16810","afterHash":"9fceb1a0656f1c99bab39ea9529996a174870b067923b7493a110fb5693633a2","patch":{"difficulty":"medium","statement":"Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.\n\nPor que a queda pode se intensificar à noite?","version":2}},{"id":"d1432000-0000-4000-8000-000000000058","label":"C58","beforeHash":"ad1bfe35e427d1b68c7e80c823e3b3cf88e14633f556e3d468db9550308af734","afterHash":"f2a4d7f7c0300e711cc1712f23b93e75ec91a3f44b3be745fe5ad54ed4913c0c","patch":{"difficulty":"medium","statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos.\n\nQue mudança pode alterar o patamar próximo de 400?","version":2}},{"id":"d1432000-0000-4000-8000-000000000059","label":"C59","beforeHash":"16dda1c8c2cb88278c7453989d780f81b55256f57b82401937eab7ba1672c10a","afterHash":"4797b6cec98105cfbb7fabf9bbd924fbfaef7d0871c1aff7f41dcfa5cb83359e","patch":{"difficulty":"medium","statement":"Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.\n\nQual processo mantém aproximadamente o balanço de crosta oceânica ao longo do tempo geológico?","version":2}},{"id":"d1432000-0000-4000-8000-000000000060","label":"C60","beforeHash":"a1993cc65c289c7277f2a37290a1bc3d2064b6a1956a1366c44c71333a3dd06c","afterHash":"9962b971241cf260b58ddef8f8a0e34b886f890700587f387e424ee6d619cbd2","patch":{"difficulty":"medium","statement":"Duas caixas idênticas, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nSe o conteúdo estivesse quente e o ambiente frio, qual previsão sobre a espuma seria coerente?","version":3}},{"id":"d1432000-0000-4000-8000-000000000061","label":"C61","beforeHash":"e5cf6ca8a151a0044f928503b8a86afa2a03ae0b6349075246bd2ccfdcf2cacb","afterHash":"9626b1d05348d24febb10614884bfc8940b0a6b2c4c21d9be890f99c37ce581b","patch":{"difficulty":"medium","statement":"Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve.\n\nUma cavidade fechada reduz a massa do objeto para 180 g, mantendo o volume externo de 300 cm³. No segundo líquido, qual previsão decorre do modelo?","version":3}},{"id":"d1432000-0000-4000-8000-000000000062","label":"C62","beforeHash":"e7c671508c5162b5444da936b6d060c7ef3ab33cf9ad92454300d4aef912370e","afterHash":"c711b061e8984bcee96e8707fd83c920449a552225eaa2bc1da0f624af995689","patch":{"difficulty":"medium","statement":"Uma solução de sal não volátil é destilada. Durante o aquecimento intenso, observa-se projeção de pequenas gotas da solução para o tubo ligado ao condensador. O líquido recolhido apresenta sal.\n\nQual mecanismo explica a contaminação do destilado?","options":["Arraste de gotículas da solução para o condensador.","Transformação do sal em água durante a condensação.","Separação completa do sal no recipiente aquecido, sem nenhum transporte de solução.","Evaporação do sal junto com a água, apesar de o sal ser não volátil nessas condições.","Retenção da água pelo sal, seguida de passagem apenas do sal pelo tubo."],"explanation":"As gotas carregam sal dissolvido por transporte mecânico. Isso contamina o líquido recolhido sem exigir que o sal vaporize. O problema é o arraste de solução, não uma mudança da volatilidade do sal.","version":2}},{"id":"d1432000-0000-4000-8000-000000000063","label":"C63","beforeHash":"91a8fc58ec7145094dc697e6d459a15a4a1b8663ed0097d888299432aed21a47","afterHash":"48e3789e7ee6dc0e43b7d4125ec0faebb7d15dd3aeba8c5735b7b3ba8b87287e","patch":{"difficulty":"medium","statement":"Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.\n\nUma fonte fornece apenas 500 W. Qual bomba pode manter os 420 W úteis nas condições descritas?","version":2}},{"id":"d1432000-0000-4000-8000-000000000064","label":"C64","beforeHash":"5d805d13930dfc190b4af94bd4d9b1cee812da42cdd20c4750c2069ab2444504","afterHash":"49ccbff079d9df97e085323a6b31678616d6c8be4fb8ffcb1e7258296127a2fd","patch":{"difficulty":"medium","statement":"Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.\n\nSe um resistor é retirado de cada circuito, deixando os fios restantes sem criar atalhos, qual mudança descreve o resultado?","version":2}},{"id":"d1432000-0000-4000-8000-000000000065","label":"C65","beforeHash":"1a0474f71074af77c8ab6fbea6c1c7247b598db9339712fba9c84e6c1de59b1a","afterHash":"8eb2f9550e699e27d44a9625fc3775bb316fc00ddf75c8685cef2b8284ad4790","patch":{"difficulty":"medium","statement":"Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico.\n\nUma medida de 12 °C após a mistura inicial é compatível com quais condições?","version":3}},{"id":"d1432000-0000-4000-8000-000000000066","label":"C66","beforeHash":"fbd40e134c630304b3b14c4d1056adadc54c113d4dd67024dbbd6b0be1a1ea24","afterHash":"e4ae047b46f0571802133ac54f0d4db2c41f10b5cf83d3f9de571323760f2d23","patch":{"difficulty":"easy","statement":"Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQual razão entre as contagens de A e B resume o resultado, sem afirmar precisão sobre a massa de oxigênio?","version":3}},{"id":"d1432000-0000-4000-8000-000000000067","label":"C67","beforeHash":"5e070773708d2de965f8166c7f6b0b636f2ca370dae17ab04d721a50c92b7d4e","afterHash":"45e6649725ce9e4238569a03a7f675c60b36a0958079065d3783280edec86924","patch":{"difficulty":"easy","statement":"Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final.\n\nSe a energia inicialmente armazenada cair para 40.000 kJ, mantendo as eficiências, qual é a nova disponibilidade ao predador final?","version":3}},{"id":"d1432000-0000-4000-8000-000000000068","label":"C68","beforeHash":"751a507bc32f39cef98d1adb30d32d3299be28bd94587bed80842be845e7ac7e","afterHash":"3990c7ec13283752bac535a11f51073d8a91af56ffe2279b2524c3254234bc21","patch":{"difficulty":"medium","statement":"Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação dos alelos, fecundações independentes e igual viabilidade dos genótipos.\n\nO nascimento de um descendente aa altera a probabilidade de aa no próximo nascimento sob as hipóteses dadas?","version":2}},{"id":"d1432000-0000-4000-8000-000000000069","label":"C69","beforeHash":"59d7f7c96889a2c6a20aea8c5a230c7cb306891eb73bebbdc28ea890cf4f8ff7","afterHash":"d1f3c22df745f67b59978d8e995d584deaace0b4564ba10018be2c6a053e3ccb","patch":{"difficulty":"medium","statement":"Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. Todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.\n\nQual conclusão é inadequada ao modelo mesmo após várias gerações sob a mesma seleção?","version":3}},{"id":"d1432000-0000-4000-8000-000000000070","label":"C70","beforeHash":"84f5ea19b2bbd4743fc9ddcbea445d059a53e783270bc7862536cecf495e5a75","afterHash":"1332541860f93aeedf048b57573ada0a7b1e4f65032d323f2320a86cfa9980ca","patch":{"difficulty":"medium","statement":"Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra, pressões hidrostáticas inicialmente iguais e ausência de transporte ativo no período.\n\nSe células de III forem transferidas a I antes de dano irreversível, que mudança se espera inicialmente?","version":2}},{"id":"d1432000-0000-4000-8000-000000000071","label":"C71","beforeHash":"22c689b0597da413a44bd10e1f5a21740b802e824fa3f9732c725081d5709cc2","afterHash":"a6c3ab2a75323fc66e762b40ab18efe6b0c8b0ec0fc71e73ee4e28fcb3789002","patch":{"difficulty":"medium","statement":"Uma porção de 150 mL de solução tem concentração de 20 g/L. Acrescenta-se água até o volume total dessa porção chegar a 300 mL, mantendo todo o soluto.\n\nQual concentração resulta dessa nova diluição?","options":["15 g/L","20 g/L","10 g/L","40 g/L","5 g/L"],"explanation":"A porção contém 20 × 0,150 = 3 g de soluto. No volume final de 0,300 L, a concentração é 3/0,300 = 10 g/L. Dobrar o volume sem mudar a massa reduz a concentração à metade.","version":2}},{"id":"d1432000-0000-4000-8000-000000000072","label":"C72","beforeHash":"3ed49a2b8b3e76bc86838e45a6d5ef82e719caa9aa1c81adca7c1b76084c236b","afterHash":"869fdb5ee1361e10f631860d611b92c510636d2975672095c62f93a64e769dee","patch":{"difficulty":"medium","statement":"Um frasco fechado contém 5 g de bicarbonato e 25 g de solução ácida. Ao misturá-los, forma-se gás e o recipiente permanece vedado. A balança continua marcando 30 g de conteúdo. Em outro ensaio igual, o recipiente é aberto e parte do gás escapa, deixando 28 g de conteúdo medido.\n\nQue característica permite distinguir a reação de uma simples mudança de estado no relato?","version":2}},{"id":"d1432000-0000-4000-8000-000000000073","label":"C73","beforeHash":"5e2d521a0fc06c80a2c45d4c478deef79352595c65800c0ef4260381b56b753c","afterHash":"d261f75a433ebd51f6b4a8946b7ba1aa8f372b04159fc1604c8cf16eeeb307f7","patch":{"difficulty":"easy","statement":"Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.\n\nQue aplicação usa o mesmo princípio para reduzir pressão sobre solo pouco resistente?","version":2}},{"id":"d1432000-0000-4000-8000-000000000074","label":"C74","beforeHash":"e261b44b104f44195faab7abf6b0238ec5f4a05f889edd10a8cbf792d786a54d","afterHash":"af223b280ddfff02c282098e7920b5557d6073009251f33983ac60b2b50afbc6","patch":{"difficulty":"medium","statement":"Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ.\n\nA velocidade menor em II prova que a onda perdeu metade de sua energia?","version":2}},{"id":"d1432000-0000-4000-8000-000000000075","label":"C75","beforeHash":"736e66fb4a1a81708fdd38c47b3b08475e02cb06174c156e142746ace5980ace","afterHash":"ce0fd116b9b16be5898c7d8e181604899906d77cce3c46319aa3ff939009b829","patch":{"difficulty":"medium","statement":"Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem.\n\nSe o eixo não tivesse inclinação, mantendo a translação, o que mudaria no mecanismo descrito?","version":3}},{"id":"d1432000-0000-4000-8000-000000000076","label":"C76","beforeHash":"60d1ad57c7aa345b1a8c302e3ea61263ae7c0dbfeeae8aca439fbd9ea3a21819","afterHash":"2a529b673106d880da534ec69891e20950578e7facafb3d14088aca5b89d9e68","patch":{"difficulty":"medium","statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQue resultado adicional seria coerente com respiração aeróbia no frasco A?","version":2}},{"id":"d1432000-0000-4000-8000-000000000077","label":"C77","beforeHash":"d4791e77d7b62af51cfccd0e58dcb883ee46ff63f1232fc035fbd8b2cdae59e7","afterHash":"e1decbc48abd51f26813023851fabfeac86302d98c589ddc2c7a9fe77205c560","patch":{"difficulty":"medium","statement":"Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.\n\nQue medida enfrenta a causa descrita, em vez de apenas aumentar oxigênio temporariamente?","version":2}},{"id":"d1432000-0000-4000-8000-000000000078","label":"C78","beforeHash":"b1df093ccc39d52303252637e9bbf9542e5f98ec9b267658253b43f7c050b7d5","afterHash":"fc5f90aa3cc3793bab547799bd5af23964fe1ce3fc2f9b9f0131145328e9c4b7","patch":{"difficulty":"medium","statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos.\n\nQual resultado pode produzir estabilidade em torno de 400 mesmo com reprodução contínua?","version":2}},{"id":"d1432000-0000-4000-8000-000000000079","label":"C79","beforeHash":"b9dfdac4f41f14b1628b710362aaf067faa847ed0e9105a507671a5d23e7e09a","afterHash":"905a7fbd58a5beded07ccbaae206bfce6d022f7c9318f94a85818a003a09757b","patch":{"difficulty":"medium","statement":"Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.\n\nSe duas placas deslizarem lateralmente uma em relação à outra, que comparação evita confundir esse limite com a dorsal?","version":2}},{"id":"d1432000-0000-4000-8000-000000000080","label":"C80","beforeHash":"a7248e0f68b1e910b1561217b1099f8ea0ef110c1dde44e32b4bf23ffaf71d41","afterHash":"eb998913c11a470bf1e47d4201a1586996fe83bb1aa87a80bd2861def0be4daa","patch":{"difficulty":"medium","statement":"Duas caixas idênticas, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nQue observação impediria concluir que B não recebeu calor durante o teste?","version":3}},{"id":"d1432000-0000-4000-8000-000000000081","label":"C81","beforeHash":"5aec26bb258da1fd244322b157ec4eb3982f86b3a0d34b90d51c1b057b3444b0","afterHash":"d405f4de6e114bbf3946305a5844284ccbcdf1d04d3ea6ee61a31c7ec762eb2d","patch":{"difficulty":"medium","statement":"Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve.\n\nPara testar a influência da densidade do líquido, qual procedimento controla melhor as demais características do objeto?","version":3}},{"id":"d1432000-0000-4000-8000-000000000082","label":"C82","beforeHash":"694904ff6e8b65c7023d6fd43754306e977c091ad2c6f2158fc7cd6a13518d9f","afterHash":"cfdc102e925d4dca30df1cbc01cf56b6c687a07dfba3a8e93e74456a7b25907b","patch":{"difficulty":"medium","statement":"Uma amostra de 20 g de areia, 30 g de sal e 150 g de água é filtrada sem perdas. O filtrado homogêneo é dividido ao meio. Uma metade é evaporada até secar, liberando sua água para o ambiente; a outra é destilada, recolhendo toda a sua água. A areia e os dois resíduos de sal são recolhidos secos.\n\nQual massa total de materiais é efetivamente recolhida ao final?","options":["125 g","95 g","110 g","180 g","200 g"],"explanation":"Recolhem-se 20 g de areia, 15 + 15 = 30 g de sal e 150/2 = 75 g de água: total de 125 g. Os outros 75 g de água foram liberados na evaporação aberta. A conservação da massa inclui essa água no ambiente; não significa recuperação integral.","version":2}},{"id":"d1432000-0000-4000-8000-000000000083","label":"C83","beforeHash":"750eacfbf4602e9627588cbb8cd0b76339aa8f21ea5ad5f44ff742fd9b40f1bf","afterHash":"26d3419c7d70ac8c112bc87967b128e36bb2394a23655eca3f6c1da437d03421","patch":{"difficulty":"medium","statement":"Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.\n\nQual interpretação respeita conservação de energia e eficiência?","explanation":"Eficiência descreve a fração aproveitada para a finalidade considerada. As perdas para a finalidade considerada não são desaparecimento de energia: há transferência para calor e outras formas.","version":2}},{"id":"d1432000-0000-4000-8000-000000000084","label":"C84","beforeHash":"c23434036072e49edb1f41c3f727b49a73122b69e2fa3dd384762c64dc471140","afterHash":"ebfe859a1e38f82237bd5a4454a90465d91ee26219ee6a7d4d0492f00f1193f8","patch":{"difficulty":"medium","statement":"Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.\n\nQual conclusão depende explicitamente da hipótese de fonte ideal adotada?","version":2}},{"id":"d1432000-0000-4000-8000-000000000085","label":"C85","beforeHash":"eeecb9280a48eae3d318a3ef8895d127f3709f038f1e1fac1d8fce185448c82a","afterHash":"6b4d51764387e66034c43397cc49b464b812b1281c3ad3308c0e419ac6dd708b","patch":{"difficulty":"medium","statement":"Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico.\n\nSe o recipiente inicialmente a 15 °C absorvesse calor, mantendo o restante comparável, o que se esperaria em relação aos 30 °C calculados?","version":3}},{"id":"d1432000-0000-4000-8000-000000000086","label":"C86","beforeHash":"9d7aa375f3696ac9de926662e5e3048ba2b6bb522ff671c4daf19b2bca541648","afterHash":"b3f65394e48fe55efc2aacaf4b1d9e5b095e128bc7bafbdde16b2bdce08251e3","patch":{"difficulty":"medium","statement":"Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nComo melhorar a confiabilidade da conclusão sobre intensidade luminosa?","version":3}},{"id":"d1432000-0000-4000-8000-000000000087","label":"C87","beforeHash":"0a462dcf57c8b3806dc1e4fcf37abb58e16eff12aa98cb3afa9a760f37c940e0","afterHash":"a59936466271509823e09fd1215d830e15e2ea021a8ea85d4ae8da49f2125fdf","patch":{"difficulty":"medium","statement":"Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final.\n\nQue afirmação distingue corretamente decomposição de fluxo energético?","version":3}},{"id":"d1432000-0000-4000-8000-000000000088","label":"C88","beforeHash":"1b268d21a70372981f014eee02a389f05f8f92ab863b7af5d93680e3f95ede06","afterHash":"6a8ca0127b350b08e6ebc5876cbc1d882ad92011c9ef7991496b50f97d7fb88a","patch":{"difficulty":"easy","statement":"Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação dos alelos, fecundações independentes e igual viabilidade dos genótipos.\n\nUm indivíduo aa cruza com outro AA. Que resultado se espera quanto ao genótipo dos descendentes?","version":2}},{"id":"d1432000-0000-4000-8000-000000000089","label":"C89","beforeHash":"2e9c5ef90503fdcf5c8fcc7bf9912d3ddd17dfcd695e69f1b16f55f71f15d8df","afterHash":"6bd7bbfe87616f28df6a34b941ed0c9dc6c1da7a961065e86e3d42a12e536a91","patch":{"difficulty":"medium","statement":"Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. Todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.\n\nQual comparação ajuda a avaliar o papel seletivo da exposição?","version":3}},{"id":"d1432000-0000-4000-8000-000000000090","label":"C90","beforeHash":"683adb7481096a890728bdd621ca1c74fbf3f46a238f733ce8dd12955cc025c6","afterHash":"baa9db2315c4a0128b1e52f69b67b003a577f9af6fd51e4365d67fda3ab26ab2","patch":{"statement":"Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra, pressões hidrostáticas inicialmente iguais e ausência de transporte ativo no período.\n\nQue alteração impediria usar diretamente as previsões anteriores?","version":2}},{"id":"d1432000-0000-4000-8000-000000000091","label":"C91","beforeHash":"74b4f78add8addf21fe9a882ffb60f65213a3663fabf0062358885df420ca726","afterHash":"c2a71116ebe2944b6082aa2cab4a7ce516394ac3221afcfcd24eab04b41cf141","patch":{"difficulty":"medium","statement":"Uma solução aquosa contém um soluto não volátil e estável durante o aquecimento. Pretende-se aumentar sua concentração sem acrescentar soluto.\n\nQual procedimento atende ao objetivo?","options":["Acrescentar água até dobrar o volume.","Evaporar parte da água, mantendo o soluto no recipiente.","Dividir a solução em frascos iguais e considerar cada porção mais concentrada.","Retirar uma porção homogênea e manter o restante sem alterações.","Transferir toda a solução para um recipiente de menor capacidade, sem alterar o volume."],"explanation":"Ao evaporar parte da água sem perder soluto, diminui-se o volume da solução e aumenta-se a razão massa/volume. Retirada homogênea, transferência ou divisão não mudam essa razão; acrescentar água a diminui.","version":2}},{"id":"d1432000-0000-4000-8000-000000000092","label":"C92","beforeHash":"d0f37119c5d57ce48d5934fdd9b1a6ac4b8433980b995eff399ae4b6b98c4249","afterHash":"93723ef59bb649e9a3092abe9f3f3b53c43e869fe643f2d81f2cf44ecfd5d672","patch":{"difficulty":"medium","statement":"Um frasco fechado contém 5 g de bicarbonato e 25 g de solução ácida. Ao misturá-los, forma-se gás e o recipiente permanece vedado. A balança continua marcando 30 g de conteúdo. Em outro ensaio igual, o recipiente é aberto e parte do gás escapa, deixando 28 g de conteúdo medido.\n\nComo medir a massa total dos produtos no ensaio aberto sem perder a parcela gasosa?","version":2}},{"id":"d1432000-0000-4000-8000-000000000093","label":"C93","beforeHash":"6e25b9cb96c490fa7a432dc68bf9d3e638c247eb330911aba2d0a867b8b5069a","afterHash":"bb754b661088a7b76afe3a2ce6c43bd507e6ac2f3de6f8c30011068abdee1c69","patch":{"difficulty":"medium","statement":"Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.\n\nQue limitação impede afirmar que a pressão é idêntica em todos os pontos de um apoio real?","version":2}},{"id":"d1432000-0000-4000-8000-000000000094","label":"C94","beforeHash":"b1415edbebcf1b1ae8e8184b4ff6dc20199e8a18e163166902d392f850d72eab","afterHash":"0d14afe8332e2d4175b5be979a23a4eb7da1f870992869eede57996ce05f3c51","patch":{"difficulty":"easy","statement":"Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ.\n\nSe a fonte passar a 10 Hz no meio I, mantendo velocidade de 20 m/s, qual será o comprimento de onda?","version":2}},{"id":"d1432000-0000-4000-8000-000000000095","label":"C95","beforeHash":"a471dd53bc1b840a6ef28c20da632cc2d58445eb91790c7d213c20e95f9fef76","afterHash":"c25a14310c207af09b7f7268795005b3f6e15e584b907a2cd4146c92f5a6e6e1","patch":{"difficulty":"medium","statement":"Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem.\n\nQual cuidado evita transformar o exemplo de horas de luz em uma regra para qualquer cidade?","version":3}},{"id":"d1432000-0000-4000-8000-000000000096","label":"C96","beforeHash":"4f61716820d45cecada8bcf54a431de8dea23cdc6c9be210e1ae82604e6eb063","afterHash":"aebdbd321c6f2e60f4b14ac526e9b6384468636149d1972944b4c666afbc0911","patch":{"difficulty":"medium","statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nSe A estivesse aberto e recebesse ar continuamente, que dificuldade surgiria?","version":2}},{"id":"d1432000-0000-4000-8000-000000000097","label":"C97","beforeHash":"a9ba0108d853cc4ab08e3a28d2f572d7d42dfaea9f2b39abc85784c44e7a6873","afterHash":"39ff7838112538ab0d4365ff4fba60ad3cbca8598350972644bbdaad91efe65a","patch":{"difficulty":"medium","statement":"Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.\n\nQual cuidado é necessário ao interpretar uma única medida diurna de oxigênio?","version":2}},{"id":"d1432000-0000-4000-8000-000000000098","label":"C98","beforeHash":"73990f0a97e412c1424f08716fb075662476fe1bc606d280c8abe6b15ab00122","afterHash":"15c62a0c96f02b64227f1449e68f50d81ec4d6d06557560e553942b9b8ff0ec5","patch":{"difficulty":"medium","statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos.\n\nQual informação adicional ajuda a investigar o mecanismo da desaceleração?","version":2}},{"id":"d1432000-0000-4000-8000-000000000099","label":"C99","beforeHash":"fd747448d334903c94bc83f2fe9e57813ebecd0f74b06a804dfe4c73b37d5c04","afterHash":"700aef3134d64de1de29f9d3949ff6c23f9c3cfd15a20753b05f5c479d721bdd","patch":{"difficulty":"medium","statement":"Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.\n\nUm relatório identifica subducção e registra terremotos anteriores na região. Qual conclusão pode ser sustentada por essas informações?","version":3}},{"id":"d1432000-0000-4000-8000-000000000100","label":"C100","beforeHash":"03a7df62d4cb22aee67b1ad16ee7b0e23996bf5c61f7899fbc8bd5a5ae497d5b","afterHash":"beef035914653ea3783cba5a27966e99f993853cab5a0eca7d8041a991582c41","patch":{"difficulty":"easy","statement":"Duas caixas idênticas, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nSe os dois conteúdos forem observados por tempo suficiente no mesmo ambiente, sem fontes ativas, o que se espera em termos de tendência térmica?","version":3}},{"id":"d1090000-0000-4000-8000-000000000007","label":"H01","beforeHash":"16ab3c9bce2bea942ee7a3012365169d4a7386ffab8741139fc5a33001fa416d","afterHash":"3ffeb4cacb7ae4ca32ee353d48dee6f9d308c144c1c97589d443e62125305e44","patch":{"difficulty":"easy","statement":"Em diferentes regiões, grupos humanos adotaram agricultura e criação de animais em épocas distintas. Há vestígios de armazenamento, assentamentos e coexistência dessas atividades com caça e coleta.\n\nQual interpretação evita transformar essas mudanças em uma evolução única e inevitável de todas as sociedades?","explanation":"O contexto apresenta diversidade de tempo e combinação de atividades. Agricultura pode favorecer permanência e especialização sem impor um mesmo caminho a todos os grupos.","version":3}},{"id":"d1090000-0000-4000-8000-000000000008","label":"H02","beforeHash":"d7c024d1b821a4b55f9d8e7fc07a6aabac10bb238a49a5aa85f905f5267885d7","afterHash":"85104e7847a71f4567fdf046948c6901fe7932d7d815c3bc9cb66b227b9e8b02","patch":{"difficulty":"medium","statement":"Na Atenas clássica, homens adultos reconhecidos como cidadãos participavam de instituições políticas. Mulheres, estrangeiros residentes e pessoas escravizadas não tinham esses direitos de participação.\n\nUm morador estrangeiro de Atenas pagava tributos, mas não participava da assembleia como cidadão. Qual interpretação distingue residência e cidadania?","version":4}},{"id":"d1392000-0000-4000-8000-000000000001","label":"H03","beforeHash":"d0d209f8032b81dfcf760998d1c832c2a29be1ba34ff28575e46312e64c0073d","afterHash":"b0c2dc9997210f819432f266a4502a246bf361a180bc8b7975f9de9d906b68a7","patch":{"difficulty":"medium","statement":"A expansão romana ampliou terras conquistadas e o uso de trabalho escravizado. A distribuição de terras e a participação política provocaram conflitos na República e na formação do poder imperial.\n\nQue relação explica por que expansão territorial podia coexistir com conflitos internos?","version":4}},{"id":"d1392000-0000-4000-8000-000000000002","label":"H04","beforeHash":"0d960c7fd89f4a23837e07d599b2b1b2055c3c3c8b01e660f42eb4a21fba14d5","afterHash":"3ff2be23375a9e997ba62ec25be7d8da2c61fd2663a19ec8c84890d571476d24","patch":{"difficulty":"medium","statement":"Em partes da Europa medieval, senhores exerciam poderes sobre terras e camponeses. Estes deviam trabalho ou parte da produção. Nobres também estabeleciam compromissos de fidelidade e serviço entre si.\n\nUm camponês entrega parte da colheita ao senhor; um nobre promete serviço militar a outro nobre em troca de um feudo. Como se distinguem as relações?","version":5}},{"id":"d1392000-0000-4000-8000-000000000003","label":"H05","beforeHash":"c3d8ae1a172681861ebcd7f187c799d04507758e18993af7a71a735c6c25bfe0","afterHash":"0537840bbc42438c9a73674db6f292b46a6d342a6616a8fb8584127a9033b411","patch":{"difficulty":"medium","statement":"Artistas e estudiosos do Renascimento retomaram referências clássicas e desenvolveram técnicas de representação e investigação. Instituições religiosas e governantes estavam entre seus patronos. A imprensa ampliou a circulação de textos.\n\nUm artista renascentista usa perspectiva e referências clássicas em uma obra encomendada por uma instituição religiosa. Que interpretação é mais adequada?","version":5}},{"id":"d1392000-0000-4000-8000-000000000004","label":"H06","beforeHash":"039ef60af84d61ba0995f06f192eec063577c1bd4495c7255b0a1d4a7a6d2403","afterHash":"bc39a18cf7712760bcbdd2b6638672d6da74386003104a867a71dec6f28a7c49","patch":{"difficulty":"medium","statement":"No século XVI, correntes reformadoras questionaram a autoridade e práticas da Igreja católica. Governantes tomaram posições nos conflitos. A Igreja católica reafirmou doutrinas e promoveu mudanças internas.\n\nQue relação entre religião e política é coerente com a síntese?","version":4}},{"id":"d1392000-0000-4000-8000-000000000005","label":"H07","beforeHash":"d6ef7039b48798c26124d449319fecd8c045e9896cb8cd2e31940ef484c91329","afterHash":"84617ff14e6804881b6a8482661a089819326f1e5347b9b5f2736c24de5c4908","patch":{"difficulty":"medium","statement":"As viagens marítimas europeias envolveram instrumentos de navegação, comércio, financiamento e ação de monarquias. Nas Américas, chegaram a territórios ocupados por diferentes povos.\n\nUm reino financia viagens, comerciantes buscam novas rotas e navegadores empregam instrumentos aperfeiçoados. Qual relação explica a expansão marítima?","version":5}},{"id":"d1392000-0000-4000-8000-000000000006","label":"H08","beforeHash":"bafc5d8a9d5d94a03a8a282f0a68e3fc35bf1f199e076e0c3644939c4c988de1","afterHash":"6fa67104be7ec1cc905123af4991c13b6b0db81575db128d475160d091a1cdee","patch":{"difficulty":"medium","statement":"Na América portuguesa, engenhos articulavam cultivo, processamento do açúcar, comércio atlântico e trabalho escravizado. Produtores de alimentos e outros bens abasteciam essas unidades e as populações locais.\n\nUm engenho exporta açúcar e compra alimentos de produtores locais. Que interpretação relaciona essas duas atividades?","version":5}},{"id":"d1392000-0000-4000-8000-000000000007","label":"H09","beforeHash":"27ec39bba78b94c617614d3eed4c96b967225c7fd946153278920af5641765de","afterHash":"548287512eaa5bf77e68872809db523c5e52fea224465a7fd414cf307813f478","patch":{"difficulty":"medium","statement":"A mineração na América portuguesa ampliou a circulação no interior. A Coroa tributava e fiscalizava a extração. As zonas mineradoras também mantinham relações com produtores de alimentos e comerciantes.\n\nQual relação integra mineração e reorganização do território?","version":4}},{"id":"d1392000-0000-4000-8000-000000000008","label":"H10","beforeHash":"8102f3f019c0956767d4f1db0acf46baa41b86ac7d211e7eceeb2a540d87ea37","afterHash":"52da80b0f8095208659a3463bfe86b13d6caa76ba1890e5c6289555b352c6daf","patch":{"difficulty":"medium","statement":"Pensadores iluministas discutiram razão, direitos e limites da autoridade. Declarações de direitos elaboradas em processos revolucionários conviveram com regras que restringiam a participação de grupos sociais.\n\nQual análise explica a coexistência entre discurso de direitos e exclusões?","version":4}},{"id":"d1392000-0000-4000-8000-000000000009","label":"H11","beforeHash":"8d2e4ca9a9144753f504f8ef1acd2ee82dc517febc725ff1729826e295f62168","afterHash":"a90f1dbd33bdafffebd1ac693709212724eb635a59fb17f4285a2a5dac16e227","patch":{"difficulty":"medium","statement":"A industrialização ampliou o uso de máquinas e reuniu trabalhadores em fábricas. Horários, jornadas e salários eram organizados sob direção dos proprietários e provocavam conflitos com os trabalhadores.\n\nQual relação explica o conflito social apesar do aumento da produção?","version":4}},{"id":"d1392000-0000-4000-8000-000000000010","label":"H12","beforeHash":"53ef3175802831371e2d8d2607f37e883102fcf66c1ce1acf35e28f99ffb646b","afterHash":"4f0a1314662f3d33a1e90bdc9deb9ac7db3d538a7579d17c79672f18c5fe06e4","patch":{"difficulty":"medium","statement":"A Revolução Francesa questionou privilégios do Antigo Regime. O processo teve diferentes fases e grupos políticos. Os ideais de liberdade e igualdade foram debatidos também em relação a mulheres e populações coloniais.\n\nQual leitura compara ideais revolucionários e sua aplicação sem confundi-los?","version":4}},{"id":"d1392000-0000-4000-8000-000000000011","label":"H13","beforeHash":"cdee47058f4adc8470b2e2f70a8084185b6fbd5552b68d9a99ac633819286e85","afterHash":"c9ff53ce3b920618dd14042ad142c115ceb0b37fda9d54171957582a6584c05e","patch":{"difficulty":"medium","statement":"Nas independências americanas, grupos disputaram a ruptura com autoridades metropolitanas e a organização do novo governo. Propriedade, trabalho e participação política variaram entre os processos.\n\nQual distinção é necessária entre independência política e transformação social?","version":4}},{"id":"d1392000-0000-4000-8000-000000000012","label":"H14","beforeHash":"b53467b67a3aa611269bf84298c80de81525ffb05119ccd5a301303bd74531dc","afterHash":"dd79914cac71534fbbc2988326c7e97c1f94c43f7919e2c8e89fcf096513566e","patch":{"difficulty":"medium","statement":"A corte portuguesa chegou ao Brasil em 1808 no contexto das guerras napoleônicas. O Rio de Janeiro passou a sediar instituições da monarquia. Em 1815 formou-se o Reino Unido de Portugal, Brasil e Algarves; em 1822 ocorreu a independência brasileira.\n\nA abertura dos portos em 1808 ampliou o comércio direto do Brasil com nações amigas. Que mudança a medida representa naquele contexto?","version":5}},{"id":"d1392000-0000-4000-8000-000000000013","label":"H15","beforeHash":"676de3536ee860c03d6a7542fb3a449507dc86fc275880ca567d94d376a8b534","afterHash":"8dae2ab6ba466aa51655067e56bd540d7ce118ad78fd36bcbfb37f5177fbb46d","patch":{"difficulty":"medium","statement":"O Brasil tornou-se independente em 1822 sob uma monarquia. A Constituição de 1824 organizou instituições imperiais e estabeleceu regras de participação. A escravidão e a concentração de propriedade persistiram.\n\nQual análise identifica simultaneamente ruptura e continuidade?","version":4}},{"id":"d1392000-0000-4000-8000-000000000014","label":"H16","beforeHash":"e5162d34b1f74668726db4c732328605c3add235ef9b5256f49b2bd27f805c0b","afterHash":"98ccc88dc74c617146c35317050c064d0b98f808fd550d3a595960a2138cfb2a","patch":{"difficulty":"medium","statement":"A escravidão foi abolida legalmente no Brasil em 1888, após resistências, mobilizações e disputas políticas. Trabalhadores emancipados continuaram disputando acesso a terra, trabalho, renda e direitos.\n\nApós 1888, trabalhadores juridicamente livres ainda enfrentavam restrições de acesso à terra e renda. Qual distinção ajuda a interpretar essa situação?","version":5}},{"id":"d1392000-0000-4000-8000-000000000015","label":"H17","beforeHash":"a79655851ab3701ae0e86946ddf6661b8f12a859b8814b8c78dcebc0a1f4c1ca","afterHash":"6dd2193b314c31b73ce8cee735fe88ebdf25b35953b7df268496d1ebfbf65567","patch":{"difficulty":"medium","statement":"A República brasileira foi proclamada em 1889. Na Primeira República, regras de acesso ao voto e redes de poder local limitavam a participação. Eleitores podiam sofrer pressões de autoridades e proprietários.\n\nQual comparação distingue forma de governo e efetividade da participação?","version":4}},{"id":"d1392000-0000-4000-8000-000000000016","label":"H18","beforeHash":"65cba52dcb2fc63db86a15ba99c99255790b5017b185eef5ccf74ba2349eea81","afterHash":"51600b53dd096f041f7f43f42199e67a9478cecaa1ca855f77ecde38a44dde16","patch":{"difficulty":"medium","statement":"Em 1914, o atentado contra o herdeiro do Império Austro-Húngaro ocorreu num contexto de alianças, nacionalismos e rivalidades imperialistas. A guerra envolveu mobilização industrial e social, trincheiras e impactos sobre civis.\n\nPor que distinguir o atentado de 1914 das rivalidades e alianças anteriores ao interpretar a Primeira Guerra?","version":5}},{"id":"d1392000-0000-4000-8000-000000000017","label":"H19","beforeHash":"38f54d43e12d348d7979a396e7ed657f5b95e9e348b388ebb62baacd200c4e37","afterHash":"b01949bb3663e13a67a3f4d44d8539d73a641ee7ebecd92439d262432f928871","patch":{"difficulty":"medium","statement":"Entre 1939 e 1945, a Segunda Guerra envolveu expansionismo e regimes autoritários. Propaganda, perseguições e políticas de extermínio integraram a atuação de regimes como o nazista.\n\nQual interpretação relaciona propaganda e poder sem tratá-la como fonte neutra?","version":4}},{"id":"d1392000-0000-4000-8000-000000000018","label":"H20","beforeHash":"666763b330bfcd69675a368cc5502ab95c99562ec081bb8f4eb42ab3f64c6fec","afterHash":"5c16f1c672b70383716409b066f5413f9f57fc282601e6c87ad6274b216779eb","patch":{"difficulty":"medium","statement":"Após a Segunda Guerra, Estados Unidos e União Soviética disputaram influência. Na América Latina, ditaduras restringiram direitos e usaram discursos de segurança. Grupos locais participaram de disputas e resistências.\n\nQual explicação evita reduzir todos os processos latino-americanos a decisões externas?","version":4}},{"id":"d1433000-0000-4000-8000-000000000021","label":"H21","beforeHash":"11ec8df2e0fdd36522aebedab1dbb1adda247fb1bc7bd6c5f1d2d33b536d11a9","afterHash":"d50d1d6512b812e11677117919d306cc7849d820026654f261903b30082a6f33","patch":{"difficulty":"medium","statement":"Em diferentes regiões, grupos humanos adotaram agricultura e criação de animais em épocas distintas. Há vestígios de armazenamento, assentamentos e coexistência dessas atividades com caça e coleta.\n\nQue relação entre produção e organização social é compatível com a síntese?","version":2}},{"id":"d1433000-0000-4000-8000-000000000022","label":"H22","beforeHash":"32c608ab6371cf8560037c5eb4d1839871a18ef25539ff5c2ceb399585f96750","afterHash":"9b97570afd6cfc9e800d1a218568c1f3d24451c89d3ce72eef28a42f32e0ef27","patch":{"difficulty":"medium","statement":"Na Atenas clássica, homens adultos reconhecidos como cidadãos participavam de instituições políticas. Mulheres, estrangeiros residentes e pessoas escravizadas não tinham esses direitos de participação.\n\nUm texto que define apenas os direitos dos cidadãos permite concluir o quê sobre toda a população?","version":2}},{"id":"d1433000-0000-4000-8000-000000000023","label":"H23","beforeHash":"5495a6902b8203d0d3033c770bc86b45fa6eace5da20eddb226ba60b9e2b1766","afterHash":"e09b0346bd08475c21fac9407c056b0c32ab0257b2e95e7439d3491752dbb7cd","patch":{"difficulty":"medium","statement":"A expansão romana ampliou terras conquistadas e o uso de trabalho escravizado. A distribuição de terras e a participação política provocaram conflitos na República e na formação do poder imperial.\n\nQue transformação política distingue a concentração imperial de uma simples mudança geográfica?","version":2}},{"id":"d1433000-0000-4000-8000-000000000024","label":"H24","beforeHash":"40096f00a14c7e1a31639494365f127be6d583557180059b1db7155b93aadde6","afterHash":"d6785a17d2f691c7ee2b2858458985920c50f1b1cf1912ea77292a631cf2390d","patch":{"difficulty":"medium","statement":"Em partes da Europa medieval, senhores exerciam poderes sobre terras e camponeses. Estes deviam trabalho ou parte da produção. Nobres também estabeleciam compromissos de fidelidade e serviço entre si.\n\nQue interpretação do trabalho e entrega de produção preserva a desigualdade descrita?","version":2}},{"id":"d1433000-0000-4000-8000-000000000025","label":"H25","beforeHash":"4aa0d035e2b0683a33d3c857143c489771c1f4e68d8e340de19ca7db5b80d193","afterHash":"bf2ba379699af2a912f7480888b1eda85c5a516c92f1f9a8f9a5c0e1169e22c2","patch":{"difficulty":"medium","statement":"Artistas e estudiosos do Renascimento retomaram referências clássicas e desenvolveram técnicas de representação e investigação. Instituições religiosas e governantes estavam entre seus patronos. A imprensa ampliou a circulação de textos.\n\nComo a imprensa podia favorecer debates sem garantir igualdade de acesso?","version":2}},{"id":"d1433000-0000-4000-8000-000000000026","label":"H26","beforeHash":"be2104073fb40f72f4920e7c6892686fb36e3c328d7ca7f8b1d37b43e2a6307b","afterHash":"51d04d003b6bfebac97278d6d76ac3139dc44f04cd5eda79720ff73af5c15d7a","patch":{"difficulty":"medium","statement":"No século XVI, correntes reformadoras questionaram a autoridade e práticas da Igreja católica. Governantes tomaram posições nos conflitos. A Igreja católica reafirmou doutrinas e promoveu mudanças internas.\n\nComo a circulação de escritos alterava as condições do debate?","version":2}},{"id":"d1433000-0000-4000-8000-000000000027","label":"H27","beforeHash":"9500619555dde530a2bf975ab8585a8e8ad01a530a83a54f58e8de509117f6b7","afterHash":"3f1292bd59f688777026b5a50a515b65d83900d56a8546d94d285abe7bc72247","patch":{"difficulty":"medium","statement":"As viagens marítimas europeias envolveram instrumentos de navegação, comércio, financiamento e ação de monarquias. Nas Américas, chegaram a territórios ocupados por diferentes povos.\n\nQual problema histórico existe em descrever os territórios americanos como vazios?","version":2}},{"id":"d1433000-0000-4000-8000-000000000028","label":"H28","beforeHash":"1ac1791099c755dc8fb0bcf1201d540710b82432a461e9d94817e9a527bf882b","afterHash":"0061bfd49dca7fa3851501c9fb5c569ad02bbaf9a62900161d796333e581c5ca","patch":{"difficulty":"medium","statement":"Na América portuguesa, engenhos articulavam cultivo, processamento do açúcar, comércio atlântico e trabalho escravizado. Produtores de alimentos e outros bens abasteciam essas unidades e as populações locais.\n\nQue continuidade econômica pode coexistir com o destaque do açúcar?","version":2}},{"id":"d1433000-0000-4000-8000-000000000029","label":"H29","beforeHash":"bfccc811611158e2ceaca92bfa2e760a22efbfc5350bd7489011e9b9ea005f2a","afterHash":"56b7c38ba3a0bb7fa4efc6ade912d1c91851d244d01c9751da620d1c04b6a5d4","patch":{"difficulty":"medium","statement":"A mineração na América portuguesa ampliou a circulação no interior. A Coroa tributava e fiscalizava a extração. As zonas mineradoras também mantinham relações com produtores de alimentos e comerciantes.\n\nPor que fiscalidade pode ser fonte de conflito, além de fonte de receita?","version":2}},{"id":"d1433000-0000-4000-8000-000000000030","label":"H30","beforeHash":"a3edaef7ad860aae5c9e0dbc9ed6a7b7c056f9c5685c93a828dbe21062ac7025","afterHash":"3cb5c65dff0bf97395888b436aee887401d54ce326d939978cdeb1eb24edaee6","patch":{"difficulty":"medium","statement":"Pensadores iluministas discutiram razão, direitos e limites da autoridade. Declarações de direitos elaboradas em processos revolucionários conviveram com regras que restringiam a participação de grupos sociais.\n\nQue crítica ao poder é compatível com a discussão iluminista sintetizada?","version":2}},{"id":"d1433000-0000-4000-8000-000000000031","label":"H31","beforeHash":"6239633d721179eb905d2bcd61cae2855e1a04b1841a09eb824cc91bab396d19","afterHash":"1415d4b6b1c159981f13092bb6529281b4f6109a06abc1c4aafdbb642e8d6696","patch":{"difficulty":"medium","statement":"A industrialização ampliou o uso de máquinas e reuniu trabalhadores em fábricas. Horários, jornadas e salários eram organizados sob direção dos proprietários e provocavam conflitos com os trabalhadores.\n\nUma fábrica exige presença em horários fixos e coordena tarefas sucessivas. Qual mudança isso evidencia em relação ao controle do tempo de trabalho?","version":2}},{"id":"d1433000-0000-4000-8000-000000000032","label":"H32","beforeHash":"c2492427c3da0f0a66a73fd73532c3229642d3d20102374ed95109a5fa6161b0","afterHash":"f7cd08afdd1310122252c692239142de60020dcd4df775b39360fc6c3ec4cc33","patch":{"difficulty":"medium","statement":"A Revolução Francesa questionou privilégios do Antigo Regime. O processo teve diferentes fases e grupos políticos. Os ideais de liberdade e igualdade foram debatidos também em relação a mulheres e populações coloniais.\n\nUma crítica a privilégios hereditários atinge qual característica do Antigo Regime?","version":2}},{"id":"d1433000-0000-4000-8000-000000000033","label":"H33","beforeHash":"ffa1f51cb39994fe605ade2c77908b0da34e815c50ac439f3844ce01e05b1d27","afterHash":"7035e13eb1dd9e271cc0d12bb79b47d685460eaebbc14e6c2ca68bb33f66c4e8","patch":{"difficulty":"medium","statement":"Nas independências americanas, grupos disputaram a ruptura com autoridades metropolitanas e a organização do novo governo. Propriedade, trabalho e participação política variaram entre os processos.\n\nPor que diferenças entre projetos de território e governo são relevantes?","version":2}},{"id":"d1433000-0000-4000-8000-000000000034","label":"H34","beforeHash":"b07b737e7895b371015e64fc7955c9919f04c48f6dfe52161f5fcc9e4e8444c0","afterHash":"5a1fc5e1d72a016ce98370793febac1db3fe3dcdf1c3bf79e7ad0239236b4ebe","patch":{"difficulty":"medium","statement":"A corte portuguesa chegou ao Brasil em 1808 no contexto das guerras napoleônicas. O Rio de Janeiro passou a sediar instituições da monarquia. Em 1815 formou-se o Reino Unido de Portugal, Brasil e Algarves; em 1822 ocorreu a independência brasileira.\n\nQual relação entre contexto externo e transformação interna é coerente?","version":2}},{"id":"d1433000-0000-4000-8000-000000000035","label":"H35","beforeHash":"f3f9fcdef076248c22b7b801c48cefaf29c55cff931f80b2ac45c6923c2df140","afterHash":"568461ddc6262f868113e79fcb8ceb543f4a4e7713c96b0dfc0984605078caf9","patch":{"difficulty":"medium","statement":"O Brasil tornou-se independente em 1822 sob uma monarquia. A Constituição de 1824 organizou instituições imperiais e estabeleceu regras de participação. A escravidão e a concentração de propriedade persistiram.\n\nQue investigação é necessária para avaliar participação política no início do Império?","version":2}},{"id":"d1433000-0000-4000-8000-000000000036","label":"H36","beforeHash":"6f8cd795a25caab000cca165c08f8cf1b60bbe6143f48388e5b6a6dfc4db55e6","afterHash":"220dd824909a85c585e667fe3aae2eafac5491b1fe8bb5264a35dd6301dda879","patch":{"difficulty":"medium","statement":"A escravidão foi abolida legalmente no Brasil em 1888, após resistências, mobilizações e disputas políticas. Trabalhadores emancipados continuaram disputando acesso a terra, trabalho, renda e direitos.\n\nQual interpretação evita reduzir a abolição a uma concessão isolada de uma autoridade?","version":2}},{"id":"d1433000-0000-4000-8000-000000000037","label":"H37","beforeHash":"6e30c668835d1015243c6b726b2ee680cec923460673fb1da91be03aa51652ca","afterHash":"dd790616be38df5c99403c5165ed3b998d718dcb00ab85ecf961dcd3a097a75d","patch":{"difficulty":"medium","statement":"A República brasileira foi proclamada em 1889. Na Primeira República, regras de acesso ao voto e redes de poder local limitavam a participação. Eleitores podiam sofrer pressões de autoridades e proprietários.\n\nComo controle de recursos pode se relacionar a coerção eleitoral?","version":2}},{"id":"d1433000-0000-4000-8000-000000000038","label":"H38","beforeHash":"5c56d93664e3984aff9e2cca4f998289c83aa6931ff40261a3405c31aa5123d2","afterHash":"acd6720beaf53d9de34992d115e9a7b7f8de02accd773ef5ba64c7f371eca977","patch":{"difficulty":"medium","statement":"Em 1914, o atentado contra o herdeiro do Império Austro-Húngaro ocorreu num contexto de alianças, nacionalismos e rivalidades imperialistas. A guerra envolveu mobilização industrial e social, trincheiras e impactos sobre civis.\n\nQual relação entre alianças e ampliação da guerra é coerente?","version":2}},{"id":"d1433000-0000-4000-8000-000000000039","label":"H39","beforeHash":"8cc3a9f9a4ca552d13b392604a391c737d02372a23d30fb2538dd86fe88174a4","afterHash":"20397dd1b359025f87b4b1e17cb59290b0fcdf6c70651e9251c8e644530ea45b","patch":{"difficulty":"medium","statement":"Entre 1939 e 1945, a Segunda Guerra envolveu expansionismo e regimes autoritários. Propaganda, perseguições e políticas de extermínio integraram a atuação de regimes como o nazista.\n\nQue procedimento é adequado ao estudar uma mensagem racista produzida por um regime perseguidor?","options":["Considerar o texto prova de que todos os contemporâneos concordavam.","Eliminar outras fontes por divergirem da mensagem oficial.","Reproduzir a classificação como verdade sem contextualização.","Analisar sua função de desumanização e legitimação da violência, sem adotar sua classificação como descrição válida dos grupos.","Usar suas categorias como explicação científica da desigualdade entre pessoas."],"version":2}},{"id":"d1433000-0000-4000-8000-000000000040","label":"H40","beforeHash":"815d473f2232f03d66ec3ade8eb2075028aca211583051ed89ecc91838a060fb","afterHash":"f46f61b19efc22c55709110e29a083bb18b52c4a721afce6b69b3f604d5e114b","patch":{"difficulty":"medium","statement":"Após a Segunda Guerra, Estados Unidos e União Soviética disputaram influência. Na América Latina, ditaduras restringiram direitos e usaram discursos de segurança. Grupos locais participaram de disputas e resistências.\n\nQue tensão existe entre discurso de segurança e restrição de direitos?","version":2}},{"id":"d1433000-0000-4000-8000-000000000041","label":"H41","beforeHash":"6a3c33b8edbfc9abb928408981259e6dfd64ee24b15248ee126b0818a10768b2","afterHash":"a063ba6e21aa2c260495f3e964a68b91d46bea8273ca7aacdd73bb0bf741c735","patch":{"difficulty":"medium","statement":"Em diferentes regiões, grupos humanos adotaram agricultura e criação de animais em épocas distintas. Há vestígios de armazenamento, assentamentos e coexistência dessas atividades com caça e coleta.\n\nUm recipiente com restos de grãos, encontrado isoladamente, permite qual conclusão mais prudente?","version":2}},{"id":"d1433000-0000-4000-8000-000000000042","label":"H42","beforeHash":"9e9f88f1f2fa3b47eaacf227a4d98c5360b39c110a9c5a6db806bd99b27bd0b3","afterHash":"95f0b726376b5268e753276bfc8fb67879a40b0d5da37f32a4c271c60d4f46ba","patch":{"difficulty":"medium","statement":"Na Atenas clássica, homens adultos reconhecidos como cidadãos participavam de instituições políticas. Mulheres, estrangeiros residentes e pessoas escravizadas não tinham esses direitos de participação.\n\nQue diferença entre participação e representação é relevante nesse exemplo?","version":2}},{"id":"d1433000-0000-4000-8000-000000000043","label":"H43","beforeHash":"b51e150ac9b1758b0d846128c30f77df21ae1bc3b39d0c4d1f9da45017ec5382","afterHash":"04ceb7f7f4a5ac5200b91ef504a4cd08f99baf6b8329e06549c5f0fd350131b9","patch":{"difficulty":"medium","statement":"A expansão romana ampliou terras conquistadas e o uso de trabalho escravizado. A distribuição de terras e a participação política provocaram conflitos na República e na formação do poder imperial.\n\nUm relato de vitória militar basta para comprovar melhoria de vida de todos os habitantes?","version":2}},{"id":"d1433000-0000-4000-8000-000000000044","label":"H44","beforeHash":"ca1d237f83b5771a7415de96485b4e7f10e6824d6e17634de9f81fcd4503e2ed","afterHash":"9b7cf0437405691ed93501a2da05a10ba0b23d74e8302dcf22aff3009a7e9a2e","patch":{"difficulty":"medium","statement":"Em partes da Europa medieval, senhores exerciam poderes sobre terras e camponeses. Estes deviam trabalho ou parte da produção. Nobres também estabeleciam compromissos de fidelidade e serviço entre si.\n\nPor que não se deve tratar a síntese como descrição idêntica de toda a Europa medieval?","version":2}},{"id":"d1433000-0000-4000-8000-000000000045","label":"H45","beforeHash":"60db533ad136b4f12e58fcd26e09bf64638788e80eaf880ced5068d81cfa074a","afterHash":"bc2f796aa70a69da1c18b80f4c56e4dd9f16a3e00ab4c4618bbe100fcd277774","patch":{"difficulty":"medium","statement":"Artistas e estudiosos do Renascimento retomaram referências clássicas e desenvolveram técnicas de representação e investigação. Instituições religiosas e governantes estavam entre seus patronos. A imprensa ampliou a circulação de textos.\n\nUma pintura que emprega perspectiva permite investigar qual dimensão de mudança?","version":2}},{"id":"d1433000-0000-4000-8000-000000000046","label":"H46","beforeHash":"6b79710d29b80563bdac8337d7daeaec7a6fc65325f3ee142c10ddff4b7b9c08","afterHash":"d55b2e487bd96d92f3becc6e15b4d10f9d36a90d3972699219d2952e9785fea8","patch":{"difficulty":"medium","statement":"No século XVI, correntes reformadoras questionaram a autoridade e práticas da Igreja católica. Governantes tomaram posições nos conflitos. A Igreja católica reafirmou doutrinas e promoveu mudanças internas.\n\nQual comparação evita tratar a reação católica como mera imobilidade?","version":2}},{"id":"d1433000-0000-4000-8000-000000000047","label":"H47","beforeHash":"341d11c30efadb45c8dabe4662a44be2192b0382eedce7ba6e36782927c016cb","afterHash":"4830076bfd2745d2e0e566aa1f5c5f0849b830ef7730c2a5af63b8a49f3c53d7","patch":{"difficulty":"medium","statement":"As viagens marítimas europeias envolveram instrumentos de navegação, comércio, financiamento e ação de monarquias. Nas Américas, chegaram a territórios ocupados por diferentes povos.\n\nUm mapa europeu de rotas descreve automaticamente a experiência de todos os povos envolvidos?","version":2}},{"id":"d1433000-0000-4000-8000-000000000048","label":"H48","beforeHash":"65c2eb4f77a43a7da25abad8b804361c518647fa6b9d95c53e6ea64c431dbc04","afterHash":"b7eb820b7527e87146c4fc84cb626082749b8b76099876799785d9e74d81d364","patch":{"difficulty":"medium","statement":"Na América portuguesa, engenhos articulavam cultivo, processamento do açúcar, comércio atlântico e trabalho escravizado. Produtores de alimentos e outros bens abasteciam essas unidades e as populações locais.\n\nPor que um registro de produção de um proprietário não descreve integralmente a experiência dos trabalhadores?","version":2}},{"id":"d1433000-0000-4000-8000-000000000049","label":"H49","beforeHash":"11a6e51a00f2a02e55268d6a05edddcea4f95061d08f800c451245b936bd3d21","afterHash":"7382859064ba945a8d7c43f361b11d32742aea1c9dd2fcfab96376c4419889f4","patch":{"difficulty":"medium","statement":"A mineração na América portuguesa ampliou a circulação no interior. A Coroa tributava e fiscalizava a extração. As zonas mineradoras também mantinham relações com produtores de alimentos e comerciantes.\n\nQue informação complementa um registro de metal exportado para estudar efeitos locais?","version":2}},{"id":"d1433000-0000-4000-8000-000000000050","label":"H50","beforeHash":"1eab85bb5b4de04b9c75beb3256c891e824a6c90e1361c44642f8e8e8e65cb42","afterHash":"921642d1abeb437adb84c4e1d631da9fe096e921605fef0a57c912d1a5f00631","patch":{"difficulty":"medium","statement":"Pensadores iluministas discutiram razão, direitos e limites da autoridade. Declarações de direitos elaboradas em processos revolucionários conviveram com regras que restringiam a participação de grupos sociais.\n\nComo investigar quem foi efetivamente incluído por uma declaração de direitos?","version":2}},{"id":"d1433000-0000-4000-8000-000000000051","label":"H51","beforeHash":"b1663e9c8df66e8158b9e94bedbecd596e713a10a08a4fd1b150e15ef4401245","afterHash":"5151155658fb59629173e033ab789359af111bad67da104e0d771165331d7085","patch":{"difficulty":"medium","statement":"A industrialização ampliou o uso de máquinas e reuniu trabalhadores em fábricas. Horários, jornadas e salários eram organizados sob direção dos proprietários e provocavam conflitos com os trabalhadores.\n\nUm registro de produção elevada basta para comprovar melhoria das condições dos trabalhadores?","version":2}},{"id":"d1433000-0000-4000-8000-000000000052","label":"H52","beforeHash":"39d115495cd915245a917967e4c732222e34345fa18f7ed3111fb3116c2d8cd8","afterHash":"4a840177cf58245852dbfa2fe194ed2f8ead9e47c2246a6e1582b88069cc2268","patch":{"difficulty":"medium","statement":"A Revolução Francesa questionou privilégios do Antigo Regime. O processo teve diferentes fases e grupos políticos. Os ideais de liberdade e igualdade foram debatidos também em relação a mulheres e populações coloniais.\n\nComo avaliar se a igualdade proclamada alcançou mulheres em determinado momento?","version":2}},{"id":"d1433000-0000-4000-8000-000000000053","label":"H53","beforeHash":"9f9e0763ab15b31ef46786321a2ecbfb5780105e2725e7baa0ecdd80bfa2e94a","afterHash":"effd6d3b0ba6b5815375c3ede5a791a7012fe732eafbe543c05dcd825784dea7","patch":{"difficulty":"medium","statement":"Nas independências americanas, grupos disputaram a ruptura com autoridades metropolitanas e a organização do novo governo. Propriedade, trabalho e participação política variaram entre os processos.\n\nUm discurso de uma elite independentista pode ser usado de que modo?","version":2}},{"id":"d1433000-0000-4000-8000-000000000054","label":"H54","beforeHash":"6787c9ecae6fb60143e1fc10bebec0112aa2c567ae26f1ad075d4552b656f30a","afterHash":"ad4d73593173fcd7a0ea7e7a4c57cb788211b5e30c684947754a8fb91ed21641","patch":{"difficulty":"medium","statement":"A corte portuguesa chegou ao Brasil em 1808 no contexto das guerras napoleônicas. O Rio de Janeiro passou a sediar instituições da monarquia. Em 1815 formou-se o Reino Unido de Portugal, Brasil e Algarves; em 1822 ocorreu a independência brasileira.\n\nPor que a instalação da corte alterava a posição do Rio de Janeiro?","version":2}},{"id":"d1433000-0000-4000-8000-000000000055","label":"H55","beforeHash":"547c6c5e2ce0459ed6f312783168dd3a2120815f3dc4b7777fc48a33853ea3a7","afterHash":"7bbfd05a4a84c56c309f140d9df76c4ddd2a43272bf59110289ea0059eea8229","patch":{"difficulty":"medium","statement":"O Brasil tornou-se independente em 1822 sob uma monarquia. A Constituição de 1824 organizou instituições imperiais e estabeleceu regras de participação. A escravidão e a concentração de propriedade persistiram.\n\nQual informação contraria a ideia de consenso nacional completo no processo?","version":2}},{"id":"d1433000-0000-4000-8000-000000000056","label":"H56","beforeHash":"cbf962f9108a80bf7b18ea9ae3cb4738473675cae74d41fc520510a18c060da5","afterHash":"1dde2fd1693eb17ce223cdfa7d55afca4c4fbb1c81ff01eef9f413ebe7845451","patch":{"difficulty":"medium","statement":"A escravidão foi abolida legalmente no Brasil em 1888, após resistências, mobilizações e disputas políticas. Trabalhadores emancipados continuaram disputando acesso a terra, trabalho, renda e direitos.\n\nQue fonte ajuda a estudar experiência social após a abolição além da lei?","version":2}},{"id":"d1433000-0000-4000-8000-000000000057","label":"H57","beforeHash":"d7d035babba797f34045430aacad12c538d37c8c3e5905cf571256864a01aa99","afterHash":"3912b69a2279fa564d2e0b4afd99b642096b850ff1afda2674312c1f760449bc","patch":{"difficulty":"medium","statement":"A República brasileira foi proclamada em 1889. Na Primeira República, regras de acesso ao voto e redes de poder local limitavam a participação. Eleitores podiam sofrer pressões de autoridades e proprietários.\n\nUm registro oficial de votos prova sozinho a liberdade de todos os votantes?","version":2}},{"id":"d1433000-0000-4000-8000-000000000058","label":"H58","beforeHash":"de5287538be911879b88d1b81c69af6059dfde063f35c669e565e494b67a0c61","afterHash":"a8016d86a9e5db73f9b0ed63d61c86e756f7695be03da20f268c6429502dba2d","patch":{"difficulty":"medium","statement":"Em 1914, o atentado contra o herdeiro do Império Austro-Húngaro ocorreu num contexto de alianças, nacionalismos e rivalidades imperialistas. A guerra envolveu mobilização industrial e social, trincheiras e impactos sobre civis.\n\nUm relato de soldado de trincheira permite qual uso histórico?","version":2}},{"id":"d1433000-0000-4000-8000-000000000059","label":"H59","beforeHash":"59fc69297ce5e97474506887190f496b4a6a4efadfe583c4cb13286d9cee26fd","afterHash":"8692cd8fba38d93a2147800ba86e2b2aa175bf0ad6a59a0b6118603aaf44e1da","patch":{"difficulty":"medium","statement":"Entre 1939 e 1945, a Segunda Guerra envolveu expansionismo e regimes autoritários. Propaganda, perseguições e políticas de extermínio integraram a atuação de regimes como o nazista.\n\nPor que testemunhos, documentos administrativos e vestígios devem ser confrontados?","version":2}},{"id":"d1433000-0000-4000-8000-000000000060","label":"H60","beforeHash":"9f14651ad184a03c9cd0953300199069f7125b819711940a76c19edf992f117d","afterHash":"8d991f46d0384b160b183ba6641abb948dbf036844b6783acbc78b32d3e7385b","patch":{"difficulty":"medium","statement":"Após a Segunda Guerra, Estados Unidos e União Soviética disputaram influência. Na América Latina, ditaduras restringiram direitos e usaram discursos de segurança. Grupos locais participaram de disputas e resistências.\n\nComo examinar a afirmação de consenso em um período de censura?","version":2}},{"id":"d1433000-0000-4000-8000-000000000061","label":"H61","beforeHash":"886b5842b862d93990c92719b56832bd5e6f60a316d724de25ca59f87b294357","afterHash":"cf4e1744d0a4fe5c01e1aee83f81ccebb66f8fdb12dc43f23c5c321128e4c911","patch":{"difficulty":"medium","statement":"Em diferentes regiões, grupos humanos adotaram agricultura e criação de animais em épocas distintas. Há vestígios de armazenamento, assentamentos e coexistência dessas atividades com caça e coleta.\n\nQual pesquisa ajuda a diferenciar produção local de circulação de alimentos por troca?","version":2}},{"id":"d1433000-0000-4000-8000-000000000062","label":"H62","beforeHash":"883b5895fbbd02466975ffbca79c4251a309f00a0d52317cf42f64c24202eb50","afterHash":"730487b53b3f59df9d6634b1d97abd19cc56e3af40906996921dd749e4f5fa36","patch":{"difficulty":"medium","statement":"Na Atenas clássica, homens adultos reconhecidos como cidadãos participavam de instituições políticas. Mulheres, estrangeiros residentes e pessoas escravizadas não tinham esses direitos de participação.\n\nQual afirmação caracteriza um anacronismo ao interpretar Atenas?","version":2}},{"id":"d1433000-0000-4000-8000-000000000063","label":"H63","beforeHash":"2ec08f57b0f8b641f8e69861abc6e534d3af4b9dcdad38af13a389e98c1f4c53","afterHash":"7af0d8a9aeda354986fd09b30cc1607e14953c7e825329fb5120229ef11109e4","patch":{"difficulty":"medium","statement":"A expansão romana ampliou terras conquistadas e o uso de trabalho escravizado. A distribuição de terras e a participação política provocaram conflitos na República e na formação do poder imperial.\n\nQual mudança pode relacionar concentração fundiária a tensões entre grupos?","version":2}},{"id":"d1433000-0000-4000-8000-000000000064","label":"H64","beforeHash":"5a53c007ed42a2b7327f140a3202f3ddd3b8cdeec3929afdeb50c75856bdd9c1","afterHash":"ea6aaa2e19f4e0d0a749ed318cc418f8abfba405d5ab19dc2f33cf497afebf51","patch":{"difficulty":"medium","statement":"Em partes da Europa medieval, senhores exerciam poderes sobre terras e camponeses. Estes deviam trabalho ou parte da produção. Nobres também estabeleciam compromissos de fidelidade e serviço entre si.\n\nQual informação seria útil ao examinar uma obrigação de entrega de parte da colheita?","version":2}},{"id":"d1433000-0000-4000-8000-000000000065","label":"H65","beforeHash":"5559aca2421f01833bfefee74d30d56bf661049ad6dcad329f24f7bbdadc2ff7","afterHash":"6f25ca3f64d49ddf7a5786f3d2a6dd6dfaa17f1c25b24077769ae83bab875c99","patch":{"difficulty":"medium","statement":"Artistas e estudiosos do Renascimento retomaram referências clássicas e desenvolveram técnicas de representação e investigação. Instituições religiosas e governantes estavam entre seus patronos. A imprensa ampliou a circulação de textos.\n\nQue pesquisa testa melhor a afirmação de que todos tiveram o mesmo acesso aos novos textos?","version":2}},{"id":"d1433000-0000-4000-8000-000000000066","label":"H66","beforeHash":"b8343abce965239b38d9fa3c2807aab3331d59548afdab1952cf44497b8de4e0","afterHash":"16626c34928daa15dcc3e171fa4d1b06c30a9dd951a17ba0c35ecc7f4a068a59","patch":{"difficulty":"medium","statement":"No século XVI, correntes reformadoras questionaram a autoridade e práticas da Igreja católica. Governantes tomaram posições nos conflitos. A Igreja católica reafirmou doutrinas e promoveu mudanças internas.\n\nAo analisar um escrito de controvérsia religiosa, que cuidado é necessário?","version":2}},{"id":"d1433000-0000-4000-8000-000000000067","label":"H67","beforeHash":"711bff32f1caaa7fe41840b3c6b2ee5a48af474847eb48b10322b1ec2b157a80","afterHash":"8559b0b8f2a1daaf586b4fe2305ef7ed4db20e6766411f4ba5fe07f50f646932","patch":{"difficulty":"medium","statement":"As viagens marítimas europeias envolveram instrumentos de navegação, comércio, financiamento e ação de monarquias. Nas Américas, chegaram a territórios ocupados por diferentes povos.\n\nQual relação pode coexistir no processo de contato sem contradição lógica?","version":2}},{"id":"d1433000-0000-4000-8000-000000000068","label":"H68","beforeHash":"2aa9af3f064409114ca5bff32d10c461962493521b1f2dc62dd4caba8716721b","afterHash":"b1b09e547a8167c40c62042784ab67f56e2403dda10742370c16e3a09b30e9f9","patch":{"difficulty":"medium","statement":"Na América portuguesa, engenhos articulavam cultivo, processamento do açúcar, comércio atlântico e trabalho escravizado. Produtores de alimentos e outros bens abasteciam essas unidades e as populações locais.\n\nQual diferença distingue escravidão de uma relação assalariada livre?","version":2}},{"id":"d1433000-0000-4000-8000-000000000069","label":"H69","beforeHash":"24da06e47b4def8812cad212800abf56472d53c6c7a5be19b5f1bcdd56b6cd38","afterHash":"0c216a40d00b76b8f5091184d9ee077ae93c10cc4d1ff9f56ef147680de4548e","patch":{"difficulty":"medium","statement":"A mineração na América portuguesa ampliou a circulação no interior. A Coroa tributava e fiscalizava a extração. As zonas mineradoras também mantinham relações com produtores de alimentos e comerciantes.\n\nQual interpretação evita reduzir conflitos fiscais a uma unidade de interesses de todos os moradores?","version":2}},{"id":"d1433000-0000-4000-8000-000000000070","label":"H70","beforeHash":"1e0ca6393d02d63c4b79ae403c639aaaaa0584aff9b33ad7581679da8abdc611","afterHash":"2ff00b761ea3c084cc90eb77bf07b2c840d063d6c985ddacc21c27072a4143bf","patch":{"difficulty":"medium","statement":"Pensadores iluministas discutiram razão, direitos e limites da autoridade. Declarações de direitos elaboradas em processos revolucionários conviveram com regras que restringiam a participação de grupos sociais.\n\nQual relação evita tratar ideias como causa suficiente de uma revolução?","version":2}},{"id":"d1433000-0000-4000-8000-000000000071","label":"H71","beforeHash":"25c3afa4d02c8f6da9d4be8872eb791b32a8e6092fa953f7f00161aca81ff1df","afterHash":"3779da154ac06436150dfec12a066de95d42f2570231f7107e8e8c32a22e856a","patch":{"difficulty":"medium","statement":"A industrialização ampliou o uso de máquinas e reuniu trabalhadores em fábricas. Horários, jornadas e salários eram organizados sob direção dos proprietários e provocavam conflitos com os trabalhadores.\n\nQual ação coletiva se relaciona à disputa sobre condições de trabalho?","version":2}},{"id":"d1433000-0000-4000-8000-000000000072","label":"H72","beforeHash":"2f94a50c3dff99e7f3f54258f131b8eceb716b3142e5abf731d4b9f59978df9c","afterHash":"ed85f56580812cb4d589bc0d263b4079b09c97c107ff9352f1de91a270eea0cf","patch":{"difficulty":"medium","statement":"A Revolução Francesa questionou privilégios do Antigo Regime. O processo teve diferentes fases e grupos políticos. Os ideais de liberdade e igualdade foram debatidos também em relação a mulheres e populações coloniais.\n\nQual informação enfraquece a leitura de que a Revolução foi um bloco de ideias e práticas imutáveis?","version":2}},{"id":"d1433000-0000-4000-8000-000000000073","label":"H73","beforeHash":"ddf3f1d2445ed445dedd345939e7701b440a518ec21f5ce3537584ae89a0f7aa","afterHash":"53e2ec5ef856d0bfd8a3fe7e686e5c4a9b00f4ef2329c015253323622576b48c","patch":{"difficulty":"medium","statement":"Nas independências americanas, grupos disputaram a ruptura com autoridades metropolitanas e a organização do novo governo. Propriedade, trabalho e participação política variaram entre os processos.\n\nQue continuidade pode ser investigada após a ruptura política?","version":2}},{"id":"d1433000-0000-4000-8000-000000000074","label":"H74","beforeHash":"807b153d3bd06c53273271e4822a70422c8342b74bbafedb01bb7f3687c7728c","afterHash":"b3779c42556cf7fe7e94c686a13f10f2557775e8a2ef14ad3be445ef805dbd9d","patch":{"difficulty":"medium","statement":"A corte portuguesa chegou ao Brasil em 1808 no contexto das guerras napoleônicas. O Rio de Janeiro passou a sediar instituições da monarquia. Em 1815 formou-se o Reino Unido de Portugal, Brasil e Algarves; em 1822 ocorreu a independência brasileira.\n\nQual interpretação da elevação de 1815 é inadequada?","version":2}},{"id":"d1433000-0000-4000-8000-000000000075","label":"H75","beforeHash":"6194e6aa192fbe3ae476c8c98b69dd13ba5a833f5088c11d70d1985861dd9744","afterHash":"0903d2663f2354ea275fbd1748fbcc0ee13c5cc3e9a029d17baafce273efab85","patch":{"difficulty":"medium","statement":"O Brasil tornou-se independente em 1822 sob uma monarquia. A Constituição de 1824 organizou instituições imperiais e estabeleceu regras de participação. A escravidão e a concentração de propriedade persistiram.\n\nUm relato que menciona apenas líderes políticos é suficiente para negar participação popular?","version":2}},{"id":"d1433000-0000-4000-8000-000000000076","label":"H76","beforeHash":"307de68bf2c64cb2eca50e8f885e726cc7be60d46731f466e94a3b13b488ef49","afterHash":"663a490107af03b03541408d9733671f1c494300923706d079a377567499ee75","patch":{"difficulty":"medium","statement":"A escravidão foi abolida legalmente no Brasil em 1888, após resistências, mobilizações e disputas políticas. Trabalhadores emancipados continuaram disputando acesso a terra, trabalho, renda e direitos.\n\nQual relação entre continuidade e mudança é coerente?","version":2}},{"id":"d1433000-0000-4000-8000-000000000077","label":"H77","beforeHash":"3d414717930643de234703e394d752dc4c0441e5812b9742047c1bb046251735","afterHash":"5002b13d63ad0fcb32cb4ded0ca1e8975ce3bff736073778bc7083e4a951c277","patch":{"difficulty":"medium","statement":"A República brasileira foi proclamada em 1889. Na Primeira República, regras de acesso ao voto e redes de poder local limitavam a participação. Eleitores podiam sofrer pressões de autoridades e proprietários.\n\nQue mudança pode coexistir com práticas locais persistentes?","version":2}},{"id":"d1433000-0000-4000-8000-000000000078","label":"H78","beforeHash":"de1d3f08dfb16938b04396a7d4833a79805943bc26dc08ade000c36d79448fcb","afterHash":"d7312f365342f92f7e74d94ec582e0a0f891d09025ba6e01a1c56142966f9afa","patch":{"difficulty":"medium","statement":"Em 1914, o atentado contra o herdeiro do Império Austro-Húngaro ocorreu num contexto de alianças, nacionalismos e rivalidades imperialistas. A guerra envolveu mobilização industrial e social, trincheiras e impactos sobre civis.\n\nQue análise relaciona guerra e sociedade além do combate militar?","version":2}},{"id":"d1433000-0000-4000-8000-000000000079","label":"H79","beforeHash":"7641bae48a55937497ccfe5bffb92f9e3cd646bb8c997b03114b93279466e9df","afterHash":"5ddbf5d7d8041554c2c3135e5dfc6ffac68c22d34fc349a92ab51a00050eb835","patch":{"difficulty":"medium","statement":"Entre 1939 e 1945, a Segunda Guerra envolveu expansionismo e regimes autoritários. Propaganda, perseguições e políticas de extermínio integraram a atuação de regimes como o nazista.\n\nQual distinção entre regime autoritário e democracia é relevante ao contexto?","version":2}},{"id":"d1433000-0000-4000-8000-000000000080","label":"H80","beforeHash":"db1c180816a9bb7c1f49c96b786a6048c98c9ad290d0f0791ac75488dec7564e","afterHash":"6cdf7719b73c069a40cf591d4289ad01652d5f6bb420b6a50956337636a7c9ae","patch":{"difficulty":"medium","statement":"Após a Segunda Guerra, Estados Unidos e União Soviética disputaram influência. Na América Latina, ditaduras restringiram direitos e usaram discursos de segurança. Grupos locais participaram de disputas e resistências.\n\nQual relação entre democracia e redemocratização é historicamente prudente?","version":2}},{"id":"d1433000-0000-4000-8000-000000000081","label":"H81","beforeHash":"8a68738dc009bbdfaac29a49fe0c1c919be6e2971f4b64fd5a7fbaa62e1c86d4","afterHash":"a16bba63711f1774a20bd859f7375169436f450de7493067788872ef5cfe119e","patch":{"difficulty":"medium","statement":"Em dois sítios arqueológicos, um grupo manteve a caça junto ao cultivo; outro reuniu grandes estoques de cereais. Que comparação é sustentada por esses vestígios?","options":["As atividades e formas de organização podiam combinar-se de modo diferente entre grupos.","A presença de caça impede a existência de cultivo.","O grupo com estoques abandonou obrigatoriamente toda caça.","Os dois grupos adotaram agricultura no mesmo ano.","O armazenamento comprova distribuição igualitária dos alimentos."],"explanation":"Os vestígios permitem comparar práticas, não impor uma sequência única ou deduzir igualdade social. Combinações distintas de produção e armazenamento são compatíveis com trajetórias diversas.","version":2}},{"id":"d1433000-0000-4000-8000-000000000082","label":"H82","beforeHash":"e2c7680db47c3e141cbb939c12759d923ab238ed5b78a5aba149230d4a7d2ab6","afterHash":"a71645e56029701884c6319080988e66027aa2381967d3782411478a0580c7ee","patch":{"difficulty":"medium","statement":"Um debate escolar distingue democracia direta e sufrágio universal. Qual característica da Atenas clássica pertence a cada dimensão?","options":["Participação direta de cidadãos descreve a forma de decisão; exclusão de moradores descreve os limites da cidadania.","Excluir estrangeiros transforma qualquer assembleia em monarquia hereditária.","Sufrágio universal significa que apenas homens reconhecidos como cidadãos participam.","Participação direta significa que todos os moradores tinham os mesmos direitos.","Ser cidadão dependia exclusivamente de morar na cidade."],"explanation":"Forma de participação e abrangência da cidadania são dimensões diferentes. Uma assembleia pode ter participação direta de um corpo de cidadãos limitado, sem equivaler ao sufrágio universal.","version":2}},{"id":"d1433000-0000-4000-8000-000000000083","label":"H83","beforeHash":"c00629263c3591d94446b0d2b033d5929d8d5bb6dad0678bf9f6c61ac288f763","afterHash":"4a10409ddceb028bdff6ec90bbb6422d8cdf8cfc2f4e00bfa500e4ecf4301ed5","patch":{"difficulty":"medium","statement":"Um mapa mostra a expansão de Roma e uma tabela registra concentração de terras. Qual análise articula as duas informações?","options":["A expansão territorial podia ampliar recursos, enquanto sua apropriação desigual alimentava disputas internas.","A concentração de terras demonstra que Roma deixou de expandir seu território.","A conquista territorial garantia que todas as famílias recebiam a mesma área de terra.","O aumento do território eliminava diferenças de posição social.","Um mapa territorial mede diretamente a renda de cada grupo."],"explanation":"O mapa descreve extensão territorial; a tabela descreve propriedade. Relacionar as fontes permite examinar quem se beneficiava da expansão, sem converter crescimento de território em igualdade de distribuição.","version":2}},{"id":"d1433000-0000-4000-8000-000000000084","label":"H84","beforeHash":"5699cae3359073304ef4b399b86fe2f28fc95058a583fee250cbdb8129dfa926","afterHash":"f60f9ffbc6efd2e1b52e54f7b553242b16042a9ff2905fec55c6ed614e5d65de","patch":{"difficulty":"medium","statement":"Um camponês presta dias de trabalho em terras do senhor e entrega parte de sua colheita. Qual elemento diferencia essa relação de uma aliança de vassalagem entre nobres?","options":["A relação dispensa controle senhorial sobre a terra.","Entregar colheita significa receber salário fixo do senhor.","O camponês exerce um cargo militar equivalente ao de qualquer nobre.","Vassalagem e obrigações camponesas têm participantes e funções idênticos.","As obrigações ligam o uso da terra ao trabalho e à produção camponesa, em vez de um pacto de fidelidade entre membros da elite."],"explanation":"A identificação considera posições sociais e obrigações. Prestação de trabalho e entrega de produtos pertencem às relações senhoriais camponesas; vassalagem corresponde a compromissos entre membros da elite.","version":2}},{"id":"d1433000-0000-4000-8000-000000000085","label":"H85","beforeHash":"753b2b245417d75ad3ab7afff257364e0d78c6c4b08894453885dbaf7deffe7b","afterHash":"bac42fb8f8d3761a7a2dcc5ac05b3332e4e578f8bf2e22ecfee03abace2db090","patch":{"difficulty":"medium","statement":"Uma oficina produz livros impressos mais rapidamente que um copista. Ainda assim, muitos habitantes não leem esses livros. Qual fator social ajuda a explicar essa situação?","options":["A maior velocidade de produção torna desnecessário saber ler.","Ter mais exemplares garante o mesmo acesso em todos os grupos.","Alfabetização, preço e controles de circulação condicionam o acesso, mesmo com maior produção.","A imprensa reproduz apenas um exemplar de cada texto.","Imprimir exemplares reduz automaticamente a população alfabetizada."],"explanation":"Capacidade técnica de reproduzir livros e acesso efetivo são dimensões distintas. Custo, alfabetização e mecanismos de controle podem limitar a circulação e a leitura sem negar o aumento da produção.","version":2}},{"id":"d1433000-0000-4000-8000-000000000086","label":"H86","beforeHash":"b44bab2467ec5efabc05c9e2b4b7e2e0361d30f3657c787e70bc8f0ac1bab15b","afterHash":"809b7629a2ae0d692ad0a1c7b4434795e77be9aced7bde52280ccb2f9ed44c27","patch":{"difficulty":"medium","statement":"Um governante apoia uma corrente reformadora e assume controle de instituições religiosas em seu território. Qual interpretação evita reduzir o episódio a uma causa única?","options":["O episódio prova que a circulação de escritos não teve papel nas reformas.","Controlar instituições comprova que todas as correntes tinham a mesma doutrina.","O apoio político demonstra ausência de qualquer divergência religiosa.","Debates doutrinários e interesses de poder podiam articular-se no apoio à reforma.","A atuação de governantes exclui a participação de outros grupos."],"explanation":"Motivações religiosas têm conteúdo próprio, mas podem se relacionar a poder, instituições e alianças. O apoio de um governante não basta para negar a diversidade dos agentes e das doutrinas.","version":2}},{"id":"d1433000-0000-4000-8000-000000000087","label":"H87","beforeHash":"36c71e680cd6bde7fa93c6a763689a4a7cc4f6a93b5d998ced19c289444290a9","afterHash":"0a1f0d29a4437151c94ee82eb237697726365c517199c1d641efa6ae97755f61","patch":{"difficulty":"medium","statement":"Um relato europeu apresenta a chegada às Américas como ocupação de terras vazias. Qual evidência contraria essa descrição?","options":["A existência de novas rotas comerciais europeias depois da chegada.","O uso de instrumentos náuticos nas embarcações europeias.","Vestígios de aldeias, cultivos, redes de troca e organizações locais anteriores à chegada.","O financiamento da viagem por uma monarquia.","A quantidade de navios registrada na partida."],"explanation":"Ocupações e atividades anteriores demonstram que os territórios já eram habitados e organizados. Dados sobre a viagem europeia, por si só, não informam a presença ou ausência das populações locais.","version":2}},{"id":"d1433000-0000-4000-8000-000000000088","label":"H88","beforeHash":"2a55bd5ce1a8b026e776d15492d4bf36f9c81971412527dbc934ad105f549006","afterHash":"4051b59da2182d3ea7e8c2ba87b3a5437902665e22f148909ea8a5b822953e93","patch":{"difficulty":"medium","statement":"Um engenho vende açúcar ao exterior e registra compra de farinha de produtores da região. Qual conclusão respeita as duas informações?","options":["Exportação e abastecimento interno integravam circuitos econômicos articulados.","Vender ao exterior exclui a existência de qualquer mercado local.","A compra regional demonstra que todo o trabalho do engenho era livre.","A farinha comprada era necessariamente enviada ao exterior junto com o açúcar.","A compra de farinha impede classificar o açúcar como produto exportado."],"explanation":"As duas operações podem coexistir: uma gera venda externa; a outra abastece a unidade e seus trabalhadores. Destino do produto e relação de trabalho não podem ser deduzidos de uma compra de alimentos.","version":2}},{"id":"d1433000-0000-4000-8000-000000000089","label":"H89","beforeHash":"39b7971c088e5a2e4b8e267df003e427ea6fd2a93c1f383c8fbfb1e13b5dfb49","afterHash":"dc677a50a59328916f9c26b37c69c64ffa48eddb59fd4c8967ade9b44264daa6","patch":{"difficulty":"easy","statement":"Em um exercício sobre a mineração colonial, o quinto corresponde a 20% do ouro tributável. Um registro anota 450 g de ouro sujeitos a essa cobrança. Quanto corresponde ao quinto?","options":["90 g","360 g","225 g","112,5 g","45 g"],"explanation":"O quinto é 1/5, ou 20%. A parcela tributária é 450 × 0,20 = 90 g; os 360 g restantes não são o imposto. O exercício usa uma regra informada, sem supor que toda prática fiscal colonial se resumia a ela.","version":2}},{"id":"d1433000-0000-4000-8000-000000000090","label":"H90","beforeHash":"3bec0c8910faf9647a9fd23f75523e7174aab9200372e31702e3393757bc1c0e","afterHash":"cf09282a1907baa5ad374e5e48cd90261a38a2e2232a53baf38427701ae1e6d1","patch":{"difficulty":"medium","statement":"Uma declaração proclama igualdade, mas uma regra de cidadania limita a participação política por renda. Qual comparação é necessária?","options":["Tomar a igualdade declarada como comprovação de participação igual em qualquer instituição.","Distinguir o princípio declarado dos critérios efetivos de inclusão nas instituições.","Considerar a renda uma medida direta da liberdade de pensamento.","Supor que toda restrição de participação era aplicada de forma idêntica em todos os países.","Concluir que o princípio nunca influenciou disputas por direitos."],"explanation":"O princípio orienta debates, mas regras e práticas definem sua abrangência efetiva. Uma restrição permite investigar exclusões sem tratar o ideal como automaticamente realizado ou completamente irrelevante.","version":2}},{"id":"d1433000-0000-4000-8000-000000000091","label":"H91","beforeHash":"b33bce0172ed9fa003ba7da10c3f9932625a1c5a567c2373df981995eb67acfc","afterHash":"4532c57fdb88467d560e65473cd207d7ba0bcacce26d704e536c7d88a97ab4c2","patch":{"difficulty":"medium","statement":"Uma fábrica dobra sua produção, mantendo jornadas extensas e salários baixos. Que dado seria necessário para avaliar se os trabalhadores se beneficiaram do aumento?","options":["Mudanças de remuneração, jornada, segurança e distribuição dos ganhos.","A quantidade de produtos tomada como prova de redução da jornada.","A produção total usada como prova suficiente de melhoria individual.","O número de máquinas usado como medida direta de salário.","A data da inauguração usada como indicador de segurança."],"explanation":"Produção mede resultado do processo produtivo. Benefícios dos trabalhadores exigem indicadores de renda e condições de trabalho; eles não são automaticamente proporcionais à quantidade de produtos fabricados.","version":2}},{"id":"d1433000-0000-4000-8000-000000000092","label":"H92","beforeHash":"a97ff2d88a9bde50dd114335868866b978bd82d41b36063850e2256ed4f94b7b","afterHash":"be01266c457e72ee2839653c327fef0bc9b4966731755797ac213cb2870b9e9d","patch":{"difficulty":"medium","statement":"Na Revolução Francesa, uma reivindicação pede participação política para mulheres com base no ideal de igualdade. Que relação essa reivindicação evidencia?","options":["Os princípios revolucionários podiam ser mobilizados para contestar exclusões presentes em sua aplicação.","A reivindicação comprova que as mulheres já tinham os mesmos direitos políticos em todas as fases.","Questionar exclusões significava rejeitar necessariamente todo princípio de igualdade.","A participação das mulheres era determinada apenas pela alfabetização, sem regras institucionais.","A igualdade declarada impedia debates sobre quem poderia participar."],"explanation":"Um princípio pode servir de argumento para ampliar direitos além da aplicação inicial. A reivindicação revela uma disputa sobre sua abrangência, sem comprovar que a inclusão já estivesse realizada.","version":2}},{"id":"d1433000-0000-4000-8000-000000000093","label":"H93","beforeHash":"476464fe1bfcec6178352264a9ca0dff5a41c9a75eb5aa5b19f0776d5eecf299","afterHash":"811f15a49dfb4ee02313ba51c91f1058f51d5c0cc146d1c6d755fdf9ca29b5b3","patch":{"difficulty":"medium","statement":"Duas antigas colônias tornam-se independentes: uma mantém monarquia, outra adota república. Em ambas persistem concentração de terras e coerção do trabalho. Qual comparação é correta?","options":["A independência substituiu automaticamente toda propriedade privada por propriedade coletiva.","As duas adotaram instituições e relações de trabalho idênticas.","A existência de república garante desaparecimento de concentração de terras.","A manutenção de monarquia significa que não houve independência política.","A ruptura metropolitana ocorreu em formas de governo diferentes e não eliminou as continuidades sociais indicadas."],"explanation":"Independência, forma de governo e relações sociais são dimensões distintas. É possível haver ruptura de soberania e continuidade social, com instituições diferentes em cada caso.","version":2}},{"id":"d1433000-0000-4000-8000-000000000094","label":"H94","beforeHash":"25cfdc1f7ab94d036ac0a2a1fe6ab0f60eaef1bef8c156efafb73cd4b2677432","afterHash":"10894edbf89021c064854beda930c5ba70ae54f5cd9277747dcf0387b0823bdb","patch":{"difficulty":"easy","statement":"Ordene os acontecimentos: instalação da corte no Brasil, formação do Reino Unido e independência brasileira. Qual sequência está correta?","options":["1808 → 1815 → 1822.","1822 → 1815 → 1808.","1815 → 1822 → 1808.","1808 → 1822 → 1815.","1815 → 1808 → 1822."],"explanation":"A corte chegou em 1808. A elevação do Brasil a reino integrante do Reino Unido ocorreu em 1815. A independência foi proclamada em 1822. São etapas distintas, não nomes diferentes de um único acontecimento.","version":2}},{"id":"d1433000-0000-4000-8000-000000000095","label":"H95","beforeHash":"361d7a35ae3d2046bb32075aba0964773fe0436c5738e3f94a8e12efeb6b5edc","afterHash":"b0780e56c73568bf3d021a31df3df7a9c4c5ac310d32316d5e5c1b71757aa730","patch":{"difficulty":"medium","statement":"Na Constituição de 1824, o Poder Moderador era atribuído ao imperador. Qual efeito institucional esse dispositivo ajuda a compreender?","options":["O dispositivo implantava uma república com eleição direta do chefe de Estado.","Todos os habitantes exerciam o Poder Moderador por sufrágio universal.","O imperador exercia função apenas cerimonial, sem atribuições políticas.","O monarca dispunha de prerrogativas de intervenção na organização dos demais poderes.","O Poder Moderador era eleito anualmente pelos trabalhadores escravizados."],"explanation":"O Poder Moderador dava ao imperador instrumentos de intervenção no funcionamento das instituições. Reconhecer essas prerrogativas distingue a monarquia imperial de um chefe de Estado apenas simbólico ou de uma república.","version":2}},{"id":"d1433000-0000-4000-8000-000000000096","label":"H96","beforeHash":"6774458b71f21bc0b2018950cfb4c0463ead4a9af0a653fb535df1c6851b3906","afterHash":"3f9a0683915dd763d9b8a1f7ed038b2169b454b36bd4300c6ed917f48a2e24ea","patch":{"difficulty":"medium","statement":"A Lei Áurea aboliu a escravidão em 1888. Qual informação não pode ser deduzida apenas desse marco legal?","options":["Que a abolição ocorreu antes da proclamação da República.","Que todas as pessoas emancipadas receberam terras e passaram a ter a mesma renda.","Que a condição jurídica de escravidão foi extinta pela lei.","Que o marco legal é posterior à independência de 1822.","Que 1888 pertence ao período imperial brasileiro."],"explanation":"A lei extingue a escravidão como condição jurídica. Ela não comprova distribuição universal de terras ou igualdade de renda. As outras informações decorrem do marco legal e da cronologia indicada da história brasileira.","version":2}},{"id":"d1433000-0000-4000-8000-000000000097","label":"H97","beforeHash":"e36e1c1ae7477c34094ebcae957c47d43f1408d8f4321510e6413f892fd1b6b3","afterHash":"67a1512359ef3ffb3bc78c5b5c9258e987a213f148e84e641d05a1d3abb972cc","patch":{"difficulty":"medium","statement":"Um eleitor depende de um proprietário para obter trabalho e recebe ameaça de perdê-lo caso vote contra o candidato indicado. Que relação o episódio ilustra?","options":["Escolha livre garantida pela existência de uma urna.","Ausência de influência dos poderes locais sobre o voto.","Distribuição igual de poder entre todos os eleitores.","Uso de dependência econômica como instrumento de coerção política.","Participação política definida exclusivamente pela preferência individual."],"explanation":"A ameaça liga recursos materiais à escolha eleitoral. Um registro formal de voto não comprova liberdade quando existem coerção, dependência e pressões sobre o eleitor.","version":2}},{"id":"d1433000-0000-4000-8000-000000000098","label":"H98","beforeHash":"d24ea66e9c526dbb16e7a5196cf9912b8708f2e334f538494d47ca239b4e43c7","afterHash":"38cc534e3accf52a9da73342e6493850356e8a6816e4484ed5e57f9b02a63b02","patch":{"difficulty":"medium","statement":"Uma tabela de 1914 registra sucessivas mobilizações de países ligados por alianças. Qual pergunta ajuda a explicar a ampliação da crise para além do atentado?","options":["Por que as datas diferentes de mobilização demonstrariam ausência de relações entre os países?","Como atribuir toda a expansão da guerra exclusivamente à resposta de um único governo?","Como compromissos, rivalidades e decisões de cada governo contribuíram para envolver outros países?","Como descrever cada mobilização como uma decisão econômica isolada das alianças militares?","Por que o atentado criou naquele momento as rivalidades que não existiam antes?"],"explanation":"A sequência de mobilizações pode ser relacionada a alianças e decisões dentro de um contexto anterior de rivalidades. O estopim não cria automaticamente todas as condições nem determina motivações idênticas.","version":2}},{"id":"d1433000-0000-4000-8000-000000000099","label":"H99","beforeHash":"31f2a63a2eb05edf47f4d6450bce1f96f70f091766d5987a8a1eb1facd30d45f","afterHash":"a1e6c8f06bf409cc7244a3ab67cb221b920a4969a09bcf3012753dac2daba95f","patch":{"difficulty":"medium","statement":"Uma propaganda nazista desumaniza um grupo perseguido. Qual uso histórico desse material é adequado?","options":["Concluir que a finalidade persuasiva elimina todo valor do material como evidência histórica.","Usar o material para negar políticas de perseguição registradas em outras fontes.","Adotar a classificação racista da propaganda como descrição factual do grupo.","Investigar a estratégia de legitimação da perseguição, confrontando-a com outras evidências.","Tomar a propaganda como comprovação de apoio espontâneo de toda a população."],"explanation":"A propaganda é evidência da construção de mensagens e da legitimação do poder, não uma classificação válida dos perseguidos. Sua função deve ser analisada sem reproduzir a ideologia como descrição neutra.","version":2}},{"id":"d1433000-0000-4000-8000-000000000100","label":"H100","beforeHash":"bb6daac3e6b85ffd26ef3732b3e6f2b5be2df3cc54da3af1d4b604b0e143afb6","afterHash":"985c2398a3103a24e544ef302bcaf9ceade79da0888cf396b2203f31a0b0f241","patch":{"difficulty":"medium","statement":"Durante uma ditadura, um jornal é censurado e manifestações são proibidas. Um relatório oficial afirma que não houve oposição. Qual conclusão é mais prudente?","options":["A ausência de manifestações públicas pode refletir repressão, sendo necessário investigar outras fontes.","A ausência de registros comprova concordância de toda a população.","A censura garante que todas as opiniões foram publicadas.","Um relatório oficial dispensa análise das condições em que foi produzido.","A proibição das manifestações demonstra que a oposição não existia antes dela."],"explanation":"Silêncio público sob repressão não equivale a consenso. Censura e proibições afetam o registro das opiniões; correspondência, testemunhos e outros materiais podem revelar posições impedidas de circular.","version":2}},{"id":"d1090000-0000-4000-8000-000000000009","label":"G01","beforeHash":"9426b027b84d051e718612af3ade67eff25bf0e128efbaae4ffa41f85bda9b0e","afterHash":"59c36df10aacef6bb645cb30bb9deaf08f6c4e2679e0b1dda096a6cb373111b6","patch":{"difficulty":"easy","statement":"Em um mapa de escala 1:50.000, uma trilha mede 8 cm. Despreze distorções da projeção.\n\nQual é o comprimento real da trilha?","options":["8 km","0,4 km","2 km","40 km","4 km"],"explanation":"O comprimento real é 8 × 50.000 = 400.000 cm. Como 100.000 cm correspondem a 1 km, a trilha tem 4 km.","version":3}},{"id":"d1090000-0000-4000-8000-000000000010","label":"G02","beforeHash":"d328347e3fb3084974079cbae92ed4b02e09242602cdae5df6100d7f795e9404","afterHash":"e5843de4c3a22efc8baa97d93b74da8684e07aed06873e9fb1b59be934f7a864","patch":{"difficulty":"easy","statement":"A região A tem 600.000 habitantes em 3.000 km²; B tem 400.000 habitantes em 1.000 km². Em A, 80% das pessoas vivem em apenas 20% da área. As áreas não se sobrepõem e os dados referem-se ao mesmo ano.\n\nQual comparação entre densidades médias está correta?","version":3}},{"id":"d1394000-0000-4000-8000-000000000001","label":"G03","beforeHash":"357731f2b4000d5fa9da751f683fdd4fadb710409d690fc06c54f46746334df2","afterHash":"b14af71124fbab0392ff8840486fc4a7eeafdcbb307cc3a52ea7776de90f63d1","patch":{"difficulty":"medium","statement":"Um município tinha 80.000 habitantes, dos quais 60.000 urbanos. Dez anos depois passou a 100.000 habitantes, sendo 85.000 urbanos. Considere os mesmos limites territoriais e critérios de classificação nos dois momentos.\n\nQual mudança da taxa de urbanização ocorreu?","version":4}},{"id":"d1394000-0000-4000-8000-000000000002","label":"G04","beforeHash":"90bd6bbc06bc81d0051cdfd89514230b3b06359576fada99387c86228f0ac2f6","afterHash":"71ba52ef3fd731aed8b109cebf90c3ed59fef47a9457a69c64da920f7bf99846","patch":{"difficulty":"medium","statement":"Uma região começa o ano com 50.000 habitantes. Registra 900 nascimentos, 400 mortes, 1.500 imigrantes e 2.000 emigrantes. As categorias não se sobrepõem, não há mudança de limites e os valores correspondem ao mesmo ano.\n\nQual população é esperada ao fim do ano?","version":4}},{"id":"d1394000-0000-4000-8000-000000000003","label":"G05","beforeHash":"c93b0342b56a44db95d39aa978ee405b3596546b9c20eec1ba2e98b7f1dcf89b","afterHash":"1dd5431fbb5cedf1a2d75c8b1e45c8fcabe3794b2452954e96f1fc2093e31c08","patch":{"difficulty":"medium","statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. a razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQual é a razão de dependência demográfica aproximada?","version":4}},{"id":"d1394000-0000-4000-8000-000000000004","label":"G06","beforeHash":"1f9a899248750358a773be1a1f13dc594a9779207b7cd65ba90cd2c1864a0e5f","afterHash":"14ac83439f70305c49a430fe74bb2beef43c3ee569b374dd6b257c6efc7031cc","patch":{"difficulty":"medium","statement":"A propriedade A colheu 12.000 toneladas em 3.000 hectares; B colheu 10.000 toneladas em 2.000 hectares. No ano seguinte, A pretende aumentar a produção para 15.000 toneladas mantendo a área. Os dados não incluem custo, renda dos trabalhadores ou impactos ambientais.\n\nQual comparação entre produção total e produtividade é correta?","version":4}},{"id":"d1394000-0000-4000-8000-000000000005","label":"G07","beforeHash":"55a75f919075f07d5e6313c95b02b81f01c3f0398aa367edd3b3fc1611261da9","afterHash":"f906c32ec3f04d461be92c61256dc2015bd83c4258bde7754d27338016a452f7","patch":{"difficulty":"easy","statement":"Em uma bacia de 1.000 km², a cobertura florestal era 600 km² e passou a 450 km². Áreas impermeabilizadas passaram de 100 para 200 km²; os demais usos ocupam a área restante. Os períodos têm os mesmos limites. O relatório não identifica automaticamente as causas de cada mudança.\n\nQual redução relativa da cobertura florestal ocorreu?","version":4}},{"id":"d1394000-0000-4000-8000-000000000006","label":"G08","beforeHash":"53052d7c1fcded5d7b9ec3bba738302e9cc9b626003b21d6241c0bc13873a974","afterHash":"0f38694db67b61e0658b1a709cedb38d1635b562e2e076fdd67ca3c639f0e69a","patch":{"difficulty":"easy","statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. No período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQue potências médias resultam no período?","version":4}},{"id":"d1394000-0000-4000-8000-000000000007","label":"G09","beforeHash":"78b925bc1f8ef5599393cf43d6398e5599757a8bdc696863847e97f3e6386fd1","afterHash":"eba56c1fe701770c286e27f24ef28f11f10dbac2c80056a090e4bacf402ae528","patch":{"difficulty":"medium","statement":"O país A emite 120 milhões de toneladas de um gás em um ano e tem 60 milhões de habitantes. B emite 80 milhões de toneladas e tem 20 milhões de habitantes. Considere a mesma metodologia de inventário e não inclua emissões históricas acumuladas neste cálculo.\n\nQual comparação distingue total anual e emissão por habitante?","version":4}},{"id":"d1394000-0000-4000-8000-000000000008","label":"G10","beforeHash":"3b33fa3b6c0068fe3ac41eac3db527c1a6ecf1dc9a0ef0770d2f95e84692b800","afterHash":"e0a5c9ce7c8deaf2757b3c53b7d1c41b2a5606c621dbd6013d58f7ae5d3f5d56","patch":{"difficulty":"medium","statement":"Uma carga de 400 toneladas deve percorrer 300 km. A rodovia cobra R$ 0,30 por tonelada-quilômetro. A ferrovia cobra R$ 0,15 por tonelada-quilômetro e exige R$ 12.000 de transferência nos terminais. Ignore custos e prazos não informados; a transferência é cobrada uma vez para toda a carga.\n\nQual comparação de custo total corresponde aos dados?","version":4}},{"id":"d1394000-0000-4000-8000-000000000009","label":"G11","beforeHash":"056ea0d9c98731b9876c66d2b18ac07931249cccd1218c03f60c350e45ac3001","afterHash":"9783762b18860f13d99eabb6285be0ceaf72cf11ccd7e68553374ca1d09083cb","patch":{"difficulty":"easy","statement":"Uma região exporta 50 milhões de reais em alimentos e 30 milhões em equipamentos. Importa 20 milhões em alimentos e 45 milhões em equipamentos. Os dados usam a mesma moeda e período e não incluem serviços, investimentos ou movimentos financeiros.\n\nQual saldo comercial total corresponde ao período?","version":4}},{"id":"d1394000-0000-4000-8000-000000000010","label":"G12","beforeHash":"a2615d51b4060999e066700b6648ad64bcb7006a92a543b7ceb5f6dd914ae54d","afterHash":"0a020db6471fade555e1b3bd6f7aa391071fea9bd16bff94faafafd8b147e7fa","patch":{"difficulty":"medium","statement":"Cinco domicílios de um setor têm rendas mensais de R$ 1.000, R$ 1.200, R$ 1.500, R$ 2.000 e R$ 9.300. Outro setor tem cinco domicílios com R$ 3.000 cada. A comparação não inclui diferenças de tamanho familiar ou custo de vida.\n\nQual comparação das médias é correta?","version":4}},{"id":"d1394000-0000-4000-8000-000000000011","label":"G13","beforeHash":"5e1dda8c27fe008a1b4638d6c4fdc20e1cc9393342b47a42d51016988b198de3","afterHash":"d040fc1fe3292d3cbccf20d7a16714cf26d585afe4032bbd62e907e5d00e1b6c","patch":{"difficulty":"easy","statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQual comparação dos saldos está correta?","version":4}},{"id":"d1394000-0000-4000-8000-000000000012","label":"G14","beforeHash":"5be8a4479e8dfc309cdbbbd6e374df79ed7c55d19b019d91a34c0131c74159dc","afterHash":"a1be9e6fcf4d7805a76696dd5b9dd3a4434cd3005ce11f1dcf6cddb19af335ad","patch":{"difficulty":"easy","statement":"Uma bacia recebe, no período estudado, 100 unidades de água por precipitação e 10 por entrada externa. Perde 40 por evapotranspiração e 50 por saída fluvial. No modelo, a diferença altera o armazenamento. Uma captação adicional retiraria 30 unidades, sem outras mudanças.\n\nQue alteração do armazenamento ocorre antes da captação adicional?","version":4}},{"id":"d1394000-0000-4000-8000-000000000013","label":"G15","beforeHash":"990672d8e36239a9c68140d33652031fd99053b5ea9774f9695684fb50d34d86","afterHash":"3fee0d8df3f0603f1b4dd23044fa959a5483fa32e642d6bccc58fa5286989247","patch":{"difficulty":"medium","statement":"Duas encostas têm a mesma declividade e recebem chuva semelhante. A mantém vegetação e solo permeável; B foi desmatada e tem trechos compactados. Há moradias na parte baixa de ambas. O relatório considera escoamento, erosão e exposição de pessoas, sem afirmar que um único fator determina todos os eventos.\n\nQue tendência diferencia B de A sob as condições informadas?","version":4}},{"id":"d1394000-0000-4000-8000-000000000014","label":"G16","beforeHash":"fd704a3a3c2b1971d4390613cbc55931cfc1d7c5655f7090081cded12988b164","afterHash":"4cd8e661f04e2e9710b97ae0aa637b6714917e2aafe57196d56d3f1cdcb997ff","patch":{"difficulty":"medium","statement":"A cidade A usa UTC−3 e B, UTC+1. Um voo sai de A às 22h de segunda-feira e dura oito horas. Não há mudança sazonal de fuso.\n\nEm que horário local chega a B?","explanation":"A partida equivale a 1h UTC de terça-feira. Oito horas depois são 9h UTC, ou 10h no fuso UTC+1. A diferença de fuso se soma à duração ao converter os horários locais.","version":4}},{"id":"d1394000-0000-4000-8000-000000000015","label":"G17","beforeHash":"e285389e5e2201f3dac099aaa48d41e0662ea12ffb0c41492cefa2646376405f","afterHash":"0472396e83a27982dc8c5f6e24b86e84705dab8c08dc342886ed381f14ad7b2e","patch":{"difficulty":"easy","statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQual comparação das coordenadas é correta?","version":4}},{"id":"d1394000-0000-4000-8000-000000000016","label":"G18","beforeHash":"5241775be89aa4ce0cc7a8a9fedf3013ce647da59c3d6d4834bf0a52f947ee99","afterHash":"7def7930196bbbcdef12532333ff918f78d669bec36cc88f73bcafa7ba136c29","patch":{"difficulty":"easy","statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nQual taxa de desocupação resulta da definição fornecida?","version":4}},{"id":"d1394000-0000-4000-8000-000000000017","label":"G19","beforeHash":"a9a9db85f9d905d6e5928e8e9e4170c5aec462b050c7b5c4877790036b73f880","afterHash":"a1cbef3bc5c19982060b6ad6b349b4e09e735fea4693f80dd08d57d6b80487e1","patch":{"difficulty":"medium","statement":"Em uma cidade, 600 viagens usam uma linha rápida com duração média de 20 minutos; 400 usam uma linha periférica com duração média de 50 minutos. Uma intervenção reduziria a duração periférica para 35 minutos, sem mudar a quantidade de viagens. Considere médias dos dois grupos, não tempos idênticos para cada pessoa.\n\nQual duração média ponderada das viagens existe inicialmente?","version":4}},{"id":"d1394000-0000-4000-8000-000000000018","label":"G20","beforeHash":"bb748fcd94f9d2aa42072a1a849c3cef4157bce71b26dfb5ef9c8faf698c0750","afterHash":"95b20e8964b0f239e0de16ce50a4b830a6e6d46fbb9422211d2eb85292718dfc","patch":{"difficulty":"easy","statement":"Um produto vendido por R$ 1.000 envolve etapas em três regiões: extração e materiais somam R$ 100; montagem soma R$ 200; desenvolvimento, marca e comercialização somam R$ 700. Para o exercício, os valores particionam o preço sem dupla contagem. Não se informa como cada etapa distribui sua receita entre salários, custos e lucros.\n\nQual participação do preço corresponde à montagem?","version":4}},{"id":"d1434000-0000-4000-8000-000000000021","label":"G21","beforeHash":"7b744072b4d1906bda649286780919bcf8e0c60da56a85c96ecedb2b82fe9490","afterHash":"4f9ce3867a7716b21dec58d4eb558d67a19dee4150ae54425dde9f42a4531a82","patch":{"difficulty":"medium","statement":"Um terreno quadrado tem lado de 2 cm em um mapa de escala 1:50.000. Despreze distorções da projeção.\n\nQual área real corresponde ao terreno?","options":["4 km²","2 km²","1 km²","0,25 km²","0,5 km²"],"explanation":"Cada lado corresponde a 2 × 50.000 = 100.000 cm, ou 1 km. A área é 1 × 1 = 1 km²; o fator de conversão linear deve ser aplicado aos dois lados.","version":2}},{"id":"d1434000-0000-4000-8000-000000000022","label":"G22","beforeHash":"8f0ba4d976e477febe88dcfb186a5101ccc78cc8531ca7ae5bf458c5d3299445","afterHash":"2c7ea6961d99ef8c682bd597d7e0e74751c6958e7097a136254c21e2fb817e7d","patch":{"difficulty":"medium","statement":"A região A tem 600.000 habitantes em 3.000 km²; B tem 400.000 habitantes em 1.000 km². Em A, 80% das pessoas vivem em apenas 20% da área. As áreas não se sobrepõem e os dados referem-se ao mesmo ano.\n\nQual densidade existe na parcela de A que concentra 80% da população?","version":2}},{"id":"d1434000-0000-4000-8000-000000000023","label":"G23","beforeHash":"b2ea77c08fce88234ce928346ab12ccdff172c11956120a91a5cf7a4983bc180","afterHash":"d7e947760dcc615534d98600523b4b0defce5b66bd02c85a03831abcbfbe086d","patch":{"difficulty":"medium","statement":"Um município tinha 80.000 habitantes, dos quais 60.000 urbanos. Dez anos depois passou a 100.000 habitantes, sendo 85.000 urbanos. Considere os mesmos limites territoriais e critérios de classificação nos dois momentos.\n\nComo mudou a população rural absoluta?","version":2}},{"id":"d1434000-0000-4000-8000-000000000024","label":"G24","beforeHash":"ba359c1e9bc83e613d6007b9f40af03ffe514649bfb7e0eb9892e9f7d394f9d0","afterHash":"f4d1ab68338e310e92f66896fc94c1fae9743b30b482c0b9bf65ce90d65925ce","patch":{"difficulty":"easy","statement":"Uma região começa o ano com 50.000 habitantes. Registra 900 nascimentos, 400 mortes, 1.500 imigrantes e 2.000 emigrantes. As categorias não se sobrepõem, não há mudança de limites e os valores correspondem ao mesmo ano.\n\nQual par distingue os componentes demográficos?","version":2}},{"id":"d1434000-0000-4000-8000-000000000025","label":"G25","beforeHash":"072666707447269d11e58cbb177b226b054bf1cf9a807055b446c289f08a5825","afterHash":"15d8bbc7515641c8de09d567692bfa57d3d138dd4bb3335c5513f7a8d3525cc4","patch":{"difficulty":"easy","statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. a razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQue fração da população total tem 65 anos ou mais?","version":2}},{"id":"d1434000-0000-4000-8000-000000000026","label":"G26","beforeHash":"b8a2cdb2e57ac833e56658757ba7b4faa8bdf0323c15b46f125a60128922c375","afterHash":"5bfa6884993f1293fef9144ea39535602b6819804481bc29982da68efb7963a4","patch":{"difficulty":"easy","statement":"A propriedade A colheu 12.000 toneladas em 3.000 hectares; B colheu 10.000 toneladas em 2.000 hectares. No ano seguinte, A pretende aumentar a produção para 15.000 toneladas mantendo a área. Os dados não incluem custo, renda dos trabalhadores ou impactos ambientais.\n\nQue produtividade A precisará atingir para cumprir a meta sem ampliar área?","version":2}},{"id":"d1434000-0000-4000-8000-000000000027","label":"G27","beforeHash":"c9a4370dabbf9e5e74219a2fab449141d1beb7c66f008da51a2c71ac44b59eb7","afterHash":"2bad364e54659629b19a5d5f44a98b34acef020a1b6ac3da87f8d144d945abbd","patch":{"difficulty":"medium","statement":"Em uma bacia de 1.000 km², a cobertura florestal era 600 km² e passou a 450 km². Áreas impermeabilizadas passaram de 100 para 200 km²; os demais usos ocupam a área restante. Os períodos têm os mesmos limites. O relatório não identifica automaticamente as causas de cada mudança.\n\nComo mudou a participação das áreas impermeabilizadas no território total?","version":2}},{"id":"d1434000-0000-4000-8000-000000000028","label":"G28","beforeHash":"e5e58bef60b70e01a672cfdb7119282b5197b5ee064015111b4caca2d0a0d050","afterHash":"a6c5d6c306033c87dc266f2bb42948094b18367d9ab43fed2364e7e30491e660","patch":{"difficulty":"medium","statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. No período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual energia conjunta média seria produzida em 10 horas sob esses valores médios?","version":2}},{"id":"d1434000-0000-4000-8000-000000000029","label":"G29","beforeHash":"5250e3aa377998bf3409b592ff53c4338bad1ae24f95c014efd5f0f3fa9d48ee","afterHash":"d61d03ef25c4efd77c82b105aa7d42d9dc116e88cb7199c23e9ed12655ae3964","patch":{"difficulty":"medium","statement":"O país A emite 120 milhões de toneladas de um gás em um ano e tem 60 milhões de habitantes. B emite 80 milhões de toneladas e tem 20 milhões de habitantes. Considere a mesma metodologia de inventário e não inclua emissões históricas acumuladas neste cálculo.\n\nQual emissão per capita conjunta se obtém ao agregar os dois países?","version":2}},{"id":"d1434000-0000-4000-8000-000000000030","label":"G30","beforeHash":"d64b6804c67319f303527c00fc676dc45283be97dae9642f8cc56b1c460cf56e","afterHash":"b10e48bb4b0a8a1e67cf7b53af3e40e6531deece3394eb0c49b00fd320f65787","patch":{"difficulty":"medium","statement":"Uma carga de 400 toneladas deve percorrer 300 km. A rodovia cobra R$ 0,30 por tonelada-quilômetro. A ferrovia cobra R$ 0,15 por tonelada-quilômetro e exige R$ 12.000 de transferência nos terminais. Ignore custos e prazos não informados; a transferência é cobrada uma vez para toda a carga.\n\nQual distância iguala os custos mantendo as demais condições?","version":2}},{"id":"d1434000-0000-4000-8000-000000000031","label":"G31","beforeHash":"e696951dcb69a72e6cd60550b1248cb3ed940df04220e3acfdee7413c21624a2","afterHash":"fe93fa525853ec0021958c003fe918000cd08863b83e6bfc1dd2605a587cc99d","patch":{"difficulty":"medium","statement":"Uma região exporta 50 milhões de reais em alimentos e 30 milhões em equipamentos. Importa 20 milhões em alimentos e 45 milhões em equipamentos. Os dados usam a mesma moeda e período e não incluem serviços, investimentos ou movimentos financeiros.\n\nQual comparação setorial é correta?","version":2}},{"id":"d1434000-0000-4000-8000-000000000032","label":"G32","beforeHash":"b775d204582bff9f8b2183ba977678efa7dd3739d01fc37d9032d3ab39a5ce65","afterHash":"a519e3da3f1549cf7be008cb4d1bd3d352cd99a6b6ab24d182a6a3026e53662b","patch":{"difficulty":"easy","statement":"Cinco domicílios de um setor têm rendas mensais de R$ 1.000, R$ 1.200, R$ 1.500, R$ 2.000 e R$ 9.300. Outro setor tem cinco domicílios com R$ 3.000 cada. A comparação não inclui diferenças de tamanho familiar ou custo de vida.\n\nQual mediana existe no primeiro setor?","version":2}},{"id":"d1434000-0000-4000-8000-000000000033","label":"G33","beforeHash":"dece760c17eccfe2b1aa93c1ce12c5ceeb406eb87b9e85f3b65a694895e8d5aa","afterHash":"b90faa1a3cdbf1d738f1b4b18b1f60735ba515e0df1a9beb5df20b780269add9","patch":{"difficulty":"easy","statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nSe julho recebesse irrigação de 50 mm, qual saldo simplificado passaria a ter?","version":2}},{"id":"d1434000-0000-4000-8000-000000000034","label":"G34","beforeHash":"3a885a083dd858f559081bb1d2f66ec6b7fe88ef7559b32db12e51ee9b6b0f4d","afterHash":"01fc2d72589aab2ec2cbb2f0056868b042c99a8aeb65c1090945737027ffbc51","patch":{"difficulty":"medium","statement":"Uma bacia recebe, no período estudado, 100 unidades de água por precipitação e 10 por entrada externa. Perde 40 por evapotranspiração e 50 por saída fluvial. No modelo, a diferença altera o armazenamento. Uma captação adicional retiraria 30 unidades, sem outras mudanças.\n\nQue alteração do armazenamento resulta com a captação adicional?","version":2}},{"id":"d1434000-0000-4000-8000-000000000035","label":"G35","beforeHash":"0cc2dfaaa750f5ca228ab0df334fce7167d398ffccec6b3f30a822eca3e660d4","afterHash":"83ddbb29d02474d8fca9adb4cdcddcd2f3abae03fe4065de97b1057ee8dc84ff","patch":{"difficulty":"medium","statement":"Duas encostas têm a mesma declividade e recebem chuva semelhante. A mantém vegetação e solo permeável; B foi desmatada e tem trechos compactados. Há moradias na parte baixa de ambas. O relatório considera escoamento, erosão e exposição de pessoas, sem afirmar que um único fator determina todos os eventos.\n\nQual informação é necessária para avaliar risco às pessoas além da tendência física?","version":2}},{"id":"d1434000-0000-4000-8000-000000000036","label":"G36","beforeHash":"8320bcc6ee3f07fa4b40bc48f924d871dbe2a33c7dd1e54059fdea3c037c6e81","afterHash":"05520dda6debd39396b2870a84d11dec748d795bab360c0fc8467a2ba3c65adc","patch":{"difficulty":"medium","statement":"Um voo chega a B (UTC+1) às 10h de terça-feira. Após duas horas de conexão, outro voo de quatro horas segue para C (UTC+5). Os fusos não mudam.\n\nEm que horário local chega a C?","options":["0h de quarta-feira.","20h de terça-feira.","12h de terça-feira.","16h de terça-feira.","18h de terça-feira."],"explanation":"A saída de B é às 12h locais e a chegada seria às 16h no relógio de B. C está quatro horas adiante: 16 + 4 = 20h de terça-feira.","version":2}},{"id":"d1434000-0000-4000-8000-000000000037","label":"G37","beforeHash":"b8a6d0689c8ef079721be5604f5f7c5aabf5795741e46d7b71c7399c0bc9b4e3","afterHash":"567a8b6d6b9cddad7aaa90e8d12a09a579dd631bfab813efd1e47da95cbb5aa9","patch":{"difficulty":"easy","statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQual separação angular de latitude existe entre A e B?","version":2}},{"id":"d1434000-0000-4000-8000-000000000038","label":"G38","beforeHash":"535bab7f4f6d2a8d66e6f2b93600f25b21f630933a2add7829682925f661a0b4","afterHash":"ec7068a1606f2f05ff3f4ace8bea1ffb2a6a6a39518097e05d7423c974dad392","patch":{"difficulty":"medium","statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nSe 1.000 desocupados conseguirem trabalho e ninguém mudar de grupo de participação, qual será a nova taxa?","version":2}},{"id":"d1434000-0000-4000-8000-000000000039","label":"G39","beforeHash":"08cf27f57619368b21ddbe4058ebad9937deffb31e22ac7a863ae50bb2b77467","afterHash":"59851ea4a9608bf1b82f6ac595e02fbb322b9caf469c30e9c10586cd1d140bf6","patch":{"difficulty":"medium","statement":"Em uma cidade, 600 viagens usam uma linha rápida com duração média de 20 minutos; 400 usam uma linha periférica com duração média de 50 minutos. Uma intervenção reduziria a duração periférica para 35 minutos, sem mudar a quantidade de viagens. Considere médias dos dois grupos, não tempos idênticos para cada pessoa.\n\nQual média resulta depois da intervenção prevista?","version":2}},{"id":"d1434000-0000-4000-8000-000000000040","label":"G40","beforeHash":"4bb857456de196a2840b9020f3ca86dcc3bccfd7595e5197104bd02567c6a4bd","afterHash":"bf47a297bcda6b753db1c9584402957cd5d6553fdb5cb7ac412afbe240afe06b","patch":{"difficulty":"medium","statement":"Um produto vendido por R$ 1.000 envolve etapas em três regiões: extração e materiais somam R$ 100; montagem soma R$ 200; desenvolvimento, marca e comercialização somam R$ 700. Para o exercício, os valores particionam o preço sem dupla contagem. Não se informa como cada etapa distribui sua receita entre salários, custos e lucros.\n\nQual comparação entre localização da montagem e apropriação do valor total é coerente?","version":2}},{"id":"d1434000-0000-4000-8000-000000000041","label":"G41","beforeHash":"1db6b27d568fb13149bf588316ee2abfe4b1f216320b6a1c56751d9e3ad28bbd","afterHash":"b717b3b82047742bb66af64f8f6ef68b2a7eb1044ceab03f62b1f747af47ea97","patch":{"difficulty":"medium","statement":"Uma trilha de 4 km será desenhada em um mapa de escala 1:25.000. Despreze distorções da projeção.\n\nQual será seu comprimento no papel?","options":["8 cm","1,6 cm","32 cm","4 cm","16 cm"],"explanation":"Quatro quilômetros correspondem a 400.000 cm. Dividindo pelo denominador da escala: 400.000/25.000 = 16 cm no papel.","version":2}},{"id":"d1434000-0000-4000-8000-000000000042","label":"G42","beforeHash":"22f93dc46ae07aeca863033f70f71bbabbb93f0afe0b218606e2bc9f17e9e2fc","afterHash":"7c1d6cfb8b092060b595b0fcf22a1f53146ded82fa8c813e03b4f9ee9314e6ff","patch":{"difficulty":"medium","statement":"A região A tem 600.000 habitantes em 3.000 km²; B tem 400.000 habitantes em 1.000 km². Em A, 80% das pessoas vivem em apenas 20% da área. As áreas não se sobrepõem e os dados referem-se ao mesmo ano.\n\nQual densidade conjunta resulta de agregar A e B?","version":2}},{"id":"d1434000-0000-4000-8000-000000000043","label":"G43","beforeHash":"6a5c92fe2c77835617d92b6148cd411be83f85baec05b6afb9c38697b1785440","afterHash":"ea3b43eb353ae8e8f2e4e1aa648c69d525fb48ec75b50aee566aa26869ad0bd9","patch":{"difficulty":"medium","statement":"Um município tinha 80.000 habitantes, dos quais 60.000 urbanos. Dez anos depois passou a 100.000 habitantes, sendo 85.000 urbanos. Considere os mesmos limites territoriais e critérios de classificação nos dois momentos.\n\nQual crescimento relativo da população urbana ocorreu?","version":2}},{"id":"d1434000-0000-4000-8000-000000000044","label":"G44","beforeHash":"2807bc6aaa93253bbe7d69d79f580541a6f60fb3c8947cd0436c5863e8575b90","afterHash":"9a348e77efcbde9f7abc9ddfd3644b94fb72ae774bcbeba1d4f3f3dceb69cefa","patch":{"difficulty":"medium","statement":"Uma região começa o ano com 50.000 habitantes. Registra 900 nascimentos, 400 mortes, 1.500 imigrantes e 2.000 emigrantes. As categorias não se sobrepõem, não há mudança de limites e os valores correspondem ao mesmo ano.\n\nQual taxa de crescimento natural se obtém usando a população inicial como base?","version":2}},{"id":"d1434000-0000-4000-8000-000000000045","label":"G45","beforeHash":"d26285c348ac5a7534503d863437feb09904afab40766ddb0b11f7d094aba160","afterHash":"20b1073ca12dc0dad62bb147841aa7ab5474ee517f8b269d8842fd07f7b4e171","patch":{"difficulty":"medium","statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. a razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nPor que não se pode transformar diretamente a razão calculada em desemprego?","version":2}},{"id":"d1434000-0000-4000-8000-000000000046","label":"G46","beforeHash":"3f3cc8b0613b96033f3fd96cdedb09aa9251efcfeaa58328db32025b5e6ffe97","afterHash":"16f84404c865238f8dd423236b45ee694f09abaf4d1027509ff8a37811fbe52e","patch":{"difficulty":"easy","statement":"A propriedade A colheu 12.000 toneladas em 3.000 hectares; B colheu 10.000 toneladas em 2.000 hectares. No ano seguinte, A pretende aumentar a produção para 15.000 toneladas mantendo a área. Os dados não incluem custo, renda dos trabalhadores ou impactos ambientais.\n\nQual aumento percentual de produtividade essa meta exige em relação ao ano inicial?","version":2}},{"id":"d1434000-0000-4000-8000-000000000047","label":"G47","beforeHash":"30bc06fdfe910e272391f007c0e785e4568110e4ceec1da62623cc746c92c930","afterHash":"31077280895fc6d13c327fb9945d5bb6ad64ee6681c79bde3e541ff61c96cd92","patch":{"difficulty":"medium","statement":"Em uma bacia de 1.000 km², a cobertura florestal era 600 km² e passou a 450 km². Áreas impermeabilizadas passaram de 100 para 200 km²; os demais usos ocupam a área restante. Os períodos têm os mesmos limites. O relatório não identifica automaticamente as causas de cada mudança.\n\nQual tendência hidrológica pode resultar da maior impermeabilização, mantendo precipitação comparável?","version":2}},{"id":"d1434000-0000-4000-8000-000000000048","label":"G48","beforeHash":"16ab80e91571c4bb9ead316c8910609b7fb988de82e9c8efc3e1d555b0ea8b33","afterHash":"e87f0f594b4db3685cae434c24529b8197fe51de148221e0fca5871bcb201bc4","patch":{"difficulty":"medium","statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. No período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual participação aproximada da geração solar no total médio das duas fontes?","version":2}},{"id":"d1434000-0000-4000-8000-000000000049","label":"G49","beforeHash":"efd264d2ca75bda31e84bc904f6b5f4d5b0cae0e149c4ebaf35f4705a0db40c6","afterHash":"9b18eb21ed6509f36eeb645eb3383580cf78c721b8231592a91abeba9020035c","patch":{"difficulty":"medium","statement":"O país A emite 120 milhões de toneladas de um gás em um ano e tem 60 milhões de habitantes. B emite 80 milhões de toneladas e tem 20 milhões de habitantes. Considere a mesma metodologia de inventário e não inclua emissões históricas acumuladas neste cálculo.\n\nSe B reduzir seu total em 25% e mantiver população, que emissão per capita terá?","version":2}},{"id":"d1434000-0000-4000-8000-000000000050","label":"G50","beforeHash":"35f87f674fccef02eee554a66b0114ca9dec1e7e500c7b6e73e3ad33c33872d1","afterHash":"7569b2db43e3efea5064b3cdb5f263ad57436e0739198ca2730be5457893e25e","patch":{"difficulty":"medium","statement":"Uma carga de 400 toneladas deve percorrer 300 km. A rodovia cobra R$ 0,30 por tonelada-quilômetro. A ferrovia cobra R$ 0,15 por tonelada-quilômetro e exige R$ 12.000 de transferência nos terminais. Ignore custos e prazos não informados; a transferência é cobrada uma vez para toda a carga.\n\nPara percurso de 100 km, qual modal tem menor custo nas hipóteses dadas?","version":2}},{"id":"d1434000-0000-4000-8000-000000000051","label":"G51","beforeHash":"09eefb50db98f8617edf4d117dd620ed71a0c9aacc0f2d3cd4cbdff1670374b5","afterHash":"007934d85398fe37c81bf467ebee68b758874636c11265163f2529d72595b2dd","patch":{"difficulty":"medium","statement":"Uma região exporta 50 milhões de reais em alimentos e 30 milhões em equipamentos. Importa 20 milhões em alimentos e 45 milhões em equipamentos. Os dados usam a mesma moeda e período e não incluem serviços, investimentos ou movimentos financeiros.\n\nSe a exportação de equipamentos aumentar 50%, mantendo os demais valores, qual saldo total resulta?","version":2}},{"id":"d1434000-0000-4000-8000-000000000052","label":"G52","beforeHash":"fbfd38b06d8df52787b33a8168a3f67fedf0a826908c19864a75f05794611189","afterHash":"65cd037e8aa6396f0659405c824ef37855bad1411c961c6337563849b53145fa","patch":{"difficulty":"medium","statement":"Cinco domicílios de um setor têm rendas mensais de R$ 1.000, R$ 1.200, R$ 1.500, R$ 2.000 e R$ 9.300. Outro setor tem cinco domicílios com R$ 3.000 cada. A comparação não inclui diferenças de tamanho familiar ou custo de vida.\n\nQue percentual da renda total do primeiro setor cabe ao domicílio de maior renda?","version":2}},{"id":"d1434000-0000-4000-8000-000000000053","label":"G53","beforeHash":"e49ea9aed5eaa5943acc5a1b2314cb65fd1fbe38fc8515c63f65d5324a29a909","afterHash":"b3fd67aec1b706757547901850b5b3269e0e0b334347a286cb56e8e62c44d822","patch":{"difficulty":"medium","statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQue informação falta para transformar esse saldo em diagnóstico completo de disponibilidade de água para plantas?","version":2}},{"id":"d1434000-0000-4000-8000-000000000054","label":"G54","beforeHash":"bd89119b55d871ac211faef1dea9029471ed9adaff5134167f855bbd5e3aaca1","afterHash":"4abdf1e7a2fdd25f4b9796b1225d40c986a0190a97b1c5afaee4d9095c2a7d7e","patch":{"difficulty":"medium","statement":"Uma bacia recebe, no período estudado, 100 unidades de água por precipitação e 10 por entrada externa. Perde 40 por evapotranspiração e 50 por saída fluvial. No modelo, a diferença altera o armazenamento. Uma captação adicional retiraria 30 unidades, sem outras mudanças.\n\nPor que saldo negativo não significa automaticamente que não resta água na bacia?","version":2}},{"id":"d1434000-0000-4000-8000-000000000055","label":"G55","beforeHash":"a3379860a5c984f7da9831ddebd7f16c3e00011c41c5c65998a642c75b78ef5d","afterHash":"d48bb02cc480c3b8fe0dedd2f0019280dbb48244ea68fb3587cbef3631efec1f","patch":{"difficulty":"medium","statement":"Duas encostas têm a mesma declividade e recebem chuva semelhante. A mantém vegetação e solo permeável; B foi desmatada e tem trechos compactados. Há moradias na parte baixa de ambas. O relatório considera escoamento, erosão e exposição de pessoas, sem afirmar que um único fator determina todos os eventos.\n\nUma obra de drenagem em B elimina automaticamente todo risco?","version":2}},{"id":"d1434000-0000-4000-8000-000000000056","label":"G56","beforeHash":"0d3186e38562ff0ca15d5cbfe5a8194424b7752797f56e3d124d8d626bb1c2ef","afterHash":"8e7d9a5027a76416da5de874fd9e9fa79418958b0fdf5311cdade8f3823201da","patch":{"difficulty":"easy","statement":"Uma viagem tem um voo de oito horas, conexão de duas horas e outro voo de quatro horas.\n\nQual é a duração da viagem, incluindo a conexão?","options":["16 horas","10 horas","18 horas","14 horas","12 horas"],"explanation":"Somam-se as durações: 8 + 2 + 4 = 14 horas. Não é necessário saber os fusos, pois os três valores já expressam intervalos de tempo, não leituras de relógios locais.","version":2}},{"id":"d1434000-0000-4000-8000-000000000057","label":"G57","beforeHash":"7b118bd940267f7e0c1c6fbff48d8cf0682b7705cc9cc24e15213a3e9a542a97","afterHash":"ba62c0be679dffaf22e51a4f4bf755ea8e6c2c9ded21e702950768418de595e8","patch":{"difficulty":"medium","statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nEm relação a A, C está em que direção sobre o paralelo indicado?","version":2}},{"id":"d1434000-0000-4000-8000-000000000058","label":"G58","beforeHash":"f30a48e1821a77996f72fbf4aa1f72adeae1b545fc27f37b1befd692f676212e","afterHash":"c8c74bf3ce2da6d53bf35fa620360e715bc229b5eedb6f8d1ee2c06530941606","patch":{"difficulty":"medium","statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nSe 1.000 desocupados deixarem de procurar trabalho e saírem da força, sem conseguir emprego, qual taxa resulta?","version":2}},{"id":"d1434000-0000-4000-8000-000000000059","label":"G59","beforeHash":"c3f1e948cae52871f81322a50e6e64e12f1a9b3634e86a49f91ec39db09f6d17","afterHash":"2da9be04f71041c19b6a54a238c1287634f6196014b0148e24f7673cf65f5989","patch":{"difficulty":"medium","statement":"Em uma cidade, 600 viagens usam uma linha rápida com duração média de 20 minutos; 400 usam uma linha periférica com duração média de 50 minutos. Uma intervenção reduziria a duração periférica para 35 minutos, sem mudar a quantidade de viagens. Considere médias dos dois grupos, não tempos idênticos para cada pessoa.\n\nQuantos minutos de viagem são poupados no conjunto de 400 viagens periféricas?","version":2}},{"id":"d1434000-0000-4000-8000-000000000060","label":"G60","beforeHash":"31d89187811f93ddaf215a14ad16d491777c98064888dcfd1415eeec9ffbac6b","afterHash":"b5b97971c9ab6113b757baad69643bdaf8cd425b18fe58e30550260a941d6c45","patch":{"difficulty":"easy","statement":"Um produto vendido por R$ 1.000 envolve etapas em três regiões: extração e materiais somam R$ 100; montagem soma R$ 200; desenvolvimento, marca e comercialização somam R$ 700. Para o exercício, os valores particionam o preço sem dupla contagem. Não se informa como cada etapa distribui sua receita entre salários, custos e lucros.\n\nSe o preço e todas as parcelas aumentarem 10%, qual valor passa a corresponder à montagem?","version":2}},{"id":"d1434000-0000-4000-8000-000000000061","label":"G61","beforeHash":"e0d7f1400bc584d048c75bf6db1a4a29e97c341ceb32640f144ec5b7d0483391","afterHash":"f4644574f8238ddcc9293bc0dba3b5fe0810f9f29f29946ba9ed1afe852e4654","patch":{"difficulty":"easy","statement":"Dois mapas representam a mesma região nas escalas 1:50.000 e 1:25.000.\n\nQual comparação entre as escalas está correta?","options":["A escala 1:25.000 reduz pela metade as distâncias no papel para a mesma região.","A escala 1:50.000 permite mais detalhes porque representa mais território em cada centímetro.","A escala 1:50.000 é maior porque seu denominador é maior.","A escala 1:25.000 é maior e permite mais detalhes, usando maior espaço no papel para a mesma região.","As duas escalas mostram a mesma distância no papel, pois ambas começam por 1."],"explanation":"Escala é uma razão: 1/25.000 é maior que 1/50.000. Para a mesma distância real, o primeiro mapa usa o dobro do comprimento no papel, permitindo representar mais detalhes.","version":2}},{"id":"d1434000-0000-4000-8000-000000000062","label":"G62","beforeHash":"c1db7ca0b34c194c8c500dd40fdec819be0036603ef8cf3f5a64544f2cc696a1","afterHash":"3358b24e0976dae0d5f1321506de0d36ff4fe4031f28668fd0318db99718df64","patch":{"difficulty":"medium","statement":"A região A tem 600.000 habitantes em 3.000 km²; B tem 400.000 habitantes em 1.000 km². Em A, 80% das pessoas vivem em apenas 20% da área. As áreas não se sobrepõem e os dados referem-se ao mesmo ano.\n\nPor que a média de A não descreve a distribuição interna da população?","version":2}},{"id":"d1434000-0000-4000-8000-000000000063","label":"G63","beforeHash":"1a5e16b603a864228c967cc0314785c89ace866c139bb822e17da73fc400fd13","afterHash":"918598a5c46a4025d536e9729bd32c331b3b39e20ee1c6bd71637c2d7e680602","patch":{"difficulty":"medium","statement":"Um município tinha 80.000 habitantes, dos quais 60.000 urbanos. Dez anos depois passou a 100.000 habitantes, sendo 85.000 urbanos. Considere os mesmos limites territoriais e critérios de classificação nos dois momentos.\n\nO aumento da população urbana de 60.000 para 85.000 permite concluir que 25.000 pessoas migraram do campo para a cidade?","version":3}},{"id":"d1434000-0000-4000-8000-000000000064","label":"G64","beforeHash":"fdaa07ec58f027f182858e12fca40031bd2635edbeb8d8eba7c04561de278e36","afterHash":"5d23cb0999ad090d0eadf0ab5a3f5d5ee295a1d54d764f875c4e791f7ab0363a","patch":{"difficulty":"medium","statement":"Uma região começa o ano com 50.000 habitantes. Registra 900 nascimentos, 400 mortes, 1.500 imigrantes e 2.000 emigrantes. As categorias não se sobrepõem, não há mudança de limites e os valores correspondem ao mesmo ano.\n\nSe a emigração caísse para 1.000, mantendo os demais valores, qual seria o crescimento total?","version":2}},{"id":"d1434000-0000-4000-8000-000000000065","label":"G65","beforeHash":"bdc3018e63c08a9260c1ba40dad031fe0af1151401059be120bf942664fac5ee","afterHash":"934a7f4e13b654a36d8aa6458b4b0c4a49c30626cc5e6f018f10da2e82308ef6","patch":{"difficulty":"medium","statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. a razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nSe o grupo de 65 ou mais passar a 20.000 e os outros ficarem iguais, qual razão resulta?","version":2}},{"id":"d1434000-0000-4000-8000-000000000066","label":"G66","beforeHash":"7ed1ba1c1da50abf29d328c1cfc203e38c6e60ff9f4297b62e48447a3720dea2","afterHash":"15d49193650bae4fef44312e02e718a852dcbc68c8525e1c5bf6b8cbcd10f4a5","patch":{"difficulty":"medium","statement":"A propriedade A colheu 12.000 toneladas em 3.000 hectares; B colheu 10.000 toneladas em 2.000 hectares. No ano seguinte, A pretende aumentar a produção para 15.000 toneladas mantendo a área. Os dados não incluem custo, renda dos trabalhadores ou impactos ambientais.\n\nSe A mantivesse 4 t/ha, que área precisaria para obter 15.000 toneladas?","version":2}},{"id":"d1434000-0000-4000-8000-000000000067","label":"G67","beforeHash":"569b509f061f185de220c625467c30c0c0362c7c04568d01b18bfc48c050c8bf","afterHash":"e40b5b3e46ec362ac3bf29a0f2b9974c6846cae992f5603393bfe758f0011e70","patch":{"difficulty":"medium","statement":"Em uma bacia de 1.000 km², a cobertura florestal era 600 km² e passou a 450 km². Áreas impermeabilizadas passaram de 100 para 200 km²; os demais usos ocupam a área restante. Os períodos têm os mesmos limites. O relatório não identifica automaticamente as causas de cada mudança.\n\nÉ possível afirmar que os 150 km² de floresta perdida viraram integralmente área impermeabilizada?","version":2}},{"id":"d1434000-0000-4000-8000-000000000068","label":"G68","beforeHash":"be406d2401cf26fcd175ad39f8f79dcf92bde1a55bb9efc897e2eab540d1786e","afterHash":"98d4f7582d39534958b567a83dc2e46c082d9ace9160abd9217bba3dbc341737","patch":{"difficulty":"medium","statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. No período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nPor que esses valores não demonstram disponibilidade de 55 MW em qualquer hora?","version":2}},{"id":"d1434000-0000-4000-8000-000000000069","label":"G69","beforeHash":"61d7451f8f1391337cedf0cecb95c2ee0458a9247df989069b5474377106886d","afterHash":"c3a2c11416c3930b2e97b9440a3240dd58aab9a87083fdd5ddda56643e8e4480","patch":{"difficulty":"medium","statement":"O país A emite 120 milhões de toneladas de um gás em um ano e tem 60 milhões de habitantes. B emite 80 milhões de toneladas e tem 20 milhões de habitantes. Considere a mesma metodologia de inventário e não inclua emissões históricas acumuladas neste cálculo.\n\nO indicador per capita comprova que cada morador emite exatamente o valor médio?","version":2}},{"id":"d1434000-0000-4000-8000-000000000070","label":"G70","beforeHash":"28d38f224c20a49db4a052b1381a5d04f2c7b1064770cbfbb9e594f875495057","afterHash":"f8cf1d4cb92bed4c60801c286e08cbef8f3c84e7e1b28ad90835901bd9365773","patch":{"difficulty":"medium","statement":"Uma carga de 400 toneladas deve percorrer 300 km. A rodovia cobra R$ 0,30 por tonelada-quilômetro. A ferrovia cobra R$ 0,15 por tonelada-quilômetro e exige R$ 12.000 de transferência nos terminais. Ignore custos e prazos não informados; a transferência é cobrada uma vez para toda a carga.\n\nQue conclusão não é sustentada apenas pelo menor custo no percurso de 300 km?","version":2}},{"id":"d1434000-0000-4000-8000-000000000071","label":"G71","beforeHash":"d287097f1a117eff0ca844a83acd1c060bf813457f5176aee734522f64db8cd9","afterHash":"e0de442ba99e4fa3371dd0db71bf6c3684b06c7edb975b45f1be97b8fd5e7e6e","patch":{"difficulty":"medium","statement":"Uma região exporta 50 milhões de reais em alimentos e 30 milhões em equipamentos. Importa 20 milhões em alimentos e 45 milhões em equipamentos. Os dados usam a mesma moeda e período e não incluem serviços, investimentos ou movimentos financeiros.\n\nO superávit comercial comprova que a região não depende de produtos externos?","version":2}},{"id":"d1434000-0000-4000-8000-000000000072","label":"G72","beforeHash":"00da49f3ccdbf0e9ef2c2e145ffb73882e5e438afcfc8a1fdc05396900de287c","afterHash":"f4a3919e02dd6fc6174b384032700d5675d3fc31c4f36bb02cac913f5cdb34bb","patch":{"difficulty":"medium","statement":"Cinco domicílios de um setor têm rendas mensais de R$ 1.000, R$ 1.200, R$ 1.500, R$ 2.000 e R$ 9.300. Outro setor tem cinco domicílios com R$ 3.000 cada. A comparação não inclui diferenças de tamanho familiar ou custo de vida.\n\nQual leitura evita confundir renda média com situação de cada domicílio?","version":2}},{"id":"d1434000-0000-4000-8000-000000000073","label":"G73","beforeHash":"db904438cec909c8df631f0d4b6d7efa721e382f056c17ba4be3b00f163226ff","afterHash":"d56cc10c97902371ea673bcf74944dd1f633a15e11477526c5590f9eac445580","patch":{"difficulty":"easy","statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nUma sequência de dois meses com saldos −60 e −20 mm representa que saldo acumulado simplificado?","version":2}},{"id":"d1434000-0000-4000-8000-000000000074","label":"G74","beforeHash":"ca1b8a373be2b6aa720dfff83c103317d6224cafcf6275ce463c39dd9c4a764c","afterHash":"bf9d7eca87f17c4f84d96d189356791f99deafa8f34be7a8845c31275828157b","patch":{"difficulty":"medium","statement":"Uma bacia recebe, no período estudado, 100 unidades de água por precipitação e 10 por entrada externa. Perde 40 por evapotranspiração e 50 por saída fluvial. No modelo, a diferença altera o armazenamento. Uma captação adicional retiraria 30 unidades, sem outras mudanças.\n\nQue problema pode surgir ao avaliar apenas a precipitação total?","version":2}},{"id":"d1434000-0000-4000-8000-000000000075","label":"G75","beforeHash":"e2d6eb9a3b038224b01c386126589cbe12c80ef68b504114078d0c30738a7c89","afterHash":"41ba44090bcd1d35c5fa99a87edaafd2a980608030c306845b4448acaee20574","patch":{"difficulty":"medium","statement":"Duas encostas têm a mesma declividade e recebem chuva semelhante. A mantém vegetação e solo permeável; B foi desmatada e tem trechos compactados. Há moradias na parte baixa de ambas. O relatório considera escoamento, erosão e exposição de pessoas, sem afirmar que um único fator determina todos os eventos.\n\nQue comparação preserva as hipóteses do estudo ao investigar cobertura vegetal?","version":2}},{"id":"d1434000-0000-4000-8000-000000000076","label":"G76","beforeHash":"bb22124feaae670445dc03a69c0dc01b627f2e6b9367177be14aa368e0a65c3d","afterHash":"9787b72ace241c0dfd1ce76ed85f78fd465c31a53591015796b47c638fc54859","patch":{"difficulty":"medium","statement":"Uma pessoa sai de A (UTC−3) às 22h de segunda-feira e chega a C (UTC+5) às 20h de terça-feira. Os fusos permanecem constantes.\n\nQual foi a duração real entre saída e chegada?","options":["30 horas","6 horas","22 horas","8 horas","14 horas"],"explanation":"Os horários locais aparentam um intervalo de 22 horas, mas C está oito horas adiante de A. Ao converter para uma referência comum, a duração é 22 − 8 = 14 horas. É necessário considerar também a mudança de data.","version":2}},{"id":"d1434000-0000-4000-8000-000000000077","label":"G77","beforeHash":"61682d07f3e74184cdf01e9b6141539976d5905e56461fcfad36f5c3d14a6c13","afterHash":"916290f4ad5d52165c08afc7bf1aa8592f410f9ab75ed9634a8b03e3ec849ac4","patch":{"difficulty":"medium","statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nEm um modelo esférico da Terra, por que 20° de longitude representam menor distância sobre o paralelo de 60° do que sobre o equador?","version":3}},{"id":"d1434000-0000-4000-8000-000000000078","label":"G78","beforeHash":"6fecaca8bab2c22d6400c3752be40287602050319e94a025195e90f7cb31fff2","afterHash":"9aba2d361dddd2df0acc58dbfcd371a98525ae254b1b27b5c7e7dfd83fce9eb5","patch":{"difficulty":"medium","statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nQue informação complementa a taxa para avaliar melhoria das condições de trabalho?","version":2}},{"id":"d1434000-0000-4000-8000-000000000079","label":"G79","beforeHash":"472e64879b4a5cbf21d5781d5ec1d90026d3d667b437deb07eb01cee8efac8f7","afterHash":"b266f382c5dafd3d96a6cb1a0eaf782b69acc76d1dd8e09197c28fe1780c7b2a","patch":{"difficulty":"medium","statement":"Em uma cidade, 600 viagens usam uma linha rápida com duração média de 20 minutos; 400 usam uma linha periférica com duração média de 50 minutos. Uma intervenção reduziria a duração periférica para 35 minutos, sem mudar a quantidade de viagens. Considere médias dos dois grupos, não tempos idênticos para cada pessoa.\n\nPor que a média geral de 32 minutos não retrata igualmente os dois grupos?","version":2}},{"id":"d1434000-0000-4000-8000-000000000080","label":"G80","beforeHash":"c1be5999ce0ac2c9b076d2c29e156b864e1a5c7dadbf82ca0be25d32741689f1","afterHash":"c372c12dfe69823ff5ae3f987527479bae9362e8d29948757c0d168d0c6c7814","patch":{"difficulty":"medium","statement":"Um produto vendido por R$ 1.000 envolve etapas em três regiões: extração e materiais somam R$ 100; montagem soma R$ 200; desenvolvimento, marca e comercialização somam R$ 700. Para o exercício, os valores particionam o preço sem dupla contagem. Não se informa como cada etapa distribui sua receita entre salários, custos e lucros.\n\nOs R$ 700 da última etapa correspondem necessariamente a lucro líquido de uma única empresa?","version":2}},{"id":"d1434000-0000-4000-8000-000000000081","label":"G81","beforeHash":"2ab451677d1068278158e5d685daa497e828582612c731160d61e6e1d5cd21e3","afterHash":"6d320049944f0a6b16d0b390040e14efcf5775da157126f55a34e37dc022a5bb","patch":{"statement":"Um mapa de escala 1:60.000 é ampliado proporcionalmente. Após a ampliação, a área no papel de um mesmo terreno quadrado fica quatro vezes maior.\n\nQual é a escala da cópia ampliada?","options":["1:120.000","1:240.000","1:15.000","1:30.000","1:60.000"],"explanation":"Se a área no papel quadruplica, cada comprimento dobra. A distância real permanece igual, então o denominador da escala é dividido por dois: 60.000/2 = 30.000. Dividir por quatro confundiria área com comprimento.","version":3}},{"id":"d1434000-0000-4000-8000-000000000082","label":"G82","beforeHash":"8a7164ab4a26753dd74b29eed7fb71d76e58d1837a82c899083956905a016b07","afterHash":"393a514ff8b785e2c78f94a07d0cb6dcf8787f0de5422c98f1adef9d1e886ffa","patch":{"difficulty":"medium","statement":"A região A tem 600.000 habitantes em 3.000 km². Uma parcela que ocupa 20% da área reúne 80% dos habitantes.\n\nQual é a densidade demográfica na área restante?","options":["50 hab./km²","250 hab./km²","40 hab./km²","200 hab./km²","800 hab./km²"],"explanation":"Na parte restante vivem 20% de 600.000 = 120.000 habitantes, em 80% de 3.000 = 2.400 km². A densidade é 120.000/2.400 = 50 hab./km². A concentração de um grupo não descreve a ocupação do território restante.","version":3}},{"id":"d1434000-0000-4000-8000-000000000083","label":"G83","beforeHash":"8237e880d7448fe7f612cfecafc9f85506a2c3a85a297a5db18c3187bbfc2a62","afterHash":"26ba460b7bb5a68d3028b1cea6e0afc2bfdf6ac43c2f231de433f79faff8ec8e","patch":{"difficulty":"medium","statement":"Um município tinha 80.000 habitantes, dos quais 60.000 urbanos. Dez anos depois passou a 100.000 habitantes, sendo 85.000 urbanos. Considere os mesmos limites territoriais e critérios de classificação nos dois momentos.\n\nQue mudança de classificação prejudicaria a comparação direta das taxas?","version":2}},{"id":"d1434000-0000-4000-8000-000000000084","label":"G84","beforeHash":"789fb91cc42dc259a1cbd30944d09cc936c94bcd5e8c3bbb99fe6009791ce664","afterHash":"618fe6a10b7ab5c127d30e722e9cdf4f81f559b13088024c5be12f690503b7bf","patch":{"difficulty":"medium","statement":"Uma região começa o ano com 50.000 habitantes. Registra 900 nascimentos, 400 mortes, 1.500 imigrantes e 2.000 emigrantes. As categorias não se sobrepõem, não há mudança de limites e os valores correspondem ao mesmo ano.\n\nQue leitura evita confundir estabilidade do total com imobilidade populacional?","version":2}},{"id":"d1434000-0000-4000-8000-000000000085","label":"G85","beforeHash":"0279b3b9502e3bdda0dfe63bce61083c4a73770f82622b14f88b9d32f822a3ca","afterHash":"b72ca8bb2247cf4e4defdc28f273e8ca17b26cb9c32bccfc6d78d1f04506991c","patch":{"difficulty":"medium","statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. a razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQue informação complementa esses números para planejar serviços?","version":2}},{"id":"d1434000-0000-4000-8000-000000000086","label":"G86","beforeHash":"a430de81918875ec86280a3c4c8a67abce33891d4c6d6e776517f07356e6e60f","afterHash":"9205f53536a96a6157d23c92f23021be48d646b258187fb5d10a5da03eccb045","patch":{"statement":"A propriedade A produz 12.000 t em 3.000 ha; B produz 10.000 t em 2.000 ha. Ambas vendem a R$ 700/t. Os custos totais por tonelada são R$ 500 em A e R$ 650 em B.\n\nQual comparação distingue produtividade e lucro total nesse período?","options":["B tem maior produtividade, mas A tem maior lucro total: R$ 2,4 milhões contra R$ 0,5 milhão.","B tem maior produtividade e maior lucro total, pois produz mais por hectare.","As duas têm o mesmo lucro por tonelada, pois o preço de venda é igual.","A tem maior produtividade e maior lucro total, pois produz mais toneladas.","A tem maior lucro total, mas B tem lucro de R$ 6,5 milhões, confundindo custo com lucro."],"explanation":"A produtividade é 4 t/ha em A e 5 t/ha em B. O lucro é receita menos custo: A = 12.000 × (700 − 500) = 2.400.000; B = 10.000 × (700 − 650) = 500.000. Maior rendimento por área não garante maior lucro.","version":3}},{"id":"d1434000-0000-4000-8000-000000000087","label":"G87","beforeHash":"bddd1e36e5746bd2da6f6d5e4a70dc42f8608e0fd816b5c31c148a84e6f856c0","afterHash":"a7d4f221523d1190096e79f8cc756fbbb259d8632b5b0026062b727fdb209a81","patch":{"difficulty":"medium","statement":"Em uma bacia de 1.000 km², a cobertura florestal era 600 km² e passou a 450 km². Áreas impermeabilizadas passaram de 100 para 200 km²; os demais usos ocupam a área restante. Os períodos têm os mesmos limites. O relatório não identifica automaticamente as causas de cada mudança.\n\nQue dado complementa o relatório para estudar causas e consequências?","version":2}},{"id":"d1434000-0000-4000-8000-000000000088","label":"G88","beforeHash":"70b76e9b75d83bdb1b5a480c36ece1c10648eab2c41f877e44a1c1e856d4b87f","afterHash":"6983a90d6a1d7395bc90b2f04b043287df94ba80d4312f73152972f8c2cac94b","patch":{"difficulty":"medium","statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. No período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual informação melhora o planejamento do atendimento contínuo da demanda?","version":2}},{"id":"d1434000-0000-4000-8000-000000000089","label":"G89","beforeHash":"0f04e6a3276b4f7c8734b69d40fe9865be705e15ffc70c6225a5a55fa6d4cd84","afterHash":"692cf0a0a1073f0002984071aad18e4491febd6103015ff37c16271d5d114c0b","patch":{"difficulty":"medium","statement":"O país A emite 120 milhões de toneladas de um gás em um ano e tem 60 milhões de habitantes. B emite 80 milhões de toneladas e tem 20 milhões de habitantes. Considere a mesma metodologia de inventário e não inclua emissões históricas acumuladas neste cálculo.\n\nSe A reduzir suas emissões totais em 10% e mantiver a população, qual será sua emissão anual por habitante?","version":3}},{"id":"d1434000-0000-4000-8000-000000000090","label":"G90","beforeHash":"58b6ed8cb6dd286752224c07e2f55f269ca6994368e4264226a613a7a7f7fec1","afterHash":"70a5662fefededa71cc00668bea77496637df5a9ae9925d95a2719eb818cdac4","patch":{"difficulty":"medium","statement":"Uma carga de 400 toneladas deve percorrer 300 km. A rodovia cobra R$ 0,30 por tonelada-quilômetro. A ferrovia cobra R$ 0,15 por tonelada-quilômetro e exige R$ 12.000 de transferência nos terminais. Ignore custos e prazos não informados; a transferência é cobrada uma vez para toda a carga.\n\nQual característica territorial pode impedir a escolha de um modal mesmo com custo calculado menor?","version":2}},{"id":"d1434000-0000-4000-8000-000000000091","label":"G91","beforeHash":"6b90e9c90763a04f2c8649b1e2df56db07dd48acac2cba574be1cd55cb073605","afterHash":"6914939ebc38b5d4b380ae5d67f48921299207ac013d3ed495fc8c5c46674254","patch":{"difficulty":"medium","statement":"Uma região exporta 50 milhões de reais em alimentos e 30 milhões em equipamentos. Importa 20 milhões em alimentos e 45 milhões em equipamentos. Os dados usam a mesma moeda e período e não incluem serviços, investimentos ou movimentos financeiros.\n\nQue informação seria necessária para avaliar bem-estar social associado ao comércio?","version":2}},{"id":"d1434000-0000-4000-8000-000000000092","label":"G92","beforeHash":"060222fa2f9fcb8ff41c8a05718c908b51e943d081998b1e63d967a293b634c2","afterHash":"91104c15edf30921373dd60b2ed4ebd241901e5695fbfa22a8ff3522a6413a02","patch":{"difficulty":"medium","statement":"Cinco domicílios de um setor têm rendas mensais de R$ 1.000, R$ 1.200, R$ 1.500, R$ 2.000 e R$ 9.300. Outro setor tem cinco domicílios com R$ 3.000 cada. A comparação não inclui diferenças de tamanho familiar ou custo de vida.\n\nQue informação adicional permite comparar mais adequadamente condições de vida?","version":2}},{"id":"d1434000-0000-4000-8000-000000000093","label":"G93","beforeHash":"82bd81295e019dd6717b97472e5601d8bcfa6d7fcf452dfcda917135ece9cee9","afterHash":"d58e51020abb04b0833970ec8920f4d5fcc1eb8b648c8eecd13b4daed8ec9ac1","patch":{"difficulty":"medium","statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQual comparação distingue clima de uma observação meteorológica isolada?","version":2}},{"id":"d1434000-0000-4000-8000-000000000094","label":"G94","beforeHash":"564d7770af1de9f9497b75fab5926ba592e3e7de6aa5d11cfd0a179b4e2f9ba5","afterHash":"9f022505736781d52cdf793174b174799b68d5701684df299cad18025bfcd772","patch":{"difficulty":"medium","statement":"Uma bacia recebe, no período estudado, 100 unidades de água por precipitação e 10 por entrada externa. Perde 40 por evapotranspiração e 50 por saída fluvial. No modelo, a diferença altera o armazenamento. Uma captação adicional retiraria 30 unidades, sem outras mudanças.\n\nQue medida de planejamento é mais coerente com o balanço apresentado?","version":2}},{"id":"d1434000-0000-4000-8000-000000000095","label":"G95","beforeHash":"33ad38116c3d8a62806c1391650138d65695701319114a130cfec987458a97f9","afterHash":"7d1aec637ac7070259dd669898724a92685168dc9f2e4c99ccacb6d645b3108c","patch":{"difficulty":"medium","statement":"Duas encostas têm a mesma declividade e recebem chuva semelhante. A mantém vegetação e solo permeável; B foi desmatada e tem trechos compactados. Há moradias na parte baixa de ambas. O relatório considera escoamento, erosão e exposição de pessoas, sem afirmar que um único fator determina todos os eventos.\n\nQual interpretação evita culpabilizar apenas os moradores por consequências do risco?","version":2}},{"id":"d1434000-0000-4000-8000-000000000096","label":"G96","beforeHash":"a52969307b6ffa9febbd90baac0e1b2f1da3033782ce6ee56c46a2d1203615c0","afterHash":"8ac6014980d19c77bfce45209cfebb15cf73581b6254dc0b1c954ed630d0e654","patch":{"difficulty":"easy","statement":"Uma viagem tem chegada prevista a C às 20h de terça-feira. A conexão sofre um atraso adicional de três horas e o voo seguinte mantém sua duração.\n\nQual é o novo horário previsto de chegada a C?","options":["23h de terça-feira.","17h de terça-feira.","20h de terça-feira.","1h de quarta-feira.","3h de quarta-feira."],"explanation":"O atraso adicional desloca a chegada em três horas: 20 + 3 = 23h de terça-feira. Os dois horários já se referem à mesma cidade, então não é preciso aplicar diferença de fuso.","version":2}},{"id":"d1434000-0000-4000-8000-000000000097","label":"G97","beforeHash":"41273ce1f55969d03714690e26bd313c73e77c0667024941abb657c6d7ad7949","afterHash":"5929382dc0e714dcc41f949161731433acc58b816977f50f6f58c19e5c505f41","patch":{"difficulty":"medium","statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQue informação falta para determinar a distância real precisa entre os pontos usando apenas o desenho esquemático?","version":2}},{"id":"d1434000-0000-4000-8000-000000000098","label":"G98","beforeHash":"ab07f7fc99b216eafb35513621b2a7533fd3b3d8cf47bbfc43c6ee3a7492b812","afterHash":"eeb3f6862fac1406821de16905dd814388858f2e4471c658de7f6be4be17bc7b","patch":{"difficulty":"medium","statement":"Uma região tem 12.000 ocupados e 3.000 desocupados. Pessoas desocupadas conseguirão trabalho, sem entradas ou saídas da força de trabalho.\n\nQuantas precisam conseguir trabalho para a taxa de desocupação cair para 10%?","options":["2.700 pessoas","1.500 pessoas","2.000 pessoas","300 pessoas","1.200 pessoas"],"explanation":"A força de trabalho continua em 15.000. Para uma taxa de 10%, devem restar 1.500 desocupados. Assim, 3.000 − 1.500 = 1.500 precisam conseguir trabalho; mudar de desocupado para ocupado não altera o denominador.","version":3}},{"id":"d1434000-0000-4000-8000-000000000099","label":"G99","beforeHash":"b799fd2caa0327565ff9c6eaa7735bf242f430f564226b9cb14a19a293586478","afterHash":"865ce0e7564b0751015bbfbadcfecc11c7e2899d941a37d7e79942f8a9fa02e7","patch":{"difficulty":"medium","statement":"Em uma cidade, 600 viagens usam uma linha rápida com duração média de 20 minutos; 400 usam uma linha periférica com duração média de 50 minutos. Uma intervenção reduziria a duração periférica para 35 minutos, sem mudar a quantidade de viagens. Considere médias dos dois grupos, não tempos idênticos para cada pessoa.\n\nQue dado amplia a avaliação da intervenção além do tempo médio?","version":2}},{"id":"d1434000-0000-4000-8000-000000000100","label":"G100","beforeHash":"1e14c1c8a07245cfa9d5288452428a79cf6798cfdca41edfa575c61a55cf443e","afterHash":"20268ba7448cfe9278a3b98ccb476a5b78948ee7247dcaf9972b926f2eede873","patch":{"difficulty":"medium","statement":"Um produto vendido por R$ 1.000 envolve etapas em três regiões: extração e materiais somam R$ 100; montagem soma R$ 200; desenvolvimento, marca e comercialização somam R$ 700. Para o exercício, os valores particionam o preço sem dupla contagem. Não se informa como cada etapa distribui sua receita entre salários, custos e lucros.\n\nSe a parcela de montagem crescer de R$ 200 para R$ 250 e as outras duas parcelas permanecerem iguais, qual será sua participação no novo preço?","version":3}}]'::jsonb; c jsonb; current_content jsonb; current_hash text;
begin
 perform pg_advisory_xact_lock(hashtextextended('editorial_catalog_stage45',45));
 perform 1 from public.questions where id in(select (value->>'id')::uuid from jsonb_array_elements(changes)) order by id for update;
 perform 1 from public.question_answers where question_id in(select (value->>'id')::uuid from jsonb_array_elements(changes)) order by question_id for update;
 for c in select value from jsonb_array_elements(changes) loop
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  current_hash:=encode(sha256(convert_to(current_content::text,'UTF8')),'hex');
  if current_hash is null or (current_hash<>c->>'beforeHash' and current_hash<>c->>'afterHash') then raise exception 'stage45_content_diverged: %',c->>'label';end if;
  if current_hash<>c->>'afterHash' and (
   exists(select 1 from private.practice_attempts where question_id=(c->>'id')::uuid)
   or exists(select 1 from private.guest_quiz_questions where question_id=(c->>'id')::uuid)
   or exists(select 1 from private.simulation_attempts where snapshots @> jsonb_build_array(jsonb_build_object('id',c->>'id')))) then
   raise exception 'stage45_content_used: %',c->>'label';
  end if;
 end loop;
 for c in select value from jsonb_array_elements(changes) loop
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  if encode(sha256(convert_to(current_content::text,'UTF8')),'hex')=c->>'afterHash' then continue;end if;
  update public.questions set statement=coalesce(c->'patch'->>'statement',statement),topic=coalesce(c->'patch'->>'topic',topic),difficulty=coalesce(c->'patch'->>'difficulty',difficulty),
   option_a=coalesce(c->'patch'->'options'->>0,option_a),option_b=coalesce(c->'patch'->'options'->>1,option_b),option_c=coalesce(c->'patch'->'options'->>2,option_c),
   option_d=coalesce(c->'patch'->'options'->>3,option_d),option_e=coalesce(c->'patch'->'options'->>4,option_e),
   target_exam=coalesce(c->'patch'->>'targetExam',target_exam),version=(c->'patch'->>'version')::int where id=(c->>'id')::uuid;
  update public.question_answers set correct_answer=coalesce(c->'patch'->>'correctAnswer',correct_answer),explanation=coalesce(c->'patch'->>'explanation',explanation) where question_id=(c->>'id')::uuid;
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  if encode(sha256(convert_to(current_content::text,'UTF8')),'hex')<>c->>'afterHash' then raise exception 'stage45_after_mismatch: %',c->>'label';end if;
 end loop;
end $stage45$;
